// Bukhari, Kitab al-Maghazi, in the book's order (the same list as the site's home card): [chapter, text, number]
export default [["باب غزوة العشيرة أو العسيرة", "حدثني عبد الله بن محمد، حدثنا وهب، حدثنا شعبة، عن أبي إسحاق، كنت إلى جنب زيد بن أرقم، فقيل له: \" كم غزا النبي صلى الله عليه وسلم من غزوة؟ قال: تسع عشرة \" قيل: كم غزوت أنت معه؟ قال: سبع عشرة، قلت: فأيهم كانت أول؟ قال: العسيرة أو العشير \" فذكرت لقتادة فقال: العشير", "3949"], ["باب ذكر النبي صلى الله عليه وسلم من يقتل ببدر", "حدثني أحمد بن عثمان، حدثنا شريح بن مسلمة، حدثنا إبراهيم بن يوسف، عن أبيه، عن أبي إسحاق، قال: حدثني عمرو بن ميمون، أنه سمع عبد الله بن مسعود رضي الله عنه حدث، عن سعد بن معاذ أنه قال: كان صديقا لأمية بن خلف، وكان أمية إذا مر بالمدينة نزل على سعد، وكان سعد إذا مر بمكة نزل على أمية، فلما قدم رسول الله…", "3950"], ["باب قصة غزوة بدر", "عن كعب بن مالك رضي الله عنه، يقول: لم أتخلف عن رسول الله صلى الله عليه وسلم في غزوة غزاها إلا في غزوة تبوك، غير أني تخلفت عن غزوة بدر، ولم يعاتب أحد تخلف عنها، إنما «خرج رسول الله صلى الله عليه وسلم يريد عير قريش، حتى جمع الله بينهم وبين عدوهم على غير ميعاد»", "3951"], ["باب قصة غزوة بدر", "حدثنا أبو نعيم، حدثنا إسرائيل، عن مخارق، عن طارق بن شهاب، قال: سمعت ابن مسعود، يقول: شهدت من المقداد بن الأسود مشهدا، لأن أكون صاحبه أحب إلي مما عدل به، أتى النبي صلى الله عليه وسلم وهو يدعو على المشركين، فقال: لا نقول كما قال قوم موسى: اذهب أنت وربك فقاتلا، ولكنا نقاتل عن يمينك، وعن شمالك، وبين…", "3952"], ["باب قصة غزوة بدر", "حدثني محمد بن عبد الله بن حوشب، حدثنا عبد الوهاب، حدثنا خالد، عن عكرمة، عن ابن عباس، قال: قال النبي صلى الله عليه وسلم يوم بدر: «اللهم أنشدك عهدك ووعدك، اللهم إن شئت لم تعبد» فأخذ أبو بكر بيده، فقال: حسبك، فخرج وهو يقول: ﴿سيهزم الجمع ويولون الدبر﴾", "3953"], ["باب قصة غزوة بدر", "حدثني إبراهيم بن موسى، أخبرنا هشام، أن ابن جريج، أخبرهم قال: أخبرني عبد الكريم، أنه سمع مقسما، مولى عبد الله بن الحارث، يحدث عن ابن عباس، أنه سمعه يقول: ﴿لا يستوي القاعدون من المؤمنين﴾ عن بدر، والخارجون إلى بدر \"", "3954"], ["باب عدة أصحاب بدر", "حدثنا مسلم، حدثنا شعبة، عن أبي إسحاق، عن البراء، قال: استصغرت أنا وابن عمر،", "3955"], ["باب عدة أصحاب بدر", "حدثني محمود، حدثنا وهب، عن شعبة، عن أبي إسحاق، عن البراء، قال: «استصغرت أنا وابن عمر يوم بدر، وكان المهاجرون يوم بدر نيفا على ستين، والأنصار نيفا وأربعين ومائتين»", "3956"], ["باب عدة أصحاب بدر", "عن البراء رضي الله عنه، يقول: حدثني أصحاب محمد صلى الله عليه وسلم ممن شهد بدرا: «أنهم كانوا عدة أصحاب طالوت، الذين جازوا معه النهر، بضعة عشر وثلاث مائة» قال البراء: «لا والله ما جاوز معه النهر إلا مؤمن»", "3957"], ["باب عدة أصحاب بدر", "حدثنا عبد الله بن رجاء، حدثنا إسرائيل، عن أبي إسحاق، عن البراء، قال: كنا أصحاب محمد صلى الله عليه وسلم، نتحدث: «أن عدة أصحاب بدر على عدة أصحاب طالوت الذين جاوزوا معه النهر، ولم يجاوز معه إلا مؤمن بضعة عشر وثلاث مائة»", "3958"], ["باب عدة أصحاب بدر", "عن البراء رضي الله عنه، قال: \" كنا نتحدث: أن أصحاب بدر ثلاث مائة وبضعة عشر، بعدة أصحاب طالوت، الذين جاوزوا معه النهر، وما جاوز معه إلا مؤمن \"", "3959"], ["باب دعاء النبي صلى الله عليه وسلم على كفار قريش شيبة، وعتبة، والوليد، وأبي جهل بن هشام، وهلاكهم", "عن عبد الله بن مسعود رضي الله عنه، قال: استقبل النبي صلى الله عليه وسلم الكعبة، \" فدعا على نفر من قريش: على شيبة بن ربيعة، وعتبة بن ربيعة، والوليد بن عتبة، وأبي جهل بن هشام، فأشهد بالله، لقد رأيتهم صرعى، قد غيرتهم الشمس، وكان يوما حارا \"", "3960"], ["باب قتل أبي جهل", "عن عبد الله رضي الله عنه: \" أنه أتى أبا جهل وبه رمق يوم بدر، فقال: أبو جهل: هل أعمد من رجل قتلتموه \"", "3961"], ["باب قتل أبي جهل", "عن أنس رضي الله عنه، قال: قال النبي صلى الله عليه وسلم: «من ينظر ما صنع أبو جهل». فانطلق ابن مسعود فوجده قد ضربه ابنا عفراء حتى برد، قال: أأنت، أبو جهل؟ قال: فأخذ بلحيته، قال: وهل فوق رجل قتلتموه، أو رجل قتله قومه قال أحمد بن يونس: «أنت أبو جهل»", "3962"], ["باب قتل أبي جهل", "عن أنس رضي الله عنه، قال: قال النبي صلى الله عليه وسلم يوم بدر: «من ينظر ما فعل أبو جهل». فانطلق ابن مسعود فوجده قد ضربه ابنا عفراء حتى برد فأخذ بلحيته، فقال: أنت أبا جهل؟ قال: وهل فوق رجل قتله قومه أو قال: قتلتموه، حدثني ابن المثنى، أخبرنا معاذ بن معاذ، حدثنا سليمان، أخبرنا أنس بن مالك نحوه،", "3963"], ["باب قتل أبي جهل", "حدثنا علي بن عبد الله، قال: كتبت عن يوسف بن الماجشون، عن صالح بن إبراهيم، عن أبيه، عن جده في بدر يعني حديث ابني عفراء", "3964"], ["باب قتل أبي جهل", "عن علي بن أبي طالب رضي الله عنه، أنه قال: «أنا أول من يجثو بين يدي الرحمن للخصومة يوم القيامة» وقال قيس بن عباد: وفيهم أنزلت: ﴿هذان خصمان اختصموا في ربهم﴾ قال: \" هم الذين تبارزوا يوم بدر: حمزة، وعلي، وعبيدة، أو أبو عبيدة بن الحارث، وشيبة بن ربيعة، وعتبة، والوليد بن عتبة \"", "3965"], ["باب قتل أبي جهل", "عن أبي ذر رضي الله عنه، قال: نزلت: ﴿هذان خصمان اختصموا﴾ في ربهم في ستة من قريش: علي، وحمزة، وعبيدة بن الحارث، وشيبة بن ربيعة، وعتبة بن ربيعة، والوليد بن عتبة \"", "3966"], ["باب قتل أبي جهل", "حدثنا إسحاق بن إبراهيم الصواف، حدثنا يوسف بن يعقوب، كان ينزل في بني ضبيعة، وهو مولى لبني سدوس، حدثنا سليمان التيمي، عن أبي مجلز، عن قيس بن عباد، قال: قال علي رضي الله عنه: فينا نزلت هذه الآية: ﴿هذان خصمان اختصموا في ربهم﴾", "3967"], ["باب قتل أبي جهل", "حدثنا يحيى بن جعفر، أخبرنا وكيع، عن سفيان، عن أبي هاشم، عن أبي مجلز، عن قيس بن عباد، سمعت أبا ذر رضي الله عنه يقسم: \" لنزلت هؤلاء الآيات، في هؤلاء الرهط الستة يوم بدر نحوه", "3968"], ["باب قتل أبي جهل", "حدثنا يعقوب بن إبراهيم، حدثنا هشيم، أخبرنا أبو هاشم، عن أبي مجلز، عن قيس قال: سمعت أبا ذر، يقسم قسما: إن هذه الآية: ﴿هذان خصمان اختصموا في ربهم﴾ نزلت في الذين برزوا يوم بدر: حمزة، وعلي، وعبيدة بن الحارث، وعتبة، وشيبة، ابني ربيعة، والوليد بن عتبة \"", "3969"], ["باب قتل أبي جهل", "حدثني أحمد بن سعيد أبو عبد الله، حدثنا إسحاق بن منصور، حدثنا إبراهيم بن يوسف، عن أبيه، عن أبي إسحاق، سأل رجل البراء وأنا أسمع، قال: أشهد علي بدرا قال: «بارز وظاهر»", "3970"], ["باب قتل أبي جهل", "حدثنا عبد العزيز بن عبد الله، قال: حدثني يوسف بن الماجشون، عن صالح بن إبراهيم بن عبد الرحمن بن عوف، عن أبيه، عن جده عبد الرحمن، قال: كاتبت أمية بن خلف، فلما كان يوم بدر، فذكر قتله وقتل ابنه، فقال بلال: «لا نجوت إن نجا أمية»", "3971"], ["باب قتل أبي جهل", "عن عبد الله رضي الله عنه، عن النبي صلى الله عليه وسلم: أنه قرأ والنجم فسجد بها، وسجد من معه، غير أن شيخا أخذ كفا من تراب فرفعه إلى جبهته، فقال: يكفيني هذا \" قال عبد الله: فلقد رأيته بعد قتل كافرا", "3972"], ["باب قتل أبي جهل", "أخبرني إبراهيم بن موسى، حدثنا هشام بن يوسف، عن معمر، عن هشام، عن عروة قال: «كان في الزبير ثلاث ضربات بالسيف إحداهن في عاتقه» قال: «إن كنت لأدخل أصابعي فيها» قال: «ضرب ثنتين يوم بدر، وواحدة يوم اليرموك» قال عروة: وقال لي عبد الملك بن مروان، حين قتل عبد الله بن الزبير: يا عروة، هل تعرف سيف الزبير؟…", "3973"], ["باب قتل أبي جهل", "حدثنا فروة، عن علي، عن هشام، عن أبيه، قال: «كان سيف الزبير محلى بفضة» قال هشام: وكان سيف عروة محلى بفضة", "3974"], ["باب قتل أبي جهل", "حدثنا أحمد بن محمد، حدثنا عبد الله، أخبرنا هشام بن عروة، عن أبيه، أن أصحاب رسول الله صلى الله عليه وسلم، قالوا للزبير يوم اليرموك: ألا تشد فنشد معك؟ فقال: \" إني إن شددت كذبتم، فقالوا: لا نفعل، فحمل عليهم حتى شق صفوفهم، فجاوزهم وما معه أحد، ثم رجع مقبلا، فأخذوا بلجامه، فضربوه ضربتين على عاتقه،…", "3975"], ["باب قتل أبي جهل", "حدثني عبد الله بن محمد، سمع روح بن عبادة، حدثنا سعيد بن أبي عروبة، عن قتادة، قال: ذكر لنا أنس بن مالك، عن أبي طلحة، أن نبي الله صلى الله عليه وسلم أمر يوم بدر بأربعة وعشرين رجلا من صناديد قريش، فقذفوا في طوي من أطواء بدر خبيث مخبث، وكان إذا ظهر على قوم أقام بالعرصة ثلاث ليال، فلما كان ببدر اليوم…", "3976"], ["باب قتل أبي جهل", "عن ابن عباس رضي الله عنهما: ﴿الذين بدلوا نعمة الله كفرا﴾. قال: «هم والله كفار قريش» قال عمرو: هم قريش، ومحمد صلى الله عليه وسلم نعمة الله ﴿وأحلوا قومهم دار البوار﴾ قال: «النار، يوم بدر»", "3977"], ["باب قتل أبي جهل", "حدثني عبيد بن إسماعيل، حدثنا أبو أسامة، عن هشام، عن أبيه، قال: ذكر عند عائشة رضي الله عنها، أن ابن عمر رفع إلى النبي صلى الله عليه وسلم: «إن الميت يعذب في قبره ببكاء أهله» فقالت: إنما قال رسول الله صلى الله عليه وسلم: «إنه ليعذب بخطيئته وذنبه، وإن أهله ليبكون عليه الآن»،", "3978"], ["باب قتل أبي جهل", "قالت: وذاك مثل قوله: إن رسول الله صلى الله عليه وسلم قام على القليب وفيه قتلى بدر من المشركين، فقال لهم ما قال: «إنهم ليسمعون ما أقول» إنما قال: «إنهم الآن ليعلمون أن ما كنت أقول لهم حق»، ثم قرأت ﴿إنك لا تسمع الموتى﴾، ﴿وما أنت بمسمع من في القبور﴾ يقول حين تبوءوا مقاعدهم من النار", "3979"], ["باب قتل أبي جهل", "عن ابن عمر رضي الله عنهما، قال: وقف النبي صلى الله عليه وسلم على قليب بدر فقال: «هل وجدتم ما وعد ربكم حقا» ثم قال: «إنهم الآن يسمعون ما أقول»، فذكر لعائشة، فقالت: إنما قال النبي صلى الله عليه وسلم: «إنهم الآن ليعلمون أن الذي كنت أقول لهم هو الحق» ثم قرأت ﴿إنك لا تسمع الموتى﴾ حتى قرأت الآية", "3980 و3981"], ["باب فضل من شهد بدرا", "عن أنسا رضي الله عنه، يقول: أصيب حارثة يوم بدر وهو غلام، فجاءت أمه إلى النبي صلى الله عليه وسلم فقالت: يا رسول الله، قد عرفت منزلة حارثة مني، فإن يكن في الجنة أصبر وأحتسب، وإن تك الأخرى ترى ما أصنع، فقال: «ويحك، أوهبلت، أوجنة واحدة هي، إنها جنان كثيرة، وإنه في جنة الفردوس»", "3982"], ["باب فضل من شهد بدرا", "عن علي رضي الله عنه، قال: بعثني رسول الله صلى الله عليه وسلم وأبا مرثد والزبير، وكلنا فارس، قال: «انطلقوا حتى تأتوا روضة خاخ، فإن بها امرأة من المشركين، معها كتاب من حاطب بن أبي بلتعة إلى المشركين» فأدركناها تسير على بعير لها، حيث قال رسول الله صلى الله عليه وسلم، فقلنا: الكتاب، فقالت: ما معنا…", "3983"], ["باب فضل من شهد بدرا", "عن أبي أسيد رضي الله عنه، قال: قال لنا رسول الله صلى الله عليه وسلم يوم بدر: «إذا أكثبوكم فارموهم، واستبقوا نبلكم»", "3984"], ["باب فضل من شهد بدرا", "عن أبي أسيد رضي الله عنه، قال: قال لنا رسول الله صلى الله عليه وسلم يوم بدر: «إذا أكثبوكم - يعني كثروكم - فارموهم، واستبقوا نبلكم»", "3985"], ["باب فضل من شهد بدرا", "عن البراء بن عازب رضي الله عنهما، قال: \" جعل النبي صلى الله عليه وسلم على الرماة يوم أحد عبد الله بن جبير، فأصابوا منا سبعين، وكان النبي صلى الله عليه وسلم وأصحابه أصابوا من المشركين يوم بدر أربعين ومائة، سبعين أسيرا، وسبعين قتيلا قال أبو سفيان: يوم بيوم بدر والحرب سجال", "3986"], ["باب فضل من شهد بدرا", "حدثني محمد بن العلاء، حدثنا أبو أسامة، عن بريد، عن جده أبي بردة، عن أبي موسى، أراه عن النبي صلى الله عليه وسلم، قال: «وإذا الخير ما جاء الله به من الخير بعد، وثواب الصدق الذي آتانا بعد يوم بدر»", "3987"], ["باب فضل من شهد بدرا", "حدثني يعقوب، حدثنا إبراهيم بن سعد، عن أبيه، عن جده، قال: قال عبد الرحمن بن عوف: \" إني لفي الصف يوم بدر إذ التفت فإذا عن يميني وعن يساري فتيان حديثا السن، فكأني لم آمن بمكانهما، إذ قال لي أحدهما سرا من صاحبه: يا عم أرني أبا جهل، فقلت: يا ابن أخي، وما تصنع به؟ قال: عاهدت الله إن رأيته أن أقتله أو…", "3988"], ["باب فضل من شهد بدرا", "عن أبي هريرة رضي الله عنه، قال: «بعث رسول الله صلى الله عليه وسلم عشرة عينا، وأمر عليهم عاصم بن ثابت الأنصاري جد عاصم بن عمر بن الخطاب» حتى إذا كانوا بالهدة بين عسفان، ومكة ذكروا لحي من هذيل يقال لهم بنو لحيان، فنفروا لهم بقريب من مائة رجل رام، فاقتصوا آثارهم حتى وجدوا مأكلهم التمر في منزل نزلوه،…", "3989"], ["باب فضل من شهد بدرا", "حدثنا قتيبة حدثنا ليث، عن يحيى، عن نافع، أن ابن عمر رضي الله عنهما، ذكر له: أن سعيد بن زيد بن عمرو بن نفيل، وكان بدريا، مرض في يوم جمعة، فركب إليه بعد أن تعالى النهار، واقتربت الجمعة، وترك الجمعة،", "3990"], ["باب فضل من شهد بدرا", "وقال الليث: حدثني يونس، عن ابن شهاب، قال: حدثني عبيد الله بن عبد الله بن عتبة، أن أباه كتب إلى عمر بن عبد الله بن الأرقم الزهري: يأمره أن يدخل على سبيعة بنت الحارث الأسلمية، فيسألها عن حديثها، وعن ما قال لها رسول الله صلى الله عليه وسلم حين استفتته. فكتب عمر بن عبد الله بن الأرقم، إلى عبد الله بن…", "3991"], ["باب شهود الملائكة بدرا", "حدثني إسحاق بن إبراهيم، أخبرنا جرير، عن يحيى بن سعيد، عن معاذ بن رفاعة بن رافع الزرقي، عن أبيه، وكان أبوه من أهل بدر قال: جاء جبريل إلى النبي صلى الله عليه وسلم، فقال: \" ما تعدون أهل بدر فيكم، قال: من أفضل المسلمين أو كلمة نحوها، قال: وكذلك من شهد بدرا من الملائكة \"", "3992"], ["باب شهود الملائكة بدرا", "حدثنا سليمان بن حرب، حدثنا حماد، عن يحيى ، عن معاذ بن رفاعة بن رافع، وكان رفاعة من أهل بدر، وكان رافع من أهل العقبة، فكان يقول لابنه: ما يسرني أني شهدت بدرا، بالعقبة قال: سأل جبريل النبي صلى الله عليه وسلم بهذا \"", "3993"], ["باب شهود الملائكة بدرا", "حدثنا إسحاق بن منصور، أخبرنا يزيد، أخبرنا يحيى، سمع معاذ بن رفاعة، أن ملكا سأل النبي صلى الله عليه وسلم وعن يحيى، أن يزيد بن الهاد، أخبره أنه كان معه يوم حدثه معاذ هذا الحديث فقال يزيد: فقال معاذ: «إن السائل هو جبريل عليه السلام»", "3994"], ["باب شهود الملائكة بدرا", "عن ابن عباس رضي الله عنهما، أن النبي صلى الله عليه وسلم قال يوم بدر: «هذا جبريل، آخذ برأس فرسه، عليه أداة الحرب»", "3995"], ["باب شهود الملائكة بدرا", "عن أنس رضي الله عنه، قال: «مات أبو زيد، ولم يترك عقبا، وكان بدريا»", "3996"], ["باب شهود الملائكة بدرا", "حدثنا عبد الله بن يوسف، حدثنا الليث، قال: حدثني يحيى بن سعيد، عن القاسم بن محمد، عن ابن خباب، أن أبا سعيد بن مالك الخدري رضي الله عنه، قدم من سفر، فقدم إليه أهله لحما من لحوم الأضحى، فقال: ما أنا بآكله حتى أسأل، فانطلق إلى أخيه لأمه، وكان بدريا، قتادة بن النعمان، فسأله فقال: «إنه حدث بعدك أمر، نقض…", "3997"], ["باب شهود الملائكة بدرا", "حدثني عبيد بن إسماعيل، حدثنا أبو أسامة، عن هشام بن عروة، عن أبيه، قال: قال الزبير: لقيت يوم بدر عبيدة بن سعيد بن العاص، وهو مدجج، لا يرى منه إلا عيناه، وهو يكنى أبو ذات الكرش، فقال: أنا أبو ذات الكرش، فحملت عليه بالعنزة فطعنته في عينه فمات، قال هشام: - فأخبرت: أن الزبير قال: - لقد وضعت رجلي عليه،…", "3998"], ["باب شهود الملائكة بدرا", "حدثنا أبو اليمان، أخبرنا شعيب، عن الزهري، قال: أخبرني أبو إدريس عائذ الله بن عبد الله، أن عبادة بن الصامت، وكان شهد بدرا أن رسول الله صلى الله عليه وسلم، قال: «بايعوني»", "3999"], ["باب شهود الملائكة بدرا", "حدثنا يحيى بن بكير، حدثنا الليث، عن عقيل، عن ابن شهاب، أخبرني عروة بن الزبير، عن عائشة رضي الله عنها، زوج النبي صلى الله عليه وسلم: أن أبا حذيفة، وكان ممن شهد بدرا مع رسول الله صلى الله عليه وسلم، تبنى سالما، وأنكحه بنت أخيه هند بنت الوليد بن عتبة، وهو مولى لامرأة من الأنصار، كما «تبنى رسول الله…", "4000"], ["باب شهود الملائكة بدرا", "حدثنا علي، حدثنا بشر بن المفضل، حدثنا خالد بن ذكوان، عن الربيع بنت معوذ، قالت: دخل علي النبي صلى الله عليه وسلم غداة بني علي، فجلس على فراشي كمجلسك مني، وجويريات يضربن بالدف، يندبن من قتل من آبائهن يوم بدر، حتى قالت جارية: وفينا نبي يعلم ما في غد. فقال النبي صلى الله عليه وسلم: «لا تقولي هكذا وقولي…", "4001"], ["باب شهود الملائكة بدرا", "عن ابن عباس رضي الله عنهما، قال: أخبرني أبو طلحة رضي الله عنه، صاحب رسول الله صلى الله عليه وسلم وكان قد شهد بدرا مع رسول الله صلى الله عليه وسلم، أنه قال: «لا تدخل الملائكة بيتا فيه كلب ولا صورة» يريد التماثيل التي فيها الأرواح", "4002"], ["باب شهود الملائكة بدرا", "حدثنا عبدان، أخبرنا عبد الله، أخبرنا يونس، حدثنا أحمد بن صالح، حدثنا عنبسة، حدثنا يونس، عن الزهري، أخبرنا علي بن حسين، أن حسين بن علي عليهم السلام، أخبره أن عليا قال: كانت لي شارف من نصيبي من المغنم يوم بدر، وكان النبي صلى الله عليه وسلم أعطاني مما أفاء الله عليه من الخمس يومئذ، فلما أردت أن أبتني…", "4003"], ["باب شهود الملائكة بدرا", "حدثني محمد بن عباد، أخبرنا ابن عيينة، قال: أنفذه لنا ابن الأصبهاني، سمعه من ابن معقل، أن عليا رضي الله عنه، كبر على سهل بن حنيف فقال: «إنه شهد بدرا»", "4004"], ["باب شهود الملائكة بدرا", "حدثنا أبو اليمان، أخبرنا شعيب، عن الزهري، قال: أخبرني سالم بن عبد الله، أنه سمع عبد الله بن عمر رضي الله عنهما، يحدث: أن عمر بن الخطاب، حين تأيمت حفصة بنت عمر من خنيس بن حذافة السهمي، وكان من أصحاب رسول الله صلى الله عليه وسلم قد شهد بدرا، توفي بالمدينة، قال عمر: فلقيت عثمان بن عفان، فعرضت عليه…", "4005"], ["باب شهود الملائكة بدرا", "حدثنا مسلم، حدثنا شعبة، عن عدي، عن عبد الله بن يزيد، سمع أبا مسعود البدري، عن النبي صلى الله عليه وسلم، قال: «نفقة الرجل على أهله صدقة»", "4006"], ["باب شهود الملائكة بدرا", "حدثنا أبو اليمان، أخبرنا شعيب، عن الزهري، سمعت عروة بن الزبير، يحدث عمر بن عبد العزيز في إمارته: أخر المغيرة بن شعبة العصر، وهو أمير الكوفة، فدخل أبو مسعود عقبة بن عمرو الأنصاري، جد زيد بن حسن، شهد بدرا، فقال: لقد علمت: نزل جبريل فصلى، فصلى رسول الله صلى الله عليه وسلم خمس صلوات، ثم قال: «هكذا…", "4007"], ["باب شهود الملائكة بدرا", "عن أبي مسعود البدري رضي الله عنه، قال: قال رسول الله صلى الله عليه وسلم: «الآيتان من آخر سورة البقرة، من قرأهما في ليلة كفتاه»، قال عبد الرحمن: فلقيت أبا مسعود وهو يطوف بالبيت فسألته فحدثنيه", "4008"], ["باب شهود الملائكة بدرا", "حدثنا يحيى بن بكير، حدثنا الليث، عن عقيل، عن ابن شهاب، أخبرني محمود بن الربيع، «أن عتبان بن مالك، وكان من أصحاب النبي صلى الله عليه وسلم ممن شهد بدرا من الأنصار، أنه أتى رسول الله صلى الله عليه وسلم»،", "4009"], ["باب شهود الملائكة بدرا", "حدثنا أحمد هو ابن صالح، حدثنا عنبسة، حدثنا يونس، قال: ابن شهاب، ثم سألت الحصين بن محمد، وهو أحد بني سالم وهو من سراتهم، عن حديث محمود بن الربيع، عن عتبان بن مالك فصدقه", "4010"], ["باب شهود الملائكة بدرا", "حدثنا أبو اليمان، أخبرنا شعيب، عن الزهري، قال: أخبرني عبد الله بن عامر بن ربيعة، وكان من أكبر بني عدي، وكان أبوه شهد بدرا مع النبي صلى الله عليه وسلم: أن عمر «استعمل قدامة بن مظعون على البحرين، وكان شهد بدرا، وهو خال عبد الله بن عمر، وحفصة رضي الله عنهم»", "4011"], ["باب شهود الملائكة بدرا", "حدثنا عبد الله بن محمد بن أسماء، حدثنا جويرية، عن مالك، عن الزهري، أن سالم بن عبد الله، أخبره قال: أخبر رافع بن خديج عبد الله بن عمر، أن عميه، وكانا شهدا بدرا، أخبراه أن رسول الله صلى الله عليه وسلم: \" نهى عن كراء المزارع قلت لسالم: فتكريها أنت؟ قال: «نعم، إن رافعا أكثر على نفسه»", "4012 و4013"], ["باب شهود الملائكة بدرا", "حدثنا آدم، حدثنا شعبة، عن حصين بن عبد الرحمن قال: سمعت عبد الله بن شداد بن الهاد الليثي قال: «رأيت رفاعة بن رافع الأنصاري وكان شهد بدرا»", "4014"], ["باب شهود الملائكة بدرا", "حدثنا عبدان، أخبرنا عبد الله، أخبرنا معمر، ويونس، عن الزهري، عن عروة بن الزبير، أنه أخبره أن المسور بن مخرمة، أخبره أن عمرو بن عوف، وهو حليف لبني عامر بن لؤي، وكان شهد بدرا مع النبي صلى الله عليه وسلم أن رسول الله صلى الله عليه وسلم : بعث أبا عبيدة بن الجراح إلى البحرين يأتي بجزيتها، وكان رسول الله…", "4015"], ["باب شهود الملائكة بدرا", "عن ابن عمر رضي الله عنهما، كان يقتل الحيات كلها،", "4016"], ["باب شهود الملائكة بدرا", "حتى حدثه أبو لبابة البدري أن النبي صلى الله عليه وسلم «نهى عن قتل جنان البيوت، فأمسك عنها»", "4017"], ["باب شهود الملائكة بدرا", "حدثني إبراهيم بن المنذر، حدثنا محمد بن فليح، عن موسى بن عقبة، قال ابن شهاب: حدثنا أنس بن مالك، أن رجالا من الأنصار استأذنوا رسول الله صلى الله عليه وسلم، فقالوا: ائذن لنا فلنترك لابن أختنا عباس فداءه قال: «والله لا تذرون منه درهما»", "4018"], ["باب شهود الملائكة بدرا", "حدثنا أبو عاصم، عن ابن جريج، عن الزهري، عن عطاء بن يزيد، عن عبيد الله بن عدي، عن المقداد بن الأسود * حدثني إسحاق، حدثنا يعقوب بن إبراهيم بن سعد، حدثنا ابن أخي ابن شهاب، عن عمه، قال: أخبرني عطاء بن يزيد الليثي ثم الجندعي، أن عبيد الله بن عدي بن الخيار أخبره، أن المقداد بن عمرو الكندي، وكان حليفا…", "4019"], ["باب شهود الملائكة بدرا", "عن أنس رضي الله عنه، قال: قال رسول الله صلى الله عليه وسلم يوم بدر: «من ينظر ما صنع أبو جهل» فانطلق ابن مسعود، فوجده قد ضربه ابنا عفراء حتى برد، فقال: آنت أبا جهل؟ قال ابن علية، قال سليمان: هكذا قالها أنس، قال : \" أنت أبا جهل؟ قال: وهل فوق رجل قتلتموه \" قال سليمان: أو قال: «قتله قومه» قال: وقال أبو…", "4020"], ["باب شهود الملائكة بدرا", "حدثنا موسى، حدثنا عبد الواحد، حدثنا معمر، عن الزهري، عن عبيد الله بن عبد الله، حدثني ابن عباس، عن عمر رضي الله عنهم، \" لما توفي النبي صلى الله عليه وسلم قلت لأبي بكر: انطلق بنا إلى إخواننا من الأنصار، فلقينا منهم رجلان صالحان شهدا بدرا \" فحدثت عروة بن الزبير، فقال: «هما عويم بن ساعدة ومعن بن عدي»", "4021"], ["باب شهود الملائكة بدرا", "حدثنا إسحاق بن إبراهيم، سمع محمد بن فضيل، عن إسماعيل، عن قيس، كان عطاء البدريين خمسة آلاف، خمسة آلاف وقال عمر: «لأفضلنهم على من بعدهم»", "4022"], ["باب شهود الملائكة بدرا", "حدثني إسحاق بن منصور، حدثنا عبد الرزاق، أخبرنا معمر، عن الزهري، عن محمد بن جبير، عن أبيه، قال: سمعت النبي صلى الله عليه وسلم: «يقرأ في المغرب بالطور، وذلك أول ما وقر الإيمان في قلبي»", "4023"], ["باب شهود الملائكة بدرا", "وعن الزهري، عن محمد بن جبير بن مطعم، عن أبيه، أن النبي صلى الله عليه وسلم، قال: في أسارى بدر: «لو كان المطعم بن عدي حيا، ثم كلمني في هؤلاء النتنى، لتركتهم له» وقال الليث، عن يحيى عن سعيد بن المسيب: وقعت الفتنة الأولى - يعني مقتل عثمان - فلم تبق من أصحاب بدر أحدا، ثم وقعت الفتنة الثانية، - يعني…", "4024"], ["باب شهود الملائكة بدرا", "حدثنا الحجاج بن منهال، حدثنا عبد الله بن عمر النميري، حدثنا يونس بن يزيد، قال: سمعت الزهري، قال: سمعت عروة بن الزبير، وسعيد بن المسيب، وعلقمة بن وقاص، وعبيد الله بن عبد الله، عن حديث عائشة رضي الله عنها، زوج النبي صلى الله عليه وسلم، كل حدثني طائفة من الحديث، قالت: فأقبلت أنا وأم مسطح، فعثرت أم…", "4025"], ["باب شهود الملائكة بدرا", "حدثنا إبراهيم بن المنذر، حدثنا محمد بن فليح بن سليمان، عن موسى بن عقبة، عن ابن شهاب، قال: هذه مغازي رسول الله صلى الله عليه وسلم فذكر الحديث، فقال رسول الله صلى الله عليه وسلم وهو يلقيهم «هل وجدتم ما وعدكم ربكم حقا؟» قال موسى: قال نافع: قال عبد الله: قال ناس من أصحابه: يا رسول الله، تنادي ناسا…", "4026"], ["باب شهود الملائكة بدرا", "حدثني إبراهيم بن موسى، أخبرنا هشام، عن معمر، عن هشام بن عروة، عن أبيه، عن الزبير، قال: «ضربت يوم بدر للمهاجرين بمائة سهم»", "4027"], ["باب حديث بني النضير، ومخرج رسول الله صلى الله عليه وسلم إليهم في دية الرجلين، وما أرادوا من الغدر برسول الله صلى الله عليه وسلم", "عن ابن عمر رضي الله عنهما، قال: \" حاربت النضير، وقريظة، فأجلى بني النضير، وأقر قريظة ومن عليهم، حتى حاربت قريظة، فقتل رجالهم، وقسم نساءهم وأولادهم وأموالهم بين المسلمين، إلا بعضهم لحقوا بالنبي صلى الله عليه وسلم فآمنهم وأسلموا، وأجلى يهود المدينة كلهم: بني قينقاع، وهم رهط عبد الله بن سلام، ويهود…", "4028"], ["باب حديث بني النضير، ومخرج رسول الله صلى الله عليه وسلم إليهم في دية الرجلين، وما أرادوا من الغدر برسول الله صلى الله عليه وسلم", "حدثني الحسن بن مدرك، حدثنا يحيى بن حماد، أخبرنا أبو عوانة، عن أبي بشر، عن سعيد بن جبير، قال: قلت لابن عباس: سورة الحشر، قال: «قل سورة النضير» تابعه هشيم، عن أبي بشر", "4029"], ["باب حديث بني النضير، ومخرج رسول الله صلى الله عليه وسلم إليهم في دية الرجلين، وما أرادوا من الغدر برسول الله صلى الله عليه وسلم", "عن أنس بن مالك رضي الله عنه، قال: «كان الرجل يجعل للنبي صلى الله عليه وسلم النخلات، حتى افتتح قريظة، والنضير، فكان بعد ذلك يرد عليهم»", "4030"], ["باب حديث بني النضير، ومخرج رسول الله صلى الله عليه وسلم إليهم في دية الرجلين، وما أرادوا من الغدر برسول الله صلى الله عليه وسلم", "عن ابن عمر رضي الله عنهما، قال: «حرق رسول الله صلى الله عليه وسلم نخل بني النضير وقطع، وهي البويرة» فنزلت: ﴿ما قطعتم من لينة أو تركتموها قائمة على أصولها فبإذن الله﴾", "4031"], ["باب حديث بني النضير، ومخرج رسول الله صلى الله عليه وسلم إليهم في دية الرجلين، وما أرادوا من الغدر برسول الله صلى الله عليه وسلم", "حدثني إسحاق، أخبرنا حبان، أخبرنا جويرية بن أسماء، عن نافع، عن ابن عمر رضي الله عنهما، \" أن النبي صلى الله عليه وسلم: حرق نخل بني النضير \" قال: ولها يقول حسان بن ثابت: وهان على سراة بني لؤي ... حريق بالبويرة مستطير قال: فأجابه أبو سفيان بن الحارث أدام الله ذلك من صنيع ... وحرق في نواحيها السعير،…", "4032"], ["باب حديث بني النضير، ومخرج رسول الله صلى الله عليه وسلم إليهم في دية الرجلين، وما أرادوا من الغدر برسول الله صلى الله عليه وسلم", "حدثنا أبو اليمان، أخبرنا شعيب، عن الزهري، قال: أخبرني مالك بن أوس بن الحدثان النصري، أن عمر بن الخطاب رضي الله عنه دعاه، إذ جاءه حاجبه يرفا، فقال: هل لك في عثمان، وعبد الرحمن، والزبير، وسعد يستأذنون؟ فقال: نعم فأدخلهم، فلبث قليلا ثم جاء فقال: هل لك في عباس، وعلي يستأذنان؟ قال: نعم، فلما دخلا قال…", "4033"], ["باب حديث بني النضير، ومخرج رسول الله صلى الله عليه وسلم إليهم في دية الرجلين، وما أرادوا من الغدر برسول الله صلى الله عليه وسلم", "قال: فحدثت هذا الحديث عروة بن الزبير، فقال: صدق مالك بن أوس: أنا سمعت عائشة رضي الله عنها، زوج النبي صلى الله عليه وسلم، تقول: \" أرسل أزواج النبي صلى الله عليه وسلم عثمان إلى أبي بكر، يسألنه ثمنهن مما أفاء الله على رسوله صلى الله عليه وسلم فكنت أنا أردهن، فقلت لهن: ألا تتقين الله، ألم تعلمن أن…", "4034"], ["باب حديث بني النضير، ومخرج رسول الله صلى الله عليه وسلم إليهم في دية الرجلين، وما أرادوا من الغدر برسول الله صلى الله عليه وسلم", "حدثنا إبراهيم بن موسى، أخبرنا هشام، أخبرنا معمر، عن الزهري، عن عروة، عن عائشة، أن فاطمة عليها السلام، والعباس، أتيا أبا بكر يلتمسان ميراثهما، أرضه من فدك، وسهمه من خيبر،", "4035"], ["باب حديث بني النضير، ومخرج رسول الله صلى الله عليه وسلم إليهم في دية الرجلين، وما أرادوا من الغدر برسول الله صلى الله عليه وسلم", "فقال أبو بكر: سمعت النبي صلى الله عليه وسلم، يقول: «لا نورث ما تركنا صدقة، إنما يأكل آل محمد في هذا المال» والله لقرابة رسول الله صلى الله عليه وسلم أحب إلي أن أصل من قرابتي", "4036"], ["باب قتل كعب بن الأشرف", "عن جابر بن عبد الله رضي الله عنهما، يقول: قال رسول الله صلى الله عليه وسلم: «من لكعب بن الأشرف، فإنه قد آذى الله ورسوله»، فقام محمد بن مسلمة فقال: يا رسول الله، أتحب أن أقتله؟ قال: «نعم»، قال: فأذن لي أن أقول شيئا، قال: «قل»، فأتاه محمد بن مسلمة فقال: إن هذا الرجل قد سألنا صدقة، وإنه قد عنانا وإني…", "4037"], ["باب قتل أبي رافع عبد الله بن أبي الحقيق", "حدثني إسحاق بن نصر، حدثنا يحيى بن آدم، حدثنا ابن أبي زائدة، عن أبيه، عن أبي إسحاق، عن البراء بن عازب، رضي الله عنهما، قال: «بعث رسول الله صلى الله عليه وسلم رهطا إلى أبي رافع، فدخل عليه عبد الله بن عتيك بيته ليلا وهو نائم فقتله»", "4038"], ["باب قتل أبي رافع عبد الله بن أبي الحقيق", "حدثنا يوسف بن موسى، حدثنا عبيد الله بن موسى، عن إسرائيل، عن أبي إسحاق، عن البراء قال: بعث رسول الله صلى الله عليه وسلم إلى أبي رافع اليهودي رجالا من الأنصار، فأمر عليهم عبد الله بن عتيك، وكان أبو رافع يؤذي رسول الله صلى الله عليه وسلم ويعين عليه، وكان في حصن له بأرض الحجاز، فلما دنوا منه، وقد غربت…", "4039"], ["باب قتل أبي رافع عبد الله بن أبي الحقيق", "عن البراء رضي الله عنه، قال: «بعث رسول الله صلى الله عليه وسلم إلى أبي رافع عبد الله بن عتيك، وعبد الله بن عتبة، في ناس معهم، فانطلقوا حتى دنوا من الحصن» فقال لهم عبد الله بن عتيك: امكثوا أنتم حتى أنطلق أنا فأنظر، قال: فتلطفت أن أدخل الحصن، ففقدوا حمارا لهم، قال: فخرجوا بقبس يطلبونه، قال: فخشيت أن…", "4040"], ["باب غزوة أحد", "عن ابن عباس رضي الله عنهما، قال: قال النبي صلى الله عليه وسلم يوم أحد: «هذا جبريل آخذ برأس فرسه عليه أداة الحرب»", "4041"], ["باب غزوة أحد", "حدثنا محمد بن عبد الرحيم، أخبرنا زكرياء بن عدي، أخبرنا ابن المبارك، عن حيوة، عن يزيد بن أبي حبيب، عن أبي الخير، عن عقبة بن عامر، قال: صلى رسول الله صلى الله عليه وسلم على قتلى أحد بعد ثماني سنين، كالمودع للأحياء والأموات، ثم طلع المنبر فقال: «إني بين أيديكم فرط، وأنا عليكم شهيد، وإن موعدكم الحوض،…", "4042"], ["باب غزوة أحد", "عن البراء رضي الله عنه، قال: لقينا المشركين يومئذ، وأجلس النبي صلى الله عليه وسلم جيشا من الرماة، وأمر عليهم عبد الله، وقال: «لا تبرحوا، إن رأيتمونا ظهرنا عليهم فلا تبرحوا، وإن رأيتموهم ظهروا علينا فلا تعينونا» فلما لقينا هربوا حتى رأيت النساء يشتددن في الجبل، رفعن عن سوقهن، قد بدت خلاخلهن، فأخذوا…", "4043"], ["باب غزوة أحد", "أخبرني عبد الله بن محمد، حدثنا سفيان، عن عمرو، عن جابر، قال: «اصطبح الخمر يوم أحد ناس، ثم قتلوا شهداء»", "4044"], ["باب غزوة أحد", "حدثنا عبدان، حدثنا عبد الله، أخبرنا شعبة، عن سعد بن إبراهيم، عن أبيه إبراهيم، أن عبد الرحمن بن عوف، \" أتي بطعام، وكان صائما، فقال: قتل مصعب بن عمير وهو خير مني، كفن في بردة: إن غطي رأسه بدت رجلاه، وإن غطي رجلاه بدا رأسه، وأراه قال: وقتل حمزة وهو خير مني، ثم بسط لنا من الدنيا ما بسط، أو قال: أعطينا…", "4045"], ["باب غزوة أحد", "حدثنا عبد الله بن محمد، حدثنا سفيان، عن عمرو، سمع جابر بن عبد الله رضي الله عنهما، قال: قال رجل للنبي صلى الله عليه وسلم يوم أحد أرأيت إن قتلت فأين أنا؟ قال: «في الجنة فألقى تمرات في يده، ثم قاتل حتى قتل»", "4046"], ["باب غزوة أحد", "عن خباب رضي الله عنه، قال: هاجرنا مع رسول الله صلى الله عليه وسلم نبتغي وجه الله، فوجب أجرنا على الله، ومنا من مضى، أو ذهب، لم يأكل من أجره شيئا، كان منهم مصعب بن عمير، قتل يوم أحد، لم يترك إلا نمرة , كنا إذا غطينا بها رأسه خرجت رجلاه، وإذا غطي بها رجلاه خرج رأسه، فقال لنا النبي صلى الله عليه وسلم:…", "4047"], ["باب غزوة أحد", "عن أنس رضي الله عنه، أن عمه غاب عن بدر، فقال: غبت عن أول قتال النبي صلى الله عليه وسلم، لئن أشهدني الله مع النبي صلى الله عليه وسلم ليرين الله ما أجد، فلقي يوم أحد، فهزم الناس، فقال: «اللهم إني أعتذر إليك مما صنع هؤلاء، يعني المسلمين وأبرأ إليك مما جاء به المشركون» فتقدم بسيفه فلقي سعد بن معاذ،…", "4048"], ["باب غزوة أحد", "حدثنا موسى بن إسماعيل، حدثنا إبراهيم بن سعد، حدثنا ابن شهاب، أخبرني خارجة بن زيد بن ثابت، أنه سمع زيد بن ثابت رضي الله عنه، يقول: \" فقدت آية من الأحزاب حين نسخنا المصحف، كنت أسمع رسول الله صلى الله عليه وسلم يقرأ بها فالتمسناها فوجدناها مع خزيمة بن ثابت الأنصاري ﴿من المؤمنين، رجال صدقوا ما عاهدوا…", "4049"], ["باب غزوة أحد", "عن زيد بن ثابت رضي الله عنه، قال: لما خرج النبي صلى الله عليه وسلم إلى أحد، رجع ناس ممن خرج معه، وكان أصحاب النبي صلى الله عليه وسلم فرقتين: فرقة تقول: نقاتلهم، وفرقة تقول: لا نقاتلهم، فنزلت ﴿فما لكم في المنافقين فئتين والله أركسهم بما كسبوا﴾ وقال: «إنها طيبة، تنفي الذنوب، كما تنفي النار خبث الفضة»", "4050"], ["باب {إذ همت طائفتان منكم أن تفشلا والله وليهما وعلى الله فليتوكل المؤمنون}", "عن جابر رضي الله عنه، قال: \" نزلت هذه الآية فينا: ﴿إذ همت طائفتان منكم أن تفشلا﴾ بني سلمة، وبني حارثة، وما أحب أنها لم تنزل، والله يقول: ﴿والله وليهما﴾", "4051"], ["باب {إذ همت طائفتان منكم أن تفشلا والله وليهما وعلى الله فليتوكل المؤمنون}", "حدثنا قتيبة، حدثنا سفيان، أخبرنا عمرو، عن جابر، قال: قال لي رسول الله صلى الله عليه وسلم «هل نكحت يا جابر؟» قلت: نعم، قال: «ماذا أبكرا أم ثيبا؟» قلت: لا بل ثيبا، قال «فهلا جارية تلاعبك» قلت: يا رسول الله إن أبي قتل يوم أحد، وترك تسع بنات، كن لي تسع أخوات، فكرهت أن أجمع إليهن جارية خرقاء مثلهن، ولكن…", "4052"], ["باب {إذ همت طائفتان منكم أن تفشلا والله وليهما وعلى الله فليتوكل المؤمنون}", "عن جابر بن عبد الله رضي الله عنهما، أن أباه، استشهد يوم أحد وترك عليه دينا، وترك ست بنات، فلما حضر جزاز النخل قال: أتيت رسول الله صلى الله عليه وسلم فقلت: قد علمت أن والدي قد استشهد يوم أحد وترك دينا كثيرا، وإني أحب أن يراك الغرماء، فقال: «اذهب فبيدر كل تمر على ناحية»، ففعلت ثم دعوته، فلما نظروا…", "4053"], ["باب {إذ همت طائفتان منكم أن تفشلا والله وليهما وعلى الله فليتوكل المؤمنون}", "عن سعد بن أبي وقاص رضي الله عنه، قال: «رأيت رسول الله صلى الله عليه وسلم يوم أحد، ومعه رجلان يقاتلان عنه، عليهما ثياب بيض، كأشد القتال ما رأيتهما قبل ولا بعد»", "4054"], ["باب {إذ همت طائفتان منكم أن تفشلا والله وليهما وعلى الله فليتوكل المؤمنون}", "حدثني عبد الله بن محمد، حدثنا مروان بن معاوية، حدثنا هاشم بن هاشم السعدي، قال: سمعت سعيد بن المسيب، يقول: سمعت سعد بن أبي وقاص، يقول: نثل لي النبي صلى الله عليه وسلم كنانته يوم أحد، فقال «ارم فداك أبي وأمي»", "4055"], ["باب {إذ همت طائفتان منكم أن تفشلا والله وليهما وعلى الله فليتوكل المؤمنون}", "حدثنا مسدد، حدثنا يحيى، عن يحيى بن سعيد، قال: سمعت سعيد بن المسيب، قال: سمعت سعدا، يقول: «جمع لي النبي صلى الله عليه وسلم، أبويه يوم أحد»", "4056"], ["باب {إذ همت طائفتان منكم أن تفشلا والله وليهما وعلى الله فليتوكل المؤمنون}", "حدثنا قتيبة، حدثنا ليث، عن يحيى، عن ابن المسيب، أنه قال: قال سعد بن أبي وقاص رضي الله عنه، لقد جمع لي رسول الله صلى الله عليه وسلم يوم أحد أبويه كليهما يريد حين قال: «فداك أبي وأمي» وهو يقاتل", "4057"], ["باب {إذ همت طائفتان منكم أن تفشلا والله وليهما وعلى الله فليتوكل المؤمنون}", "عن عليا رضي الله عنه، يقول: «ما سمعت النبي صلى الله عليه وسلم يجمع أبويه لأحد غير سعد»", "4058"], ["باب {إذ همت طائفتان منكم أن تفشلا والله وليهما وعلى الله فليتوكل المؤمنون}", "عن علي رضي الله عنه، قال: ما سمعت النبي صلى الله عليه وسلم جمع أبويه لأحد إلا لسعد بن مالك، فإني سمعته يقول يوم أحد: «يا سعد ارم فداك أبي وأمي»", "4059"], ["باب {إذ همت طائفتان منكم أن تفشلا والله وليهما وعلى الله فليتوكل المؤمنون}", "حدثنا موسى بن إسماعيل، عن معتمر، عن أبيه، قال زعم أبو عثمان: «أنه لم يبق مع النبي صلى الله عليه وسلم، في بعض تلك الأيام التي يقاتل فيهن، غير طلحة، وسعد» عن حديثهما", "4060 و4061"], ["باب {إذ همت طائفتان منكم أن تفشلا والله وليهما وعلى الله فليتوكل المؤمنون}", "حدثنا عبد الله بن أبي الأسود، حدثنا حاتم بن إسماعيل، عن محمد بن يوسف، قال: سمعت السائب بن يزيد، قال: صحبت عبد الرحمن بن عوف، وطلحة بن عبيد الله، والمقداد، وسعدا رضي الله عنهم فما سمعت أحدا منهم يحدث عن النبي صلى الله عليه وسلم، إلا أني سمعت طلحة: «يحدث عن يوم أحد»", "4062"], ["باب {إذ همت طائفتان منكم أن تفشلا والله وليهما وعلى الله فليتوكل المؤمنون}", "حدثني عبد الله بن أبي شيبة، حدثنا وكيع، عن إسماعيل، عن قيس، قال: «رأيت يد طلحة شلاء وقى بها النبي صلى الله عليه وسلم يوم أحد»", "4063"], ["باب {إذ همت طائفتان منكم أن تفشلا والله وليهما وعلى الله فليتوكل المؤمنون}", "عن أنس رضي الله عنه، قال: لما كان يوم أحد انهزم الناس عن النبي صلى الله عليه وسلم، وأبو طلحة بين يدي النبي صلى الله عليه وسلم مجوب عليه بحجفة له ، وكان أبو طلحة رجلا راميا شديد النزع، كسر يومئذ قوسين أو ثلاثا، وكان الرجل يمر معه بجعبة من النبل، فيقول: «انثرها لأبي طلحة» قال: ويشرف النبي صلى الله…", "4064"], ["باب {إذ همت طائفتان منكم أن تفشلا والله وليهما وعلى الله فليتوكل المؤمنون}", "عن عائشة رضي الله عنها، قالت: \" لما كان يوم أحد هزم المشركون، فصرخ إبليس لعنة الله عليه: أي عباد الله أخراكم، فرجعت أولاهم فاجتلدت هي وأخراهم، فبصر حذيفة فإذا هو بأبيه اليمان، فقال: أي عباد الله أبي أبي، قال: قالت: فوالله ما احتجزوا حتى قتلوه، فقال حذيفة: يغفر الله لكم \" قال عروة: فوالله ما زالت في…", "4065"], ["باب قول الله تعالى: {إن الذين تولوا منكم يوم التقى الجمعان إنما استزلهم الشيطان ببعض ما كسبوا ولقد عفا الله عنهم إن الله غفور حليم}", "حدثنا عبدان، أخبرنا أبو حمزة، عن عثمان بن موهب، قال: جاء رجل حج البيت، فرأى قوما جلوسا، فقال: من هؤلاء القعود؟ قالوا: هؤلاء قريش. قال: من الشيخ؟ قالوا ابن عمر، فأتاه فقال: إني سائلك عن شيء أتحدثني؟ قال: أنشدك بحرمة هذا البيت، أتعلم أن عثمان بن عفان فر يوم أحد؟ قال: نعم، قال: فتعلمه تغيب عن بدر، فلم…", "4066"], ["باب {إذ تصعدون ولا تلوون على أحد والرسول يدعوكم في أخراكم فأثابكم غما بغم لكيلا تحزنوا على ما فاتكم ولا ما أصابكم والله خبير بما تعملون} \"", "عن البراء بن عازب رضي الله عنهما، قال \" جعل النبي صلى الله عليه وسلم على الرجالة يوم أحد عبد الله بن جبير، وأقبلوا منهزمين فذاك: إذ يدعوهم الرسول في أخراهم \"", "4067"], ["باب {ثم أنزل عليكم من بعد الغم أمنة نعاسا يغشى طائفة منكم وطائفة قد أهمتهم أنفسهم يظنون بالله غير الحق ظن الجاهلية يقولون هل لنا من الأمر من شيء قل إن الأمر كله لله يخفون في أنفسهم ما لا يبدون لك يقولون لو كان لنا من الأمر شيء ما قتلنا هاهنا قل لو كنتم في بيوتكم لبرز الذين كتب عليهم القتل إلى مضاجعهم وليبتلي الله ما في صدوركم وليمحص ما في قلوبكم والله عليم بذات الصدور}", "عن أبي طلحة رضي الله عنهما، قال: «كنت فيمن تغشاه النعاس يوم أحد حتى سقط سيفي من يدي مرارا يسقط وآخذه ويسقط فآخذه»", "4068"], ["باب {ليس لك من الأمر شيء أو يتوب عليهم أو يعذبهم فإنهم ظالمون} قال حميد وثابت، عن أنس شج النبي صلى الله عليه وسلم يوم أحد فقال: «كيف يفلح قوم شجوا نبيهم» فنزلت: {ليس لك من الأمر شيء}", "حدثنا يحيى بن عبد الله السلمي، أخبرنا عبد الله، أخبرنا معمر، عن الزهري، حدثني سالم، عن أبيه، أنه سمع رسول الله صلى الله عليه وسلم إذا رفع رأسه من الركوع من الركعة الآخرة من الفجر يقول: «اللهم العن فلانا وفلانا وفلانا» بعد ما يقول «سمع الله لمن حمده، ربنا ولك الحمد» فأنزل الله: ﴿ليس لك من الأمر…", "4069"], ["باب {ليس لك من الأمر شيء أو يتوب عليهم أو يعذبهم فإنهم ظالمون} قال حميد وثابت، عن أنس شج النبي صلى الله عليه وسلم يوم أحد فقال: «كيف يفلح قوم شجوا نبيهم» فنزلت: {ليس لك من الأمر شيء}", "وعن حنظلة بن أبي سفيان، سمعت سالم بن عبد الله يقول: كان رسول الله صلى الله عليه وسلم \" يدعو على صفوان بن أمية، وسهيل بن عمرو، والحارث بن هشام فنزلت ﴿ليس لك من الأمر شيء﴾- إلى قوله - ﴿فإنهم ظالمون﴾", "4070"], ["باب ذكر أم سليط", "حدثنا يحيى بن بكير، حدثنا الليث، عن يونس، عن ابن شهاب، وقال ثعلبة بن أبي مالك: إن عمر بن الخطاب رضي الله عنه، قسم مروطا بين نساء من نساء أهل المدينة، فبقي منها مرط جيد، فقال له بعض من عنده: يا أمير المؤمنين، أعط هذا بنت رسول الله صلى الله عليه وسلم التي عندك، يريدون أم كلثوم بنت علي، فقال عمر: أم…", "4071"], ["باب قتل حمزة رضي الله عنه", "حدثني أبو جعفر محمد بن عبد الله، حدثنا حجين بن المثنى، حدثنا عبد العزيز بن عبد الله بن أبي سلمة، عن عبد الله بن الفضل، عن سليمان بن يسار، عن جعفر بن عمرو بن أمية الضمري، قال: خرجت مع عبيد الله بن عدي بن الخيار، فلما قدمنا حمص، قال لي عبيد الله هل لك في وحشي، نسأله عن قتل حمزة؟ قلت: نعم، وكان وحشي…", "4072"], ["باب ما أصاب النبي صلى الله عليه وسلم من الجراح يوم أحد", "حدثنا إسحاق بن نصر، حدثنا عبد الرزاق، عن معمر، عن همام، سمع أبا هريرة رضي الله عنه، قال: قال رسول الله صلى الله عليه وسلم: «اشتد غضب الله على قوم فعلوا بنبيه، يشير إلى رباعيته، اشتد غضب الله على رجل يقتله رسول الله صلى الله عليه وسلم في سبيل الله»", "4073"], ["باب ما أصاب النبي صلى الله عليه وسلم من الجراح يوم أحد", "عن ابن عباس رضي الله عنهما، قال: «اشتد غضب الله على من قتله النبي صلى الله عليه وسلم في سبيل الله، اشتد غضب الله على قوم دموا وجه نبي الله صلى الله عليه وسلم»", "4074"], ["باب ما أصاب النبي صلى الله عليه وسلم من الجراح يوم أحد", "حدثنا قتيبة بن سعيد، حدثنا يعقوب، عن أبي حازم، أنه سمع سهل بن سعد، وهو يسأل عن جرح رسول الله صلى الله عليه وسلم، فقال: \" أما والله إني لأعرف من كان يغسل جرح رسول الله صلى الله عليه وسلم، ومن كان يسكب الماء، وبما دووي، قال: كانت فاطمة عليها السلام بنت رسول الله صلى الله عليه وسلم تغسله، وعلي يسكب…", "4075"], ["باب ما أصاب النبي صلى الله عليه وسلم من الجراح يوم أحد", "حدثني عمرو بن علي، حدثنا أبو عاصم، حدثنا ابن جريج، عن عمرو بن دينار، عن عكرمة، عن ابن عباس، قال: «اشتد غضب الله على من قتله نبي، واشتد غضب الله على من دمى وجه رسول الله صلى الله عليه وسلم»", "4076"], ["باب {الذين استجابوا لله والرسول}", "حدثنا محمد، حدثنا أبو معاوية، عن هشام، عن أبيه، عن عائشة رضي الله عنها، ﴿الذين استجابوا لله والرسول من بعد ما أصابهم القرح﴾ للذين أحسنوا منهم واتقوا أجر عظيم، قالت لعروة: يا ابن أختي، كان أبوك منهم: الزبير، وأبو بكر، لما أصاب رسول الله صلى الله عليه وسلم ما أصاب يوم أحد، وانصرف عنه المشركون، خاف أن…", "4077"], ["باب من قتل من المسلمين يوم أحد منهم حمزة بن عبد المطلب، واليمان، وأنس بن النضر، ومصعب بن عمير", "حدثني عمرو بن علي، حدثنا معاذ بن هشام، قال: حدثني أبي، عن قتادة، قال: ما نعلم حيا من أحياء العرب أكثر شهيدا أعز يوم القيامة من الأنصار قال قتادة: وحدثنا أنس بن مالك أنه \" قتل منهم يوم أحد سبعون، ويوم بئر معونة سبعون، ويوم اليمامة سبعون، قال: «وكان بئر معونة على عهد رسول الله صلى الله عليه وسلم،…", "4078"], ["باب من قتل من المسلمين يوم أحد منهم حمزة بن عبد المطلب، واليمان، وأنس بن النضر، ومصعب بن عمير", "حدثنا قتيبة بن سعيد، حدثنا الليث، عن ابن شهاب، عن عبد الرحمن بن كعب بن مالك، أن جابر بن عبد الله رضي الله عنهما، أخبره أن رسول الله صلى الله عليه وسلم كان يجمع بين الرجلين من قتلى أحد في ثوب واحد، ثم يقول: «أيهم أكثر أخذا للقرآن» فإذا أشير له إلى أحد قدمه في اللحد، وقال: «أنا شهيد على هؤلاء يوم…", "4079"], ["باب من قتل من المسلمين يوم أحد منهم حمزة بن عبد المطلب، واليمان، وأنس بن النضر، ومصعب بن عمير", "وقال أبو الوليد، عن شعبة، عن ابن المنكدر، قال: سمعت جابرا قال: لما قتل أبي جعلت أبكي، وأكشف الثوب عن وجهه، فجعل أصحاب النبي صلى الله عليه وسلم ينهوني والنبي صلى الله عليه وسلم لم ينه، وقال النبي صلى الله عليه وسلم: \" لا تبكيه - أو: ما تبكيه - ما زالت الملائكة تظله بأجنحتها حتى رفع \"", "4080"], ["باب من قتل من المسلمين يوم أحد منهم حمزة بن عبد المطلب، واليمان، وأنس بن النضر، ومصعب بن عمير", "حدثنا محمد بن العلاء، حدثنا أبو أسامة، عن بريد بن عبد الله بن أبي بردة، عن جده أبي بردة، عن أبي موسى رضي الله عنه، - أرى - عن النبي صلى الله عليه وسلم، قال: «رأيت في رؤياي أني هززت سيفا فانقطع صدره، فإذا هو ما أصيب من المؤمنين يوم أحد، ثم هززته أخرى فعاد أحسن ما كان، فإذا هو ما جاء به الله من الفتح…", "4081"], ["باب من قتل من المسلمين يوم أحد منهم حمزة بن عبد المطلب، واليمان، وأنس بن النضر، ومصعب بن عمير", "عن خباب رضي الله عنه، قال: هاجرنا مع النبي صلى الله عليه وسلم ونحن نبتغي وجه الله، فوجب أجرنا على الله، فمنا من مضى، أو ذهب، لم يأكل من أجره شيئا، كان منهم مصعب بن عمير، قتل يوم أحد، فلم يترك إلا نمرة، كنا إذا غطينا بها رأسه خرجت رجلاه، وإذا غطي بها رجليه خرج رأسه، فقال لنا النبي صلى الله عليه…", "4082"], ["باب أحد يحبنا", "عن أنسا رضي الله عنه، أن النبي صلى الله عليه وسلم، قال: «هذا جبل يحبنا ونحبه»", "4083"], ["باب أحد يحبنا", "عن أنس بن مالك رضي الله عنه، أن رسول الله صلى الله عليه وسلم طلع له أحد فقال: «هذا جبل يحبنا ونحبه، اللهم إن إبراهيم حرم مكة وإني حرمت ما بين لابتيها»", "4084"], ["باب أحد يحبنا", "حدثني عمرو بن خالد، حدثنا الليث، عن يزيد بن أبي حبيب، عن أبي الخير، عن عقبة: أن النبي صلى الله عليه وسلم خرج يوما، فصلى على أهل أحد صلاته على الميت، ثم انصرف إلى المنبر فقال: «إني فرط لكم، وأنا شهيد عليكم، وإني لأنظر إلى حوضي الآن، وإني أعطيت مفاتيح خزائن الأرض، أو مفاتيح الأرض، وإني والله ما أخاف…", "4085"], ["باب غزوة الرجيع، ورعل، وذكوان، وبئر معونة، وحديث عضل، والقارة، وعاصم بن ثابت، وخبيب وأصحابه", "عن أبي هريرة رضي الله عنه، قال: «بعث النبي صلى الله عليه وسلم سرية عينا، وأمر عليهم عاصم بن ثابت» وهو جد عاصم بن عمر بن الخطاب، فانطلقوا حتى إذا كان بين عسفان ومكة ذكروا لحي من هذيل يقال لهم: بنو لحيان، فتبعوهم بقريب من مائة رام، فاقتصوا آثارهم حتى أتوا منزلا نزلوه، فوجدوا فيه نوى تمر تزودوه من…", "4086"], ["باب غزوة الرجيع، ورعل، وذكوان، وبئر معونة، وحديث عضل، والقارة، وعاصم بن ثابت، وخبيب وأصحابه", "حدثنا عبد الله بن محمد، حدثنا سفيان، عن عمرو، سمع جابرا، يقول: «الذي قتل خبيبا، هو أبو سروعة»", "4087"], ["باب غزوة الرجيع، ورعل، وذكوان، وبئر معونة، وحديث عضل، والقارة، وعاصم بن ثابت، وخبيب وأصحابه", "عن أنس رضي الله عنه، قال: بعث النبي صلى الله عليه وسلم سبعين رجلا لحاجة، يقال لهم القراء، فعرض لهم حيان من بني سليم، رعل، وذكوان، عند بئر يقال لها بئر معونة، فقال القوم: والله ما إياكم أردنا، إنما نحن مجتازون في حاجة للنبي صلى الله عليه وسلم، فقتلوهم «فدعا النبي صلى الله عليه وسلم عليهم شهرا في…", "4088"], ["باب غزوة الرجيع، ورعل، وذكوان، وبئر معونة، وحديث عضل، والقارة، وعاصم بن ثابت، وخبيب وأصحابه", "حدثنا مسلم، حدثنا هشام، حدثنا قتادة، عن أنس، قال: «قنت رسول الله صلى الله عليه وسلم شهرا، بعد الركوع يدعو على أحياء من العرب»", "4089"], ["باب غزوة الرجيع، ورعل، وذكوان، وبئر معونة، وحديث عضل، والقارة، وعاصم بن ثابت، وخبيب وأصحابه", "عن أنس بن مالك رضي الله عنه، أن رعلا، وذكوان، وعصية، وبني لحيان، استمدوا رسول الله صلى الله عليه وسلم على عدو، فأمدهم بسبعين من الأنصار، كنا نسميهم القراء في زمانهم، كانوا يحتطبون بالنهار، ويصلون بالليل، حتى كانوا ببئر معونة قتلوهم وغدروا بهم، فبلغ النبي صلى الله عليه وسلم «فقنت شهرا يدعو في الصبح…", "4090"], ["باب غزوة الرجيع، ورعل، وذكوان، وبئر معونة، وحديث عضل، والقارة، وعاصم بن ثابت، وخبيب وأصحابه", "حدثنا موسى بن إسماعيل، حدثنا همام، عن إسحاق بن عبد الله بن أبي طلحة، قال: حدثني أنس، أن النبي صلى الله عليه وسلم: «بعث خاله، أخ لأم سليم، في سبعين راكبا» وكان رئيس المشركين عامر بن الطفيل، خير بين ثلاث خصال، فقال: يكون لك أهل السهل ولي أهل المدر، أو أكون خليفتك، أو أغزوك بأهل غطفان بألف وألف؟ فطعن…", "4091"], ["باب غزوة الرجيع، ورعل، وذكوان، وبئر معونة، وحديث عضل، والقارة، وعاصم بن ثابت، وخبيب وأصحابه", "حدثني حبان، أخبرنا عبد الله، أخبرنا معمر، قال: حدثني ثمامة بن عبد الله بن أنس، أنه سمع أنس بن مالك رضي الله عنه، يقول: \" لما طعن حرام بن ملحان، وكان خاله يوم بئر معونة، قال: بالدم هكذا فنضحه على وجهه ورأسه، ثم قال: فزت ورب الكعبة \"", "4092"], ["باب غزوة الرجيع، ورعل، وذكوان، وبئر معونة، وحديث عضل، والقارة، وعاصم بن ثابت، وخبيب وأصحابه", "عن عائشة رضي الله عنها، قالت: استأذن النبي صلى الله عليه وسلم أبو بكر في الخروج حين اشتد عليه الأذى، فقال له: أقم فقال يا رسول الله أتطمع أن يؤذن لك؟ فكان رسول الله صلى الله عليه وسلم يقول: «إني لأرجو ذلك» قالت: فانتظره أبو بكر، فأتاه رسول الله صلى الله عليه وسلم ذات يوم ظهرا، فناداه فقال: «أخرج من…", "4093"], ["باب غزوة الرجيع، ورعل، وذكوان، وبئر معونة، وحديث عضل، والقارة، وعاصم بن ثابت، وخبيب وأصحابه", "عن أنس رضي الله عنه، قال: «قنت النبي صلى الله عليه وسلم بعد الركوع شهرا يدعو على رعل، وذكوان، ويقول عصية عصت الله ورسوله»", "4094"], ["باب غزوة الرجيع، ورعل، وذكوان، وبئر معونة، وحديث عضل، والقارة، وعاصم بن ثابت، وخبيب وأصحابه", "حدثنا يحيى بن بكير، حدثنا مالك، عن إسحاق بن عبد الله بن أبي طلحة، عن أنس بن مالك، قال: «دعا النبي صلى الله عليه وسلم على الذين قتلوا يعني أصحابه ببئر معونة ثلاثين صباحا حين يدعو على رعل، ولحيان، وعصية عصت الله ورسوله صلى الله عليه وسلم» قال أنس: \" فأنزل الله تعالى لنبيه صلى الله عليه وسلم في الذين…", "4095"], ["باب غزوة الرجيع، ورعل، وذكوان، وبئر معونة، وحديث عضل، والقارة، وعاصم بن ثابت، وخبيب وأصحابه", "حدثنا موسى بن إسماعيل، حدثنا عبد الواحد، حدثنا عاصم الأحول، قال: سألت أنس بن مالك رضي الله عنه، عن القنوت في الصلاة؟ فقال: نعم، فقلت: كان قبل الركوع أو بعده؟ قال: قبله، قلت: فإن فلانا أخبرني عنك أنك قلت بعده، قال: كذب «إنما قنت رسول الله صلى الله عليه وسلم بعد الركوع شهرا أنه كان بعث ناسا يقال لهم…", "4096"], ["باب غزوة الخندق وهي الأحزاب", "عن ابن عمر رضي الله عنهما، أن النبي صلى الله عليه وسلم: «عرضه يوم أحد وهو ابن أربع عشرة فلم يجزه، وعرضه يوم الخندق، وهو ابن خمس عشرة فأجازه»", "4097"], ["باب غزوة الخندق وهي الأحزاب", "عن سهل بن سعد رضي الله عنه، قال: كنا مع رسول الله صلى الله عليه وسلم في الخندق، وهم يحفرون ونحن ننقل التراب على أكتادنا، فقال رسول الله صلى الله عليه وسلم: «اللهم لا عيش إلا عيش الآخره، فاغفر للمهاجرين والأنصار»", "4098"], ["باب غزوة الخندق وهي الأحزاب", "عن أنسا رضي الله عنه، يقول: خرج رسول الله صلى الله عليه وسلم إلى الخندق، فإذا المهاجرون، والأنصار يحفرون في غداة باردة، فلم يكن لهم عبيد يعملون ذلك لهم، فلما رأى ما بهم من النصب والجوع، قال: «اللهم إن العيش عيش الآخره، فاغفر للأنصار والمهاجره» فقالوا مجيبين له: نحن الذين بايعوا محمدا ... على الجهاد…", "4099"], ["باب غزوة الخندق وهي الأحزاب", "عن أنس رضي الله عنه، قال: جعل المهاجرون والأنصار يحفرون الخندق حول المدينة، وينقلون التراب على متونهم، وهم يقولون نحن الذين بايعوا محمدا ... على الإسلام ما بقينا أبدا قال: يقول النبي صلى الله عليه وسلم، وهو يجيبهم: «اللهم إنه لا خير إلا خير الآخره ... فبارك في الأنصار والمهاجره» قال: يؤتون بملء كفي…", "4100"], ["باب غزوة الخندق وهي الأحزاب", "حدثنا خلاد بن يحيى، حدثنا عبد الواحد بن أيمن، عن أبيه، قال: أتيت جابرا رضي الله عنه، فقال: إنا يوم الخندق نحفر، فعرضت كدية شديدة، فجاءوا النبي صلى الله عليه وسلم فقالوا: هذه كدية عرضت في الخندق، فقال: «أنا نازل». ثم قام وبطنه معصوب بحجر، ولبثنا ثلاثة أيام لا نذوق ذواقا، فأخذ النبي صلى الله عليه…", "4101"], ["باب غزوة الخندق وهي الأحزاب", "حدثني عمرو بن علي، حدثنا أبو عاصم، أخبرنا حنظلة بن أبي سفيان، أخبرنا سعيد بن ميناء، قال: سمعت جابر بن عبد الله، رضي الله عنهما قال: لما حفر الخندق رأيت بالنبي صلى الله عليه وسلم خمصا شديدا، فانكفأت إلى امرأتي، فقلت: هل عندك شيء؟ فإني رأيت برسول الله صلى الله عليه وسلم خمصا شديدا، فأخرجت إلي جرابا…", "4102"], ["باب غزوة الخندق وهي الأحزاب", "عن عائشة رضي الله عنها: ﴿إذ جاءوكم من فوقكم ومن أسفل منكم. وإذ زاغت الأبصار﴾ قالت: كان ذاك يوم الخندق", "4103"], ["باب غزوة الخندق وهي الأحزاب", "عن البراء رضي الله عنه، قال: كان النبي صلى الله عليه وسلم ينقل التراب يوم الخندق، حتى أغمر بطنه، أو اغبر بطنه، يقول: «والله لولا الله ما اهتدينا، ولا تصدقنا ولا صلينا، فأنزلن سكينة علينا، وثبت الأقدام إن لاقينا، إن الألى قد بغوا علينا، إذا أرادوا فتنة أبينا» ورفع بها صوته: «أبينا أبينا»", "4104"], ["باب غزوة الخندق وهي الأحزاب", "عن ابن عباس رضي الله عنهما، عن النبي صلى الله عليه وسلم قال: «نصرت بالصبا، وأهلكت عاد بالدبور»", "4105"], ["باب غزوة الخندق وهي الأحزاب", "حدثني أحمد بن عثمان، حدثنا شريح بن مسلمة، قال: حدثني إبراهيم بن يوسف، قال: حدثني أبي، عن أبي إسحاق، قال: سمعت البراء يحدث، قال: لما كان يوم الأحزاب، وخندق رسول الله صلى الله عليه وسلم، رأيته ينقل من تراب الخندق، حتى وارى عني الغبار جلدة بطنه، وكان كثير الشعر، فسمعته يرتجز بكلمات ابن رواحة، وهو ينقل…", "4106"], ["باب غزوة الخندق وهي الأحزاب", "حدثني عبدة بن عبد الله، حدثنا عبد الصمد، عن عبد الرحمن هو ابن عبد الله بن دينار، عن أبيه، أن ابن عمر رضي الله عنهما، قال: «أول يوم شهدته يوم الخندق»", "4107"], ["باب غزوة الخندق وهي الأحزاب", "حدثني إبراهيم بن موسى، أخبرنا هشام، عن معمر، عن الزهري، عن سالم، عن ابن عمر، قال: وأخبرني ابن طاوس، عن عكرمة بن خالد، عن ابن عمر، قال: \" دخلت على حفصة ونسواتها تنطف، قلت: قد كان من أمر الناس ما ترين، فلم يجعل لي من الأمر شيء، فقالت: الحق فإنهم ينتظرونك، وأخشى أن يكون في احتباسك عنهم فرقة، فلم تدعه…", "4108"], ["باب غزوة الخندق وهي الأحزاب", "حدثنا أبو نعيم، حدثنا سفيان، عن أبي إسحاق، عن سليمان بن صرد، قال: قال النبي صلى الله عليه وسلم يوم الأحزاب: «نغزوهم، ولا يغزوننا»", "4109"], ["باب غزوة الخندق وهي الأحزاب", "حدثني عبد الله بن محمد، حدثنا يحيى بن آدم، حدثنا إسرائيل، سمعت أبا إسحاق، يقول: سمعت سليمان بن صرد، يقول: سمعت النبي صلى الله عليه وسلم، يقول: حين أجلى الأحزاب عنه: «الآن نغزوهم ولا يغزوننا، نحن نسير إليهم»", "4110"], ["باب غزوة الخندق وهي الأحزاب", "عن علي رضي الله عنه، عن النبي صلى الله عليه وسلم، أنه قال يوم الخندق: «ملأ الله عليهم بيوتهم وقبورهم نارا، كما شغلونا عن صلاة الوسطى حتى غابت الشمس»", "4111"], ["باب غزوة الخندق وهي الأحزاب", "حدثنا المكي بن إبراهيم، حدثنا هشام، عن يحيى، عن أبي سلمة، عن جابر بن عبد الله، أن عمر بن الخطاب رضي الله عنه، جاء يوم الخندق بعد ما غربت الشمس، جعل يسب كفار قريش، وقال: يا رسول الله، ما كدت أن أصلي، حتى كادت الشمس أن تغرب، قال النبي صلى الله عليه وسلم: «والله ما صليتها» فنزلنا مع النبي صلى الله…", "4112"], ["باب غزوة الخندق وهي الأحزاب", "حدثنا محمد بن كثير، أخبرنا سفيان، عن ابن المنكدر، قال: سمعت جابرا، يقول: قال رسول الله صلى الله عليه وسلم يوم الأحزاب: «من يأتينا بخبر القوم» فقال الزبير: أنا، ثم قال: «من يأتينا بخبر القوم». فقال الزبير: أنا، ثم قال: «من يأتينا بخبر القوم» فقال الزبير: أنا، ثم قال: «إن لكل نبي حواري، وإن حواري…", "4113"], ["باب غزوة الخندق وهي الأحزاب", "عن أبي هريرة رضي الله عنه: أن رسول الله صلى الله عليه وسلم كان يقول: «لا إله إلا الله وحده، أعز جنده، ونصر عبده، وغلب الأحزاب وحده، فلا شيء بعده»", "4114"], ["باب غزوة الخندق وهي الأحزاب", "عن عبد الله بن أبي أوفى رضي الله عنهما، يقول: دعا رسول الله صلى الله عليه وسلم على الأحزاب فقال: «اللهم منزل الكتاب، سريع الحساب، اهزم الأحزاب، اللهم اهزمهم وزلزلهم»", "4115"], ["باب غزوة الخندق وهي الأحزاب", "عن عبد الله رضي الله عنه، أن رسول الله صلى الله عليه وسلم كان إذا قفل من الغزو أو الحج أو العمرة يبدأ فيكبر ثلاث مرار، ثم يقول: «لا إله إلا الله، وحده لا شريك له، له الملك، وله الحمد، وهو على كل شيء قدير. آيبون تائبون، عابدون ساجدون، لربنا حامدون صدق الله وعده، ونصر عبده، وهزم الأحزاب وحده»", "4116"], ["باب مرجع النبي صلى الله عليه وسلم من الأحزاب، ومخرجه إلى بني قريظة ومحاصرته إياهم", "عن عائشة رضي الله عنها، قالت: لما رجع النبي صلى الله عليه وسلم من الخندق، ووضع السلاح واغتسل، أتاه جبريل عليه السلام، فقال: \" قد وضعت السلاح؟ والله ما وضعناه، فاخرج إليهم قال: فإلى أين؟ قال: ها هنا، وأشار إلى بني قريظة، فخرج النبي صلى الله عليه وسلم إليهم \"", "4117"], ["باب مرجع النبي صلى الله عليه وسلم من الأحزاب، ومخرجه إلى بني قريظة ومحاصرته إياهم", "عن أنس رضي الله عنه، قال: «كأني أنظر إلى الغبار ساطعا في زقاق بني غنم، موكب جبريل حين سار رسول الله صلى الله عليه وسلم إلى بني قريظة»", "4118"], ["باب مرجع النبي صلى الله عليه وسلم من الأحزاب، ومخرجه إلى بني قريظة ومحاصرته إياهم", "عن ابن عمر رضي الله عنهما، قال: قال النبي صلى الله عليه وسلم يوم الأحزاب: «لا يصلين أحد العصر إلا في بني قريظة» فأدرك بعضهم العصر في الطريق، فقال بعضهم: لا نصلي حتى نأتيها، وقال بعضهم: بل نصلي، لم يرد منا ذلك، فذكر ذلك للنبي صلى الله عليه وسلم فلم يعنف واحدا منهم", "4119"], ["باب مرجع النبي صلى الله عليه وسلم من الأحزاب، ومخرجه إلى بني قريظة ومحاصرته إياهم", "عن أنس رضي الله عنه، قال: كان الرجل يجعل للنبي صلى الله عليه وسلم النخلات، حتى افتتح قريظة والنضير، وإن أهلي أمروني أن آتي النبي صلى الله عليه وسلم، فأسأله الذين كانوا أعطوه أو بعضه، وكان النبي صلى الله عليه وسلم قد أعطاه أم أيمن، فجاءت أم أيمن فجعلت الثوب في عنقي، تقول: كلا والذي لا إله إلا هو لا…", "4120"], ["باب مرجع النبي صلى الله عليه وسلم من الأحزاب، ومخرجه إلى بني قريظة ومحاصرته إياهم", "عن أبا سعيد الخدري رضي الله عنه، يقول: نزل أهل قريظة على حكم سعد بن معاذ، فأرسل النبي صلى الله عليه وسلم إلى سعد فأتى على حمار، فلما دنا من المسجد قال للأنصار: «قوموا إلى سيدكم، أو خيركم». فقال: «هؤلاء نزلوا على حكمك». فقال: تقتل مقاتلتهم، وتسبي ذراريهم، قال: «قضيت بحكم الله» وربما قال: «بحكم الملك»", "4121"], ["باب مرجع النبي صلى الله عليه وسلم من الأحزاب، ومخرجه إلى بني قريظة ومحاصرته إياهم", "عن عائشة رضي الله عنها، قالت: أصيب سعد يوم الخندق، رماه رجل من قريش، يقال له حبان بن العرقة رماه في الأكحل، فضرب النبي صلى الله عليه وسلم خيمة في المسجد ليعوده من قريب، فلما رجع رسول الله صلى الله عليه وسلم من الخندق وضع السلاح واغتسل، فأتاه جبريل عليه السلام وهو ينفض رأسه من الغبار، فقال: \" قد…", "4122"], ["باب مرجع النبي صلى الله عليه وسلم من الأحزاب، ومخرجه إلى بني قريظة ومحاصرته إياهم", "حدثنا الحجاج بن منهال، أخبرنا شعبة، قال: أخبرني عدي، أنه سمع البراء رضي الله عنه، قال: قال النبي صلى الله عليه وسلم لحسان: «اهجهم - أو هاجهم - وجبريل معك»", "4123"], ["باب مرجع النبي صلى الله عليه وسلم من الأحزاب، ومخرجه إلى بني قريظة ومحاصرته إياهم", "وزاد إبراهيم بن طهمان، عن الشيباني، عن عدي بن ثابت، عن البراء بن عازب قال: قال رسول الله صلى الله عليه وسلم يوم قريظة لحسان بن ثابت: «اهج المشركين، فإن جبريل معك»", "4124"], ["باب غزوة ذات الرقاع", "عن جابر بن عبد الله رضي الله عنهما: «أن النبي صلى الله عليه وسلم صلى بأصحابه في الخوف في غزوة السابعة، غزوة ذات الرقاع» قال ابن عباس صلى النبي صلى الله عليه وسلم الخوف بذي قرد", "4125"], ["باب غزوة ذات الرقاع", "وقال بكر بن سوادة: حدثني زياد بن نافع، عن أبي موسى، أن جابرا حدثهم: «صلى النبي صلى الله عليه وسلم بهم يوم محارب، وثعلبة»", "4126"], ["باب غزوة ذات الرقاع", "وقال ابن إسحاق: سمعت وهب بن كيسان، سمعت جابرا، خرج النبي صلى الله عليه وسلم إلى ذات الرقاع من نخل، فلقي جمعا من غطفان، فلم يكن قتال، وأخاف الناس بعضهم بعضا، فصلى النبي صلى الله عليه وسلم ركعتي الخوف \" وقال يزيد: عن سلمة، غزوت مع النبي صلى الله عليه وسلم يوم القرد", "4127"], ["باب غزوة ذات الرقاع", "عن أبي موسى رضي الله عنه، قال: «خرجنا مع النبي صلى الله عليه وسلم في غزاة ونحن ستة نفر، بيننا بعير نعتقبه، فنقبت أقدامنا، ونقبت قدماي، وسقطت أظفاري، وكنا نلف على أرجلنا الخرق، فسميت غزوة ذات الرقاع، لما كنا نعصب من الخرق على أرجلنا»، وحدث أبو موسى بهذا ثم كره ذاك، قال: ما كنت أصنع بأن أذكره، كأنه…", "4128"], ["باب غزوة ذات الرقاع", "حدثنا قتيبة بن سعيد ، عن مالك، عن يزيد بن رومان، عن صالح بن خوات، عمن شهد \" رسول الله صلى الله عليه وسلم يوم ذات الرقاع صلى صلاة الخوف: أن طائفة صفت معه، وطائفة وجاه العدو، فصلى بالتي معه ركعة، ثم ثبت قائما، وأتموا لأنفسهم ثم انصرفوا، فصفوا وجاه العدو، وجاءت الطائفة الأخرى فصلى بهم الركعة التي بقيت…", "4129"], ["باب غزوة ذات الرقاع", "وقال معاذ: حدثنا هشام، عن أبي الزبير، عن جابر، قال: كنا مع النبي صلى الله عليه وسلم بنخل، فذكر صلاة الخوف، قال مالك: «وذلك أحسن ما سمعت في صلاة الخوف» تابعه الليث، عن هشام، عن زيد بن أسلم، أن القاسم بن محمد، حدثه: صلى النبي صلى الله عليه وسلم في غزوة بني أنمار", "4130"], ["باب غزوة ذات الرقاع", "حدثنا مسدد، حدثنا يحيى بن سعيد القطان، عن يحيى بن سعيد الأنصاري، عن القاسم بن محمد، عن صالح بن خوات، عن سهل بن أبي حثمة، قال: «يقوم الإمام مستقبل القبلة، وطائفة منهم معه، وطائفة من قبل العدو، وجوههم إلى العدو، فيصلي بالذين معه ركعة، ثم يقومون فيركعون لأنفسهم ركعة، ويسجدون سجدتين في مكانهم، ثم يذهب…", "4131"], ["باب غزوة ذات الرقاع", "عن ابن عمر رضي الله عنهما، قال: «غزوت مع رسول الله صلى الله عليه وسلم قبل نجد، فوازينا العدو، فصاففنا لهم»", "4132"], ["باب غزوة ذات الرقاع", "حدثنا مسدد، حدثنا يزيد بن زريع، حدثنا معمر، عن الزهري، عن سالم بن عبد الله بن عمر، عن أبيه، «أن رسول الله صلى الله عليه وسلم صلى بإحدى الطائفتين، والطائفة الأخرى مواجهة العدو، ثم انصرفوا فقاموا في مقام أصحابهم فجاء أولئك، فصلى بهم ركعة، ثم سلم عليهم، ثم قام هؤلاء فقضوا ركعتهم، وقام هؤلاء فقضوا…", "4133"], ["باب غزوة ذات الرقاع", "حدثنا أبو اليمان، حدثنا شعيب، عن الزهري، قال: حدثني سنان، وأبو سلمة، أن جابرا أخبر: أنه «غزا مع رسول الله صلى الله عليه وسلم قبل نجد»", "4134"], ["باب غزوة ذات الرقاع", "حدثنا إسماعيل، قال: حدثني أخي، عن سليمان، عن محمد بن أبي عتيق، عن ابن شهاب، عن سنان بن أبي سنان الدؤلي، عن جابر بن عبد الله رضي الله عنهما، أخبره: أنه غزا مع رسول الله صلى الله عليه وسلم قبل نجد، فلما قفل رسول الله صلى الله عليه وسلم قفل معه، فأدركتهم القائلة في واد كثير العضاه، فنزل رسول الله صلى…", "4135"], ["باب غزوة ذات الرقاع", "وقال أبان، حدثنا يحيى بن أبي كثير، عن أبي سلمة، عن جابر، قال: كنا مع النبي صلى الله عليه وسلم بذات الرقاع، فإذا أتينا على شجرة ظليلة تركناها للنبي صلى الله عليه وسلم، فجاء رجل من المشركين وسيف النبي صلى الله عليه وسلم معلق بالشجرة، فاخترطه، فقال: تخافني؟ قال: «لا»، قال: فمن يمنعك مني؟ قال: «الله»…", "4136"], ["باب غزوة ذات الرقاع", "وقال أبو الزبير، عن جابر، كنا مع النبي صلى الله عليه وسلم بنخل، فصلى الخوف، وقال أبو هريرة: «صليت مع النبي صلى الله عليه وسلم غزوة نجد صلاة الخوف» وإنما جاء أبو هريرة إلى النبي صلى الله عليه وسلم أيام خيبر \"", "4137"], ["باب غزوة بني المصطلق، من خزاعة، وهي غزوة المريسيع", "حدثنا قتيبة بن سعيد، أخبرنا إسماعيل بن جعفر، عن ربيعة بن أبي عبد الرحمن، عن محمد بن يحيى بن حبان، عن ابن محيريز، أنه قال: دخلت المسجد، فرأيت أبا سعيد الخدري فجلست إليه، فسألته عن العزل، قال أبو سعيد: خرجنا مع رسول الله صلى الله عليه وسلم في غزوة بني المصطلق، فأصبنا سبيا من سبي العرب، فاشتهينا…", "4138"], ["باب غزوة بني المصطلق، من خزاعة، وهي غزوة المريسيع", "حدثنا محمود، حدثنا عبد الرزاق، أخبرنا معمر، عن الزهري، عن أبي سلمة، عن جابر بن عبد الله، قال: غزونا مع رسول الله صلى الله عليه وسلم غزوة نجد، فلما أدركته القائلة، وهو في واد كثير العضاه، فنزل تحت شجرة واستظل بها وعلق سيفه، فتفرق الناس في الشجر يستظلون، وبينا نحن كذلك إذ دعانا رسول الله صلى الله…", "4139"], ["باب غزوة أنمار", "حدثنا آدم، حدثنا ابن أبي ذئب، حدثنا عثمان بن عبد الله بن سراقة، عن جابر بن عبد الله الأنصاري، قال: «رأيت النبي صلى الله عليه وسلم في غزوة أنمار يصلي على راحلته متوجها قبل المشرق متطوعا»", "4140"], ["باب حديث الإفك والأفك، بمنزلة النجس والنجس", "حدثنا عبد العزيز بن عبد الله، حدثنا إبراهيم بن سعد، عن صالح، عن ابن شهاب، قال: حدثني عروة بن الزبير، وسعيد بن المسيب، وعلقمة بن وقاص، وعبيد الله بن عبد الله بن عتبة بن مسعود، عن عائشة رضي الله عنها، زوج النبي صلى الله عليه وسلم، حين قال لها: أهل الإفك ما قالوا، وكلهم حدثني طائفة من حديثها، وبعضهم…", "4141"], ["باب حديث الإفك والأفك، بمنزلة النجس والنجس", "حدثني عبد الله بن محمد، قال: أملى علي هشام بن يوسف من حفظه، أخبرنا معمر، عن الزهري، قال: قال لي الوليد بن عبد الملك: أبلغك أن عليا، كان فيمن قذف عائشة؟ قلت: لا، ولكن قد أخبرني رجلان من قومك، أبو سلمة بن عبد الرحمن، وأبو بكر بن عبد الرحمن بن الحارث، أن عائشة رضي الله عنها قالت لهما: \" كان علي مسلما…", "4142"], ["باب حديث الإفك والأفك، بمنزلة النجس والنجس", "حدثنا موسى بن إسماعيل، حدثنا أبو عوانة، عن حصين، عن أبي وائل، قال: حدثني مسروق بن الأجدع، قال: حدثتني أم رومان، وهي أم عائشة رضي الله عنهما قالت بينا أنا قاعدة أنا وعائشة، إذ ولجت امرأة من الأنصار فقالت: فعل الله بفلان وفعل، فقالت أم رومان: وما ذاك؟ قالت: ابني فيمن حدث الحديث، قالت: وما ذاك؟ قالت:…", "4143"], ["باب حديث الإفك والأفك، بمنزلة النجس والنجس", "عن عائشة رضي الله عنها: \" كانت تقرأ: إذ تلقونه بألسنتكم، وتقول: الولق الكذب \" قال ابن أبي مليكة: «وكانت أعلم من غيرها بذلك لأنه نزل فيها»", "4144"], ["باب حديث الإفك والأفك، بمنزلة النجس والنجس", "حدثنا عثمان بن أبي شيبة، حدثنا عبدة، عن هشام، عن أبيه، قال: ذهبت أسب حسان عند عائشة، فقالت: لا تسبه، فإنه كان ينافح عن رسول الله صلى الله عليه وسلم، وقالت عائشة: استأذن النبي صلى الله عليه وسلم في هجاء المشركين، قال «كيف بنسبي؟» قال: لأسلنك منهم كما تسل الشعرة من العجين وقال محمد حدثنا عثمان بن…", "4145"], ["باب حديث الإفك والأفك، بمنزلة النجس والنجس", "حدثني بشر بن خالد، أخبرنا محمد بن جعفر، عن شعبة، عن سليمان، عن أبي الضحى، عن مسروق، قال: دخلنا على عائشة رضي الله عنها، وعندها حسان بن ثابت ينشدها شعرا، يشبب بأبيات له: وقال: حصان رزان ما تزن بريبة وتصبح غرثى من لحوم الغوافل، فقالت له عائشة: لكنك لست كذلك، قال مسروق: فقلت لها لم تأذني له أن يدخل…", "4146"], ["باب غزوة الحديبية", "عن زيد بن خالد رضي الله عنه، قال: خرجنا مع رسول الله صلى الله عليه وسلم عام الحديبية، فأصابنا مطر ذات ليلة، فصلى لنا رسول الله صلى الله عليه وسلم الصبح، ثم أقبل علينا فقال: «أتدرون ماذا قال ربكم؟». قلنا: الله ورسوله أعلم، فقال: \" قال الله: أصبح من عبادي مؤمن بي وكافر بي، فأما من قال: مطرنا برحمة…", "4147"], ["باب غزوة الحديبية", "حدثنا هدبة بن خالد، حدثنا همام، عن قتادة، أن أنسا رضي الله عنه، أخبره قال: \" اعتمر رسول الله صلى الله عليه وسلم أربع عمر، كلهن في ذي القعدة، إلا التي كانت مع حجته: عمرة من الحديبية في ذي القعدة، وعمرة من العام المقبل في ذي القعدة، وعمرة من الجعرانة، حيث قسم غنائم حنين في ذي القعدة، وعمرة مع حجته \"", "4148"], ["باب غزوة الحديبية", "حدثنا سعيد بن الربيع، حدثنا علي بن المبارك، عن يحيى، عن عبد الله بن أبي قتادة، أن أباه، حدثه قال: انطلقنا مع النبي صلى الله عليه وسلم عام الحديبية، فأحرم أصحابه ولم أحرم \"", "4149"], ["باب غزوة الحديبية", "عن البراء رضي الله عنه، قال: تعدون أنتم الفتح فتح مكة، وقد كان فتح مكة فتحا، ونحن نعد الفتح بيعة الرضوان يوم الحديبية، كنا مع النبي صلى الله عليه وسلم أربع عشرة مائة، والحديبية بئر، فنزحناها فلم نترك فيها قطرة، فبلغ ذلك النبي صلى الله عليه وسلم فأتاها، فجلس على شفيرها ثم «دعا بإناء من ماء فتوضأ، ثم…", "4150"], ["باب غزوة الحديبية", "حدثني فضل بن يعقوب، حدثنا الحسن بن محمد بن أعين أبو علي الحراني، حدثنا زهير، حدثنا أبو إسحاق، قال: أنبأنا البراء بن عازب رضي الله عنهما، أنهم كانوا مع رسول الله صلى الله عليه وسلم يوم الحديبية ألفا وأربع مائة أو أكثر، فنزلوا على بئر فنزحوها، فأتوا رسول الله صلى الله عليه وسلم، فأتى البئر وقعد على…", "4151"], ["باب غزوة الحديبية", "عن جابر رضي الله عنه، قال: عطش الناس يوم الحديبية، ورسول الله صلى الله عليه وسلم بين يديه ركوة فتوضأ منها، ثم أقبل الناس نحوه، فقال رسول الله صلى الله عليه وسلم: «ما لكم؟» قالوا يا رسول الله: ليس عندنا ماء نتوضأ به ولا نشرب، إلا ما في ركوتك، قال: «فوضع النبي صلى الله عليه وسلم يده في الركوة، فجعل…", "4152"], ["باب غزوة الحديبية", "حدثنا الصلت بن محمد، حدثنا يزيد بن زريع، عن سعيد، عن قتادة، قلت لسعيد بن المسيب: بلغني أن جابر بن عبد الله كان يقول: «كانوا أربع عشرة مائة»، فقال لي سعيد: حدثني جابر: «كانوا خمس عشرة مائة، الذين بايعوا النبي صلى الله عليه وسلم يوم الحديبية» قال أبو داود، حدثنا قرة، عن قتادة تابعه محمد بن بشار،…", "4153"], ["باب غزوة الحديبية", "عن جابر بن عبد الله رضي الله عنهما، قال: قال لنا رسول الله صلى الله عليه وسلم يوم الحديبية: «أنتم خير أهل الأرض» وكنا ألفا وأربع مائة، ولو كنت أبصر اليوم لأريتكم مكان الشجرة تابعه الأعمش، سمع سالما، سمع جابرا ألفا وأربع مائة،", "4154"], ["باب غزوة الحديبية", "عن عبد الله بن أبي أوفى رضي الله عنهما، كان أصحاب الشجرة ألفا وثلاث مائة، وكانت أسلم، ثمن المهاجرين \"", "4155"], ["باب غزوة الحديبية", "حدثنا إبراهيم بن موسى، أخبرنا عيسى، عن إسماعيل، عن قيس، أنه سمع مرداسا الأسلمي، يقول: وكان من أصحاب الشجرة: «يقبض الصالحون، الأول فالأول، وتبقى حفالة كحفالة التمر والشعير، لا يعبأ الله بهم شيئا»", "4156"], ["باب غزوة الحديبية", "حدثنا علي بن عبد الله، حدثنا سفيان، عن الزهري، عن عروة، عن مروان، والمسور بن مخرمة، قالا: «خرج النبي صلى الله عليه وسلم عام الحديبية في بضع عشرة مائة من أصحابه، فلما كان بذي الحليفة قلد الهدي، وأشعر وأحرم منها» لا أحصي كم سمعته من سفيان، حتى سمعته يقول: لا أحفظ من الزهري الإشعار والتقليد، فلا أدري،…", "4157 و4158"], ["باب غزوة الحديبية", "حدثنا الحسن بن خلف، قال: حدثنا إسحاق بن يوسف، عن أبي بشر ورقاء، عن ابن أبي نجيح، عن مجاهد، قال: حدثني عبد الرحمن بن أبي ليلى، عن كعب بن عجرة، أن رسول الله صلى الله عليه وسلم رآه وقمله يسقط على وجهه، فقال: «أيؤذيك هوامك؟» قال: نعم، فأمره رسول الله صلى الله عليه وسلم أن يحلق، وهو بالحديبية، لم يبين…", "4159"], ["باب غزوة الحديبية", "حدثنا إسماعيل بن عبد الله، قال: حدثني مالك، عن زيد بن أسلم، عن أبيه، قال: خرجت مع عمر بن الخطاب رضي الله عنه إلى السوق، فلحقت عمر امرأة شابة، فقالت: يا أمير المؤمنين، هلك زوجي وترك صبية صغارا، والله ما ينضجون كراعا، ولا لهم زرع ولا ضرع، وخشيت أن تأكلهم الضبع، وأنا بنت خفاف بن إيماء الغفاري، «وقد…", "4160 و4161"], ["باب غزوة الحديبية", "حدثني محمد بن رافع، حدثنا شبابة بن سوار أبو عمرو الفزاري، حدثنا شعبة، عن قتادة، عن سعيد بن المسيب، عن أبيه، قال: «لقد رأيت الشجرة، ثم أتيتها بعد فلم أعرفها» قال محمود ثم أنسيتها بعد", "4162"], ["باب غزوة الحديبية", "حدثنا محمود، حدثنا عبيد الله، عن إسرائيل، عن طارق بن عبد الرحمن، قال: انطلقت حاجا، فمررت بقوم يصلون، قلت: ما هذا المسجد؟ قالوا: هذه الشجرة، حيث بايع رسول الله صلى الله عليه وسلم بيعة الرضوان، فأتيت سعيد بن المسيب فأخبرته، فقال سعيد، حدثني أبي \" أنه كان فيمن بايع رسول الله صلى الله عليه وسلم تحت…", "4163"], ["باب غزوة الحديبية", "حدثنا موسى، حدثنا أبو عوانة، حدثنا طارق، عن سعيد بن المسيب، عن أبيه، «أنه كان ممن بايع تحت الشجرة، فرجعنا إليها العام المقبل فعميت علينا»", "4164"], ["باب غزوة الحديبية", "حدثنا قبيصة، حدثنا سفيان، عن طارق، قال: ذكرت عند سعيد بن المسيب الشجرة فضحك، فقال: أخبرني أبي: «وكان شهدها»", "4165"], ["باب غزوة الحديبية", "حدثنا آدم بن أبي إياس، حدثنا شعبة، عن عمرو بن مرة، قال: سمعت عبد الله بن أبي أوفى، وكان من أصحاب الشجرة، قال: كان النبي صلى الله عليه وسلم إذا أتاه قوم بصدقة قال: «اللهم صل عليهم». فأتاه أبي بصدقته، فقال: «اللهم صل على آل أبي أوفى»", "4166"], ["باب غزوة الحديبية", "حدثنا إسماعيل، عن أخيه، عن سليمان، عن عمرو بن يحيى، عن عباد بن تميم، قال: لما كان يوم الحرة، والناس يبايعون لعبد الله بن حنظلة، فقال ابن زيد: على ما يبايع ابن حنظلة الناس؟ قيل له: على الموت، قال: «لا أبايع على ذلك أحدا بعد رسول الله صلى الله عليه وسلم، وكان شهد معه الحديبية»", "4167"], ["باب غزوة الحديبية", "حدثنا يحيى بن يعلى المحاربي، قال: حدثني أبي، حدثنا إياس بن سلمة بن الأكوع، قال: حدثني أبي، وكان من أصحاب الشجرة، قال: «كنا نصلي مع النبي صلى الله عليه وسلم الجمعة ثم ننصرف، وليس للحيطان ظل نستظل فيه»", "4168"], ["باب غزوة الحديبية", "حدثنا قتيبة بن سعيد، حدثنا حاتم، عن يزيد بن أبي عبيد، قال: قلت لسلمة بن الأكوع: \" على أي شيء بايعتم رسول الله صلى الله عليه وسلم يوم الحديبية؟ قال: على الموت \"", "4169"], ["باب غزوة الحديبية", "حدثني أحمد بن إشكاب، حدثنا محمد بن فضيل، عن العلاء بن المسيب، عن أبيه، قال: لقيت البراء بن عازب رضي الله عنهما، فقلت: \" طوبى لك، صحبت النبي صلى الله عليه وسلم وبايعته تحت الشجرة، فقال: يا ابن أخي، إنك لا تدري ما أحدثنا بعده \"", "4170"], ["باب غزوة الحديبية", "حدثنا إسحاق، حدثنا يحيى بن صالح، قال: حدثنا معاوية هو ابن سلام، عن يحيى، عن أبي قلابة، أن ثابت بن الضحاك، أخبره أنه «بايع النبي صلى الله عليه وسلم تحت الشجرة»", "4171"], ["باب غزوة الحديبية", "حدثني أحمد بن إسحاق، حدثنا عثمان بن عمر، أخبرنا شعبة، عن قتادة، عن أنس بن مالك رضي الله عنه، ﴿إنا فتحنا لك فتحا مبينا﴾. قال: الحديبية قال أصحابه: هنيئا مريئا، فما لنا؟ فأنزل الله: ﴿ليدخل المؤمنين والمؤمنات جنات﴾ قال شعبة: فقدمت الكوفة، فحدثت بهذا كله عن قتادة، ثم رجعت فذكرت له فقال أما: ﴿إنا فتحنا…", "4172"], ["باب غزوة الحديبية", "حدثنا عبد الله بن محمد، حدثنا أبو عامر، حدثنا إسرائيل، عن مجزأة بن زاهر الأسلمي، عن أبيه، وكان ممن شهد الشجرة، قال: إني لأوقد تحت القدر بلحوم الحمر، إذ نادى منادي رسول الله صلى الله عليه وسلم، إن رسول الله صلى الله عليه وسلم: «ينهاكم عن لحوم الحمر»", "4173"], ["باب غزوة الحديبية", "وعن مجزأة، عن رجل منهم من أصحاب الشجرة اسمه أهبان بن أوس: «وكان اشتكى ركبته، وكان إذا سجد جعل تحت ركبته وسادة»", "4174"], ["باب غزوة الحديبية", "حدثني محمد بن بشار، حدثنا ابن أبي عدي، عن شعبة، عن يحيى بن سعيد، عن بشير بن يسار، عن سويد بن النعمان، وكان من أصحاب الشجرة: «كان رسول الله صلى الله عليه وسلم وأصحابه أتوا بسويق فلاكوه» تابعه معاذ، عن شعبة", "4175"], ["باب غزوة الحديبية", "حدثنا محمد بن حاتم بن بزيع، حدثنا شاذان، عن شعبة، عن أبي جمرة، قال: سألت عائذ بن عمرو رضي الله عنه، وكان من أصحاب النبي صلى الله عليه وسلم من أصحاب الشجرة، هل ينقض الوتر؟ قال: «إذا أوترت من أوله، فلا توتر من آخره»", "4176"], ["باب غزوة الحديبية", "حدثني عبد الله بن يوسف، أخبرنا مالك، عن زيد بن أسلم، عن أبيه، أن رسول الله صلى الله عليه وسلم كان يسير في بعض أسفاره، وعمر بن الخطاب يسير معه ليلا، فسأله عمر بن الخطاب عن شيء فلم يجبه رسول الله صلى الله عليه وسلم، ثم سأله فلم يجبه، ثم سأله فلم يجبه، وقال عمر بن الخطاب: ثكلتك أمك يا عمر، نزرت رسول…", "4177"], ["باب غزوة الحديبية", "حدثنا عبد الله بن محمد، حدثنا سفيان، قال: سمعت الزهري، حين حدث هذا الحديث، حفظت بعضه، وثبتني معمر، عن عروة بن الزبير، عن المسور بن مخرمة، ومروان بن الحكم، يزيد أحدهما على صاحبه قالا: خرج النبي صلى الله عليه وسلم عام الحديبية في بضع عشرة مائة من أصحابه، فلما أتى ذا الحليفة، قلد الهدي وأشعره وأحرم…", "4178 و4179"], ["باب غزوة الحديبية", "حدثني إسحاق، أخبرنا يعقوب، حدثني ابن أخي ابن شهاب، عن عمه، أخبرني عروة بن الزبير، أنه سمع مروان بن الحكم، والمسور بن مخرمة: يخبران خبرا من خبر رسول الله صلى الله عليه وسلم في عمرة الحديبية، فكان فيما أخبرني عروة عنهما: أنه لما كاتب رسول الله صلى الله عليه وسلم سهيل بن عمرو يوم الحديبية على قضية…", "4180 و4181"], ["باب غزوة الحديبية", "قال ابن شهاب: وأخبرني عروة بن الزبير، أن عائشة رضي الله عنها زوج النبي صلى الله عليه وسلم قالت: إن رسول الله صلى الله عليه وسلم كان «يمتحن من هاجر من المؤمنات بهذه الآية»: ﴿يا أيها النبي إذا جاءك المؤمنات﴾ وعن عمه قال: \" بلغنا حين أمر الله رسوله صلى الله عليه وسلم أن يرد إلى المشركين ما أنفقوا من…", "4182"], ["باب غزوة الحديبية", "حدثنا قتيبة، عن مالك، عن نافع، أن عبد الله بن عمر رضي الله عنهما، خرج معتمرا في الفتنة، فقال: إن صددت عن البيت صنعنا كما صنعنا مع رسول الله صلى الله عليه وسلم، فأهل بعمرة، من أجل «أن رسول الله صلى الله عليه وسلم كان أهل بعمرة عام الحديبية»", "4183"], ["باب غزوة الحديبية", "حدثنا مسدد، حدثنا يحيى، عن عبيد الله، عن نافع، عن ابن عمر أنه أهل وقال: \" إن حيل بيني وبينه لفعلت كما فعل النبي صلى الله عليه وسلم: حين حالت كفار قريش بينه \" وتلا: ﴿لقد كان لكم في رسول الله أسوة حسنة﴾", "4184"], ["باب غزوة الحديبية", "حدثنا عبد الله بن محمد بن أسماء، حدثنا جويرية، عن نافع، أن عبيد الله بن عبد الله، وسالم بن عبد الله، أخبراه: أنهما كلما عبد الله بن عمر وحدثنا موسى بن إسماعيل ، حدثنا جويرية، عن نافع، أن بعض بني عبد الله، قال له: لو أقمت العام، فإني أخاف أن لا تصل إلى البيت قال: \" خرجنا مع النبي صلى الله عليه وسلم…", "4185"], ["باب غزوة الحديبية", "حدثني شجاع بن الوليد، سمع النضر بن محمد، حدثنا صخر، عن نافع، قال: إن الناس يتحدثون أن ابن عمر، أسلم قبل عمر، وليس كذلك، ولكن عمر يوم الحديبية أرسل عبد الله إلى فرس له عند رجل من الأنصار، يأتي به ليقاتل عليه، ورسول الله صلى الله عليه وسلم يبايع عند الشجرة، وعمر لا يدري بذلك، فبايعه عبد الله ثم ذهب…", "4186"], ["باب غزوة الحديبية", "وقال هشام بن عمار، حدثنا الوليد بن مسلم، حدثنا عمر بن محمد العمري، أخبرني نافع، عن ابن عمر رضي الله عنهما، \" أن الناس كانوا مع النبي صلى الله عليه وسلم يوم الحديبية تفرقوا في ظلال الشجر، فإذا الناس محدقون بالنبي صلى الله عليه وسلم، فقال: يا عبد الله، انظر ما شأن الناس قد أحدقوا برسول الله صلى الله…", "4187"], ["باب غزوة الحديبية", "عن عبد الله بن أبي أوفى رضي الله عنهما، قال: كنا مع النبي صلى الله عليه وسلم، حين اعتمر «فطاف فطفنا معه، وصلى وصلينا معه، وسعى بين الصفا والمروة، فكنا نستره من أهل مكة لا يصيبه أحد بشيء»", "4188"], ["باب غزوة الحديبية", "حدثنا الحسن بن إسحاق، حدثنا محمد بن سابق، حدثنا مالك بن مغول، قال: سمعت أبا حصين، قال: قال أبو وائل: لما قدم سهل بن حنيف من صفين أتيناه نستخبره، فقال: «اتهموا الرأي، فلقد رأيتني يوم أبي جندل ولو أستطيع أن أرد على رسول الله صلى الله عليه وسلم أمره لرددت، والله ورسوله أعلم، وما وضعنا أسيافنا على…", "4189"], ["باب غزوة الحديبية", "عن كعب بن عجرة رضي الله عنه، قال: أتى علي النبي صلى الله عليه وسلم زمن الحديبية، والقمل يتناثر على وجهي، فقال: «أيؤذيك هوام رأسك؟» قلت: نعم، قال: «فاحلق، وصم ثلاثة أيام، أو أطعم ستة مساكين، أو انسك نسيكة» قال أيوب: «لا أدري بأي هذا بدأ»", "4190"], ["باب غزوة الحديبية", "حدثني محمد بن هشام أبو عبد الله، حدثنا هشيم، عن أبي بشر، عن مجاهد، عن عبد الرحمن بن أبي ليلى، عن كعب بن عجرة، قال: كنا مع رسول الله صلى الله عليه وسلم بالحديبية ونحن محرمون، وقد حصرنا المشركون، قال: وكانت لي وفرة، فجعلت الهوام تساقط على وجهي، فمر بي النبي صلى الله عليه وسلم فقال: «أيؤذيك هوام…", "4191"], ["باب قصة عكل وعرينة", "حدثني عبد الأعلى بن حماد، حدثنا يزيد بن زريع، حدثنا سعيد، عن قتادة، أن أنسا رضي الله عنه، حدثهم: أن ناسا من عكل وعرينة قدموا المدينة على النبي صلى الله عليه وسلم وتكلموا بالإسلام، فقالوا يا نبي الله: إنا كنا أهل ضرع، ولم نكن أهل ريف، واستوخموا المدينة، «فأمرهم رسول الله صلى الله عليه وسلم بذود…", "4192"], ["باب قصة عكل وعرينة", "حدثني محمد بن عبد الرحيم، حدثنا حفص بن عمر أبو عمر الحوضي، حدثنا حماد بن زيد، حدثنا أيوب، والحجاج الصواف، قال: حدثني أبو رجاء، مولى أبي قلابة، وكان معه بالشأم: أن عمر بن عبد العزيز، استشار الناس يوما، قال: ما تقولون في هذه القسامة؟ فقالوا: «حق قضى بها رسول الله صلى الله عليه وسلم، وقضت بها الخلفاء…", "4193"], ["باب غزوة ذات القرد", "حدثنا قتيبة بن سعيد، حدثنا حاتم، عن يزيد بن أبي عبيد، قال: سمعت سلمة بن الأكوع، يقول: خرجت قبل أن يؤذن بالأولى، وكانت لقاح رسول الله صلى الله عليه وسلم ترعى بذي قرد، قال: فلقيني غلام لعبد الرحمن بن عوف، فقال: أخذت لقاح رسول الله صلى الله عليه وسلم، قلت: من أخذها؟ قال: غطفان، قال: فصرخت ثلاث صرخات…", "4194"], ["باب غزوة خيبر", "حدثنا عبد الله بن مسلمة، عن مالك، عن يحيى بن سعيد، عن بشير بن يسار، أن سويد بن النعمان، أخبره: أنه خرج مع النبي صلى الله عليه وسلم عام خيبر، حتى إذا كنا بالصهباء، وهي من أدنى خيبر، «صلى العصر، ثم دعا بالأزواد فلم يؤت إلا بالسويق، فأمر به فثري، فأكل وأكلنا، ثم قام إلى المغرب، فمضمض ومضمضنا، ثم صلى…", "4195"], ["باب غزوة خيبر", "عن سلمة بن الأكوع رضي الله عنه، قال: خرجنا مع النبي صلى الله عليه وسلم إلى خيبر، فسرنا ليلا، فقال رجل من القوم لعامر: يا عامر ألا تسمعنا من هنيهاتك؟ وكان عامر رجلا شاعرا، فنزل يحدو بالقوم يقول: اللهم لولا أنت ما اهتدينا ... ولا تصدقنا ولا صلينا فاغفر فداء لك ما أبقينا ... وثبت الأقدام إن لاقينا…", "4196"], ["باب غزوة خيبر", "عن أنس رضي الله عنه، أن رسول الله صلى الله عليه وسلم أتى خيبر ليلا، وكان إذا أتى قوما بليل لم يغر بهم حتى يصبح، فلما أصبح خرجت اليهود بمساحيهم، ومكاتلهم فلما رأوه قالوا: محمد والله، محمد والخميس، فقال النبي صلى الله عليه وسلم: \" خربت خيبر، إنا إذا نزلنا بساحة قوم ﴿فساء صباح المنذرين﴾ \"", "4197"], ["باب غزوة خيبر", "عن أنس بن مالك رضي الله عنه، قال: صبحنا خيبر بكرة، فخرج أهلها بالمساحي، فلما بصروا بالنبي صلى الله عليه وسلم قالوا: محمد والله، محمد والخميس، فقال النبي صلى الله عليه وسلم: \" الله أكبر، خربت خيبر، إنا إذا نزلنا بساحة قوم ﴿فساء صباح المنذرين﴾ \" فأصبنا من لحوم الحمر، فنادى منادي النبي صلى الله عليه…", "4198"], ["باب غزوة خيبر", "عن أنس بن مالك رضي الله عنه، أن رسول الله صلى الله عليه وسلم جاءه جاء، فقال: أكلت الحمر، فسكت، ثم أتاه الثانية ، فقال: أكلت الحمر، فسكت، ثم أتاه الثالثة فقال: أفنيت الحمر، فأمر مناديا فنادى في الناس: «إن الله ورسوله ينهيانكم عن لحوم الحمر الأهلية». فأكفئت القدور وإنها لتفور باللحم", "4199"], ["باب غزوة خيبر", "عن أنس رضي الله عنه، قال: صلى النبي صلى الله عليه وسلم الصبح قريبا من خيبر بغلس، ثم قال: \" الله أكبر خربت خيبر، إنا إذا نزلنا بساحة قوم ﴿فساء صباح المنذرين﴾ \" فخرجوا يسعون في السكك، فقتل النبي صلى الله عليه وسلم المقاتلة، وسبى الذرية، وكان في السبي صفية، فصارت إلى دحية الكلبي، ثم صارت إلى النبي صلى…", "4200"], ["باب غزوة خيبر", "عن أنس بن مالك رضي الله عنه، يقول: «سبى النبي صلى الله عليه وسلم صفية فأعتقها وتزوجها» فقال ثابت لأنس ما أصدقها؟ قال: «أصدقها نفسها فأعتقها»", "4201"], ["باب غزوة خيبر", "عن سهل بن سعد الساعدي رضي الله عنه، أن رسول الله صلى الله عليه وسلم التقى هو والمشركون فاقتتلوا، فلما مال رسول الله صلى الله عليه وسلم إلى عسكره ومال الآخرون إلى عسكرهم، وفي أصحاب رسول الله صلى الله عليه وسلم رجل لا يدع لهم شاذة ولا فاذة إلا اتبعها يضربها بسيفه، فقيل: ما أجزأ منا اليوم أحد كما أجزأ…", "4202"], ["باب غزوة خيبر", "عن أبا هريرة رضي الله عنه، قال: شهدنا خيبر، فقال رسول الله صلى الله عليه وسلم لرجل ممن معه يدعي الإسلام: «هذا من أهل النار». فلما حضر القتال قاتل الرجل أشد القتال، حتى كثرت به الجراحة، فكاد بعض الناس يرتاب، فوجد الرجل ألم الجراحة، فأهوى بيده إلى كنانته فاستخرج منها أسهما فنحر بها نفسه، فاشتد رجال…", "4203"], ["باب غزوة خيبر", "وقال شبيب، عن يونس، عن ابن شهاب، أخبرني ابن المسيب، وعبد الرحمن بن عبد الله بن كعب، أن أبا هريرة، قال: «شهدنا مع النبي صلى الله عليه وسلم خيبر»، وقال ابن المبارك، عن يونس، عن الزهري، عن سعيد، عن النبي صلى الله عليه وسلم. تابعه صالح، عن الزهري، وقال: الزبيدي، أخبرني الزهري، أن عبد الرحمن بن كعب،…", "4204"], ["باب غزوة خيبر", "عن أبي موسى الأشعري رضي الله عنه، قال: لما غزا رسول الله صلى الله عليه وسلم خيبر، أو قال: لما توجه رسول الله صلى الله عليه وسلم، أشرف الناس على واد، فرفعوا أصواتهم بالتكبير: الله أكبر الله أكبر، لا إله إلا الله، فقال رسول الله صلى الله عليه وسلم: «اربعوا على أنفسكم، إنكم لا تدعون أصم ولا غائبا،…", "4205"], ["باب غزوة خيبر", "حدثنا المكي بن إبراهيم، حدثنا يزيد بن أبي عبيد، قال: رأيت أثر ضربة في ساق سلمة، فقلت يا أبا مسلم، ما هذه الضربة؟ فقال: هذه ضربة أصابتني يوم خيبر، فقال الناس: أصيب سلمة، فأتيت النبي صلى الله عليه وسلم «فنفث فيه ثلاث نفثات، فما اشتكيتها حتى الساعة»", "4206"], ["باب غزوة خيبر", "حدثنا عبد الله بن مسلمة، حدثنا ابن أبي حازم، عن أبيه ، عن سهل، قال: التقى النبي صلى الله عليه وسلم والمشركون في بعض مغازيه، فاقتتلوا، فمال كل قوم إلى عسكرهم، وفي المسلمين رجل لا يدع من المشركين شاذة ولا فاذة إلا اتبعها فضربها بسيفه، فقيل: يا رسول الله، ما أجزأ أحدهم ما أجزأ فلان، فقال: «إنه من أهل…", "4207"], ["باب غزوة خيبر", "حدثنا محمد بن سعيد الخزاعي، حدثنا زياد بن الربيع، عن أبي عمران، قال: نظر أنس إلى الناس يوم الجمعة، فرأى طيالسة، فقال: «كأنهم الساعة يهود خيبر»", "4208"], ["باب غزوة خيبر", "عن سلمة رضي الله عنه، قال: كان علي رضي الله عنه، تخلف عن النبي صلى الله عليه وسلم في خيبر، وكان رمدا، فقال: أنا أتخلف عن النبي صلى الله عليه وسلم، فلحق، فلما بتنا الليلة التي فتحت قال: «لأعطين الراية غدا أو ليأخذن الراية غدا رجل يحبه الله ورسوله، يفتح عليه» فنحن نرجوها، فقيل: هذا علي فأعطاه، ففتح…", "4209"], ["باب غزوة خيبر", "عن سهل بن سعد رضي الله عنه، أن رسول الله صلى الله عليه وسلم قال يوم خيبر: «لأعطين هذه الراية غدا رجلا يفتح الله على يديه، يحب الله ورسوله ويحبه الله ورسوله»، قال: فبات الناس يدوكون ليلتهم أيهم يعطاها، فلما أصبح الناس غدوا على رسول الله صلى الله عليه وسلم كلهم يرجو أن يعطاها، فقال: «أين علي بن أبي…", "4210"], ["باب غزوة خيبر", "عن أنس بن مالك رضي الله عنه، قال: قدمنا خيبر فلما فتح الله عليه الحصن، ذكر له جمال صفية بنت حيي بن أخطب، وقد قتل زوجها وكانت عروسا، فاصطفاها النبي صلى الله عليه وسلم لنفسه، فخرج بها حتى بلغنا سد الصهباء حلت، فبنى بها رسول الله صلى الله عليه وسلم، ثم صنع حيسا في نطع صغير، ثم قال لي: «آذن من حولك».…", "4211"], ["باب غزوة خيبر", "حدثنا إسماعيل، قال: حدثني أخي، عن سليمان، عن يحيى، عن حميد الطويل، سمع أنس بن مالك رضي الله عنه، أن النبي صلى الله عليه وسلم: «أقام على صفية بنت حيي بطريق خيبر ثلاثة أيام، حتى أعرس بها، وكانت فيمن ضرب عليها الحجاب»", "4212"], ["باب غزوة خيبر", "حدثنا سعيد بن أبي مريم، أخبرنا محمد بن جعفر بن أبي كثير، قال: أخبرني حميد، أنه سمع أنسا رضي الله عنه، يقول: «أقام النبي صلى الله عليه وسلم بين خيبر، والمدينة ثلاث ليال يبنى عليه بصفية»، فدعوت المسلمين إلى وليمته، وما كان فيها من خبز ولا لحم، وما كان فيها إلا أن أمر بلالا بالأنطاع فبسطت، فألقى عليها…", "4213"], ["باب غزوة خيبر", "حدثنا أبو الوليد، حدثنا شعبة، * وحدثني عبد الله بن محمد، حدثنا وهب، حدثنا شعبة، عن حميد بن هلال، عن عبد الله بن مغفل رضي الله عنه، قال: «كنا محاصري خيبر، فرمى إنسان بجراب فيه شحم، فنزوت لآخذه، فالتفت فإذا النبي صلى الله عليه وسلم فاستحييت»", "4214"], ["باب غزوة خيبر", "عن ابن عمر رضي الله عنهما، أن رسول الله صلى الله عليه وسلم «نهى يوم خيبر عن أكل الثوم، وعن لحوم الحمر الأهلية» نهى عن أكل الثوم «هو عن نافع وحده،» ولحوم الحمر الأهلية \" عن سالم", "4215"], ["باب غزوة خيبر", "عن علي بن أبي طالب رضي الله عنه، أن رسول الله صلى الله عليه وسلم: «نهى عن متعة النساء يوم خيبر، وعن أكل الحمر الإنسية»", "4216"], ["باب غزوة خيبر", "حدثنا محمد بن مقاتل، أخبرنا عبد الله، حدثنا عبيد الله بن عمر، عن نافع، عن ابن عمر أن رسول الله صلى الله عليه وسلم: «نهى يوم خيبر عن لحوم الحمر الأهلية»", "4217"], ["باب غزوة خيبر", "عن ابن عمر رضي الله عنهما، قال: «نهى النبي صلى الله عليه وسلم عن أكل لحوم الحمر الأهلية»", "4218"], ["باب غزوة خيبر", "عن جابر بن عبد الله رضي الله عنهما، قال: «نهى رسول الله صلى الله عليه وسلم يوم خيبر عن لحوم الحمر ورخص في الخيل»", "4219"], ["باب غزوة خيبر", "حدثنا سعيد بن سليمان، حدثنا عباد، عن الشيباني، قال: سمعت ابن أبي أوفى رضي الله عنهما، أصابتنا مجاعة يوم خيبر فإن القدور لتغلي، قال: وبعضها نضجت، فجاء منادي النبي صلى الله عليه وسلم: «لا تأكلوا من لحوم الحمر شيئا، وأهريقوها». قال ابن أبي أوفى: \" فتحدثنا أنه إنما نهى عنها لأنها لم تخمس، وقال بعضهم:…", "4220"], ["باب غزوة خيبر", "حدثنا حجاج بن منهال، حدثنا شعبة، قال: أخبرني عدي بن ثابت، عن البراء، وعبد الله بن أبي أوفى رضي الله عنهم، أنهم كانوا مع النبي صلى الله عليه وسلم فأصابوا حمرا، فطبخوها فنادى منادي النبي صلى الله عليه: «أكفئوا القدور»", "4221 و4222"], ["باب غزوة خيبر", "حدثني إسحاق، حدثنا عبد الصمد، حدثنا شعبة، حدثنا عدي بن ثابت، سمعت البراء، وابن أبي أوفى، رضي الله عنهم، يحدثان عن النبي صلى الله عليه وسلم أنه قال: يوم خيبر وقد نصبوا القدور: «أكفئوا القدور»", "4223 و4224"], ["باب غزوة خيبر", "حدثنا مسلم، حدثنا شعبة، عن عدي بن ثابت، عن البراء قال: غزونا مع النبي صلى الله عليه وسلم نحوه", "4225"], ["باب غزوة خيبر", "عن البراء بن عازب رضي الله عنهما، قال: أمرنا النبي صلى الله عليه وسلم في غزوة خيبر «أن نلقي الحمر الأهلية نيئة ونضيجة، ثم لم يأمرنا بأكله بعد»", "4226"], ["باب غزوة خيبر", "عن ابن عباس رضي الله عنهما، قال: «لا أدري أنهى عنه رسول الله صلى الله عليه وسلم من أجل أنه كان حمولة الناس فكره أن تذهب حمولتهم، أو حرمه في يوم خيبر لحم الحمر الأهلية»", "4227"], ["باب غزوة خيبر", "عن ابن عمر رضي الله عنهما، قال: «قسم رسول الله صلى الله عليه وسلم يوم خيبر للفرس سهمين، وللراجل سهما» قال: فسره نافع فقال: «إذا كان مع الرجل فرس فله ثلاثة أسهم، فإن لم يكن له فرس فله سهم»", "4228"], ["باب غزوة خيبر", "حدثنا يحيى بن بكير، حدثنا الليث، عن يونس، عن ابن شهاب، عن سعيد بن المسيب، أن جبير بن مطعم، أخبره قال: مشيت أنا وعثمان بن عفان، إلى النبي صلى الله عليه وسلم فقلنا: أعطيت بني المطلب من خمس خيبر، وتركتنا، ونحن بمنزلة واحدة منك، فقال «إنما بنو هاشم، وبنو المطلب شيء واحد» قال جبير: «ولم يقسم النبي صلى…", "4229"], ["باب غزوة خيبر", "عن أبي موسى رضي الله عنه، قال: بلغنا مخرج النبي صلى الله عليه وسلم ونحن باليمن، فخرجنا مهاجرين إليه أنا وأخوان لي أنا أصغرهم، أحدهما أبو بردة، والآخر أبو رهم، إما قال: بضع، وإما قال: في ثلاثة وخمسين، أو اثنين وخمسين رجلا من قومي، فركبنا سفينة، فألقتنا سفينتنا إلى النجاشي بالحبشة، فوافقنا جعفر بن…", "4230"], ["باب غزوة خيبر", "فلما جاء النبي صلى الله عليه وسلم قالت: يا نبي الله إن عمر قال: كذا وكذا؟ قال: «فما قلت له؟» قالت: قلت له: كذا وكذا، قال: «ليس بأحق بي منكم، وله ولأصحابه هجرة واحدة، ولكم أنتم - أهل السفينة - هجرتان»، قالت: فلقد رأيت أبا موسى وأصحاب السفينة يأتوني أرسالا، يسألوني عن هذا الحديث، ما من الدنيا شيء هم…", "4231"], ["باب غزوة خيبر", "قال أبو بردة، عن أبي موسى، قال النبي صلى الله عليه وسلم: \" إني لأعرف أصوات رفقة الأشعريين بالقرآن حين يدخلون بالليل، وأعرف منازلهم من أصواتهم بالقرآن بالليل، وإن كنت لم أر منازلهم حين نزلوا بالنهار، ومنهم حكيم، إذا لقي الخيل، أو قال: العدو، قال لهم: إن أصحابي يأمرونكم أن تنظروهم \"", "4232"], ["باب غزوة خيبر", "حدثني إسحاق بن إبراهيم، سمع حفص بن غياث، حدثنا بريد بن عبد الله، عن أبي بردة، عن أبي موسى، قال: «قدمنا على النبي صلى الله عليه وسلم بعد أن افتتح خيبر فقسم لنا، ولم يقسم لأحد لم يشهد الفتح غيرنا»", "4233"], ["باب غزوة خيبر", "حدثنا عبد الله بن محمد، حدثنا معاوية بن عمرو، حدثنا أبو إسحاق، عن مالك بن أنس، قال: حدثني ثور، قال: حدثني سالم، مولى ابن مطيع، أنه سمع أبا هريرة رضي الله عنه، يقول: افتتحنا خيبر، ولم نغنم ذهبا ولا فضة، إنما غنمنا البقر والإبل والمتاع والحوائط، ثم انصرفنا مع رسول الله صلى الله عليه وسلم إلى وادي…", "4234"], ["باب غزوة خيبر", "حدثنا سعيد بن أبي مريم، أخبرنا محمد بن جعفر، قال: أخبرني زيد، عن أبيه، أنه سمع عمر بن الخطاب رضي الله عنه يقول: «أما والذي نفسي بيده لولا أن أترك آخر الناس ببانا ليس لهم شيء، ما فتحت علي قرية إلا قسمتها كما قسم النبي صلى الله عليه وسلم خيبر ولكني أتركها خزانة لهم يقتسمونها»", "4235"], ["باب غزوة خيبر", "عن عمر رضي الله عنه، قال: «لولا آخر المسلمين، ما فتحت عليهم قرية إلا قسمتها، كما قسم النبي صلى الله عليه وسلم خيبر»", "4236"], ["باب غزوة خيبر", "حدثنا علي بن عبد الله، حدثنا سفيان، قال: سمعت الزهري، وسأله إسماعيل بن أمية، قال: أخبرني عنبسة بن سعيد، أن أبا هريرة رضي الله عنه، أتى النبي صلى الله عليه وسلم فسأله، قال له بعض بني سعيد بن العاص لا تعطه، فقال أبو هريرة هذا قاتل ابن قوقل فقال: «وا عجباه لوبر، تدلى من قدوم الضأن»", "4237"], ["باب غزوة خيبر", "ويذكر عن الزبيدي، عن الزهري، قال: أخبرني عنبسة بن سعيد أنه سمع أبا هريرة، يخبر سعيد بن العاصي قال: بعث رسول الله صلى الله عليه وسلم أبان على سرية من المدينة قبل نجد، قال أبو هريرة: فقدم أبان وأصحابه على النبي صلى الله عليه وسلم بخيبر بعد ما افتتحها، وإن حزم خيلهم لليف قال أبو هريرة: قلت: يا رسول…", "4238"], ["باب غزوة خيبر", "حدثنا موسى بن إسماعيل، حدثنا عمرو بن يحيى بن سعيد، قال: أخبرني جدي، أن أبان بن سعيد أقبل إلى النبي صلى الله عليه وسلم فسلم عليه، فقال أبو هريرة: يا رسول الله، هذا قاتل ابن قوقل، وقال أبان لأبي هريرة: «واعجبا لك، وبر تدأدأ من قدوم ضأن ينعى علي امرأ أكرمه الله بيدي، ومنعه أن يهينني بيده»", "4239"], ["باب غزوة خيبر", "حدثنا يحيى بن بكير، حدثنا الليث، عن عقيل، عن ابن شهاب، عن عروة، عن عائشة، أن فاطمة عليها السلام، بنت النبي صلى الله عليه وسلم أرسلت إلى أبي بكر تسأله ميراثها من رسول الله صلى الله عليه وسلم مما أفاء الله عليه بالمدينة، وفدك وما بقي من خمس خيبر فقال أبو بكر: إن رسول الله صلى الله عليه وسلم قال: «لا…", "4240 و4241"], ["باب غزوة خيبر", "عن عائشة رضي الله عنها، قالت: «لما فتحت خيبر قلنا الآن نشبع من التمر»", "4242"], ["باب غزوة خيبر", "عن ابن عمر رضي الله عنهما، قال: «ما شبعنا حتى فتحنا خيبر»", "4243"], ["باب استعمال النبي صلى الله عليه وسلم على أهل خيبر", "حدثنا إسماعيل، قال: حدثني مالك، عن عبد المجيد بن سهيل، عن سعيد بن المسيب، عن أبي سعيد الخدري، وأبي هريرة رضي الله عنهما، أن رسول الله صلى الله عليه وسلم استعمل رجلا على خيبر، فجاءه بتمر جنيب فقال رسول الله صلى الله عليه وسلم: «كل تمر خيبر هكذا»، فقال: لا والله يا رسول الله، إنا لنأخذ الصاع من هذا…", "4244 و4245"], ["باب استعمال النبي صلى الله عليه وسلم على أهل خيبر", "وقال عبد العزيز بن محمد، عن عبد المجيد، عن سعيد، أن أبا سعيد، وأبا هريرة حدثاه أن النبي صلى الله عليه وسلم بعث أخا بني عدي من الأنصار إلى خيبر، فأمره عليها، وعن عبد المجيد، عن أبي صالح السمان، عن أبي هريرة، وأبي سعيد مثله", "4246 و4247"], ["باب معاملة النبي صلى الله عليه وسلم أهل خيبر", "عن عبد الله رضي الله عنه، قال: \" أعطى النبي صلى الله عليه وسلم خيبر اليهود: أن يعملوها ويزرعوها، ولهم شطر ما يخرج منها \"", "4248"], ["باب الشاة التي سمت للنبي صلى الله عليه وسلم بخيبر", "عن أبي هريرة رضي الله عنه، قال: «لما فتحت خيبر أهديت لرسول الله صلى الله عليه وسلم شاة فيها سم»", "4249"], ["باب غزوة زيد بن حارثة", "عن ابن عمر رضي الله عنهما، قال: أمر رسول الله صلى الله عليه وسلم أسامة على قوم فطعنوا في إمارته، فقال: «إن تطعنوا في إمارته فقد طعنتم في إمارة أبيه من قبله، وايم الله لقد كان خليقا للإمارة، وإن كان من أحب الناس إلي، وإن هذا لمن أحب الناس إلي بعده»", "4250"], ["باب عمرة القضاء", "عن البراء رضي الله عنه، قال: لما اعتمر النبي صلى الله عليه وسلم في ذي القعدة، فأبى أهل مكة أن يدعوه يدخل مكة، حتى قاضاهم على أن يقيم بها ثلاثة أيام، فلما كتبوا الكتاب، كتبوا: هذا ما قاضى عليه محمد رسول الله، قالوا: لا نقر بهذا، لو نعلم أنك رسول الله ما منعناك شيئا، ولكن أنت محمد بن عبد الله، فقال…", "4251"], ["باب عمرة القضاء", "حدثني محمد بن رافع، حدثنا سريج، حدثنا فليح، ح وحدثني محمد بن الحسين بن إبراهيم، قال: حدثني أبي، حدثنا فليح بن سليمان، عن نافع، عن ابن عمر رضي الله عنهما «أن رسول الله صلى الله عليه وسلم خرج معتمرا، فحال كفار قريش بينه وبين البيت، فنحر هديه وحلق رأسه بالحديبية، وقاضاهم على أن يعتمر العام المقبل، ولا…", "4252"], ["باب عمرة القضاء", "حدثني عثمان بن أبي شيبة، حدثنا جرير، عن منصور، عن مجاهد، قال: دخلت أنا وعروة بن الزبير المسجد، فإذا عبد الله بن عمر رضي الله عنهما، جالس إلى حجرة عائشة ثم قال: «كم اعتمر النبي صلى الله عليه وسلم؟» قال: أربعا،", "4253"], ["باب عمرة القضاء", "ثم سمعنا استنان عائشة، قال عروة: يا أم المؤمنين ألا تسمعين ما يقول أبو عبد الرحمن إن النبي صلى الله عليه وسلم اعتمر أربع عمر، فقالت: «ما اعتمر النبي صلى الله عليه وسلم عمرة إلا وهو شاهده. وما اعتمر في رجب قط»", "4254"], ["باب عمرة القضاء", "حدثنا علي بن عبد الله، حدثنا سفيان، عن إسماعيل بن أبي خالد، سمع ابن أبي أوفى، يقول «لما اعتمر رسول الله صلى الله عليه وسلم سترناه من غلمان المشركين ومنهم، أن يؤذوا رسول الله صلى الله عليه وسلم»", "4255"], ["باب عمرة القضاء", "عن ابن عباس رضي الله عنهما، قال: قدم رسول الله صلى الله عليه وسلم وأصحابه، فقال المشركون: إنه يقدم عليكم وفد وهنهم حمى يثرب، «وأمرهم النبي صلى الله عليه وسلم أن يرملوا الأشواط الثلاثة، وأن يمشوا ما بين الركنين، ولم يمنعه أن يأمرهم، أن يرملوا الأشواط كلها إلا الإبقاء عليهم» وزاد ابن سلمة، عن أيوب،…", "4256"], ["باب عمرة القضاء", "عن ابن عباس رضي الله عنهما، قال: «إنما سعى النبي صلى الله عليه وسلم بالبيت، وبين الصفا والمروة، ليري المشركين قوته»", "4257"], ["باب عمرة القضاء", "حدثنا موسى بن إسماعيل، حدثنا وهيب، حدثنا أيوب، عن عكرمة، عن ابن عباس، قال: \" تزوج النبي صلى الله عليه وسلم ميمونة وهو محرم، وبنى بها وهو حلال، وماتت بسرف،", "4258"], ["باب عمرة القضاء", "وزاد ابن إسحاق، حدثني ابن أبي نجيح، وأبان بن صالح، عن عطاء، ومجاهد، عن ابن عباس قال: «تزوج النبي صلى الله عليه وسلم ميمونة في عمرة القضاء»", "4259"], ["باب غزوة مؤتة من أرض الشأم", "حدثنا أحمد، حدثنا ابن وهب، عن عمرو، عن ابن أبي هلال، قال: وأخبرني نافع، أن ابن عمر، أخبره: «أنه وقف على جعفر يومئذ، وهو قتيل، فعددت به خمسين، بين طعنة وضربة، ليس منها شيء في دبره» يعني في ظهره", "4260"], ["باب غزوة مؤتة من أرض الشأم", "عن عبد الله بن عمر رضي الله عنهما، قال: أمر رسول الله صلى الله عليه وسلم في غزوة مؤتة زيد بن حارثة، فقال رسول الله صلى الله عليه وسلم: «إن قتل زيد فجعفر، وإن قتل جعفر فعبد الله بن رواحة» قال عبد الله: كنت فيهم في تلك الغزوة، فالتمسنا جعفر بن أبي طالب، فوجدناه في القتلى، ووجدنا ما في جسده بضعا…", "4261"], ["باب غزوة مؤتة من أرض الشأم", "عن أنس رضي الله عنه، أن النبي صلى الله عليه وسلم نعى زيدا، وجعفرا، وابن رواحة للناس قبل أن يأتيهم خبرهم، فقال: «أخذ الراية زيد فأصيب، ثم أخذ جعفر فأصيب، ثم أخذ ابن رواحة فأصيب» وعيناه تذرفان: «حتى أخذ الراية سيف من سيوف الله، حتى فتح الله عليهم»", "4262"], ["باب غزوة مؤتة من أرض الشأم", "عن عائشة رضي الله عنها، تقول: لما جاء قتل ابن حارثة، وجعفر بن أبي طالب، وعبد الله بن رواحة رضي الله عنهم، جلس رسول الله صلى الله عليه وسلم يعرف فيه الحزن، قالت عائشة: وأنا أطلع من صائر الباب، تعني من شق الباب، فأتاه رجل، فقال: أي رسول الله إن نساء جعفر، قال: وذكر بكاءهن، فأمره أن ينهاهن، قال: فذهب…", "4263"], ["باب غزوة مؤتة من أرض الشأم", "حدثني محمد بن أبي بكر، حدثنا عمر بن علي، عن إسماعيل بن أبي خالد، عن عامر، قال: كان ابن عمر إذا حيا ابن جعفر قال: «السلام عليك يا ابن ذي الجناحين»", "4264"], ["باب غزوة مؤتة من أرض الشأم", "حدثنا أبو نعيم، حدثنا سفيان، عن إسماعيل، عن قيس بن أبي حازم، قال: سمعت خالد بن الوليد، يقول: «لقد انقطعت في يدي يوم مؤتة تسعة أسياف فما بقي في يدي إلا صفيحة يمانية»", "4265"], ["باب غزوة مؤتة من أرض الشأم", "حدثني محمد بن المثنى، حدثنا يحيى، عن إسماعيل، قال: حدثني قيس، قال: سمعت خالد بن الوليد، يقول: «لقد دق في يدي يوم مؤتة تسعة أسياف، وصبرت في يدي صفيحة لي يمانية»", "4266"], ["باب غزوة مؤتة من أرض الشأم", "عن النعمان بن بشير رضي الله عنهما، قال: أغمي على عبد الله بن رواحة، فجعلت أخته عمرة تبكي واجبلاه، واكذا واكذا، تعدد عليه، فقال حين أفاق: \" ما قلت شيئا إلا قيل لي: آنت كذلك «", "4267"], ["باب غزوة مؤتة من أرض الشأم", "حدثنا قتيبة، حدثنا عبثر، عن حصين، عن الشعبي، عن النعمان بن بشير،» قال أغمي على عبد الله بن رواحة بهذا فلما مات لم تبك عليه \"", "4268"], ["باب بعث النبي صلى الله عليه وسلم أسامة بن زيد إلى الحرقات من جهينة", "عن أسامة بن زيد رضي الله عنهما، يقول: بعثنا رسول الله صلى الله عليه وسلم إلى الحرقة، فصبحنا القوم فهزمناهم، ولحقت أنا ورجل من الأنصار رجلا منهم، فلما غشيناه، قال: لا إله إلا الله فكف الأنصاري فطعنته برمحي حتى قتلته، فلما قدمنا بلغ النبي صلى الله عليه وسلم، فقال: «يا أسامة، أقتلته بعد ما قال لا إله…", "4269"], ["باب بعث النبي صلى الله عليه وسلم أسامة بن زيد إلى الحرقات من جهينة", "حدثنا قتيبة بن سعيد، حدثنا حاتم، عن يزيد بن أبي عبيد، قال: سمعت سلمة بن الأكوع، يقول: «غزوت مع النبي صلى الله عليه وسلم سبع غزوات، وخرجت فيما يبعث من البعوث تسع غزوات مرة علينا أبو بكر، ومرة علينا أسامة»", "4270"], ["باب بعث النبي صلى الله عليه وسلم أسامة بن زيد إلى الحرقات من جهينة", "وقال عمر بن حفص بن غياث، حدثنا أبي، عن يزيد بن أبي عبيد، قال: سمعت سلمة يقول: غزوت مع النبي صلى الله عليه وسلم سبع غزوات، وخرجت فيما يبعث من البعث تسع غزوات، علينا مرة أبو بكر، ومرة أسامة", "4271"], ["باب بعث النبي صلى الله عليه وسلم أسامة بن زيد إلى الحرقات من جهينة", "عن سلمة بن الأكوع رضي الله عنه، قال: «غزوت مع النبي صلى الله عليه وسلم سبع غزوات، وغزوت مع ابن حارثة استعمله علينا»", "4272"], ["باب بعث النبي صلى الله عليه وسلم أسامة بن زيد إلى الحرقات من جهينة", "حدثنا محمد بن عبد الله، حدثنا حماد بن مسعدة ، عن يزيد بن أبي عبيد، عن سلمة بن الأكوع، قال \" غزوت مع النبي صلى الله عليه وسلم سبع غزوات، فذكر: خيبر، والحديبية، ويوم حنين، ويوم القرد \" قال يزيد: «ونسيت بقيتهم»", "4273"], ["باب غزوة الفتح", "عن عليا رضي الله عنه، يقول: بعثني رسول الله صلى الله عليه وسلم أنا والزبير، والمقداد، فقال: «انطلقوا حتى تأتوا روضة خاخ، فإن بها ظعينة معها كتاب، فخذوا منها» قال: فانطلقنا تعادى بنا خيلنا حتى أتينا الروضة، فإذا نحن بالظعينة، قلنا لها: أخرجي الكتاب، قالت: ما معي كتاب، فقلنا: لتخرجن الكتاب، أو لنلقين…", "4274"], ["باب غزوة الفتح في رمضان", "حدثنا عبد الله بن يوسف، حدثنا الليث، قال: حدثني عقيل، عن ابن شهاب، قال: أخبرني عبيد الله بن عبد الله بن عتبة، أن ابن عباس، أخبره: «أن رسول الله صلى الله عليه وسلم غزا غزوة الفتح في رمضان»، قال: وسمعت ابن المسيب، يقول مثل ذلك، وعن عبيد الله أن ابن عباس رضي الله عنهما قال: «صام رسول الله صلى الله…", "4275"], ["باب غزوة الفتح في رمضان", "عن ابن عباس رضي الله عنهما، أن النبي صلى الله عليه وسلم «خرج في رمضان من المدينة ومعه عشرة آلاف، وذلك على رأس ثمان سنين ونصف من مقدمه المدينة، فسار هو ومن معه من المسلمين إلى مكة، يصوم ويصومون، حتى بلغ الكديد، وهو ماء بين عسفان، وقديد أفطر وأفطروا»، قال الزهري: «وإنما يؤخذ من أمر رسول الله صلى الله…", "4276"], ["باب غزوة الفتح في رمضان", "حدثني عياش بن الوليد، حدثنا عبد الأعلى، حدثنا خالد، عن عكرمة، عن ابن عباس، قال: \" خرج النبي صلى الله عليه وسلم في رمضان إلى حنين، والناس مختلفون، فصائم ومفطر، فلما استوى على راحلته، دعا بإناء من لبن أو ماء، فوضعه على راحته، أو على راحلته، ثم نظر إلى الناس فقال المفطرون للصوام: أفطروا \"", "4277"], ["باب غزوة الفتح في رمضان", "وقال عبد الرزاق، أخبرنا معمر، عن أيوب، عن عكرمة، عن ابن عباس رضي الله عنهما خرج النبي صلى الله عليه وسلم عام الفتح، وقال حماد بن زيد: عن أيوب، عن عكرمة، عن ابن عباس عن النبي صلى الله عليه وسلم", "4278"], ["باب غزوة الفتح في رمضان", "حدثنا علي بن عبد الله، حدثنا جرير، عن منصور، عن مجاهد، عن طاوس، عن ابن عباس، قال: «سافر رسول الله صلى الله عليه وسلم في رمضان، فصام حتى بلغ عسفان، ثم دعا بإناء من ماء، فشرب نهارا ليريه الناس، فأفطر حتى قدم مكة» قال: وكان ابن عباس يقول: «صام رسول الله صلى الله عليه وسلم في السفر، وأفطر فمن شاء صام…", "4279"], ["باب: أين ركز النبي صلى الله عليه وسلم الراية يوم الفتح؟", "حدثنا عبيد بن إسماعيل، حدثنا أبو أسامة، عن هشام، عن أبيه، قال: لما سار رسول الله صلى الله عليه وسلم عام الفتح، فبلغ ذلك قريشا، خرج أبو سفيان بن حرب، وحكيم بن حزام، وبديل بن ورقاء، يلتمسون الخبر عن رسول الله صلى الله عليه وسلم، فأقبلوا يسيرون حتى أتوا مر الظهران، فإذا هم بنيران كأنها نيران عرفة،…", "4280"], ["باب: أين ركز النبي صلى الله عليه وسلم الراية يوم الفتح؟", "حدثنا أبو الوليد، حدثنا شعبة، عن معاوية بن قرة، قال: سمعت عبد الله بن مغفل، يقول: «رأيت رسول الله صلى الله عليه وسلم يوم فتح مكة على ناقته، وهو يقرأ سورة الفتح يرجع». وقال: لولا أن يجتمع الناس حولي لرجعت كما رجع", "4281"], ["باب: أين ركز النبي صلى الله عليه وسلم الراية يوم الفتح؟", "حدثنا سليمان بن عبد الرحمن، حدثنا سعدان بن يحيى، حدثنا محمد بن أبي حفصة، عن الزهري، عن علي بن حسين، عن عمرو بن عثمان، عن أسامة بن زيد، أنه قال زمن الفتح: يا رسول الله، أين تنزل غدا؟ قال النبي صلى الله عليه وسلم: «وهل ترك لنا عقيل من منزل»", "4282"], ["باب: أين ركز النبي صلى الله عليه وسلم الراية يوم الفتح؟", "ثم قال: «لا يرث المؤمن الكافر، ولا يرث الكافر المؤمن» قيل للزهري: ومن ورث أبا طالب؟ قال: «ورثه عقيل وطالب»، قال معمر عن الزهري: «أين تنزل غدا في حجته؟» ولم يقل يونس: «حجته ولا زمن الفتح»", "4283"], ["باب: أين ركز النبي صلى الله عليه وسلم الراية يوم الفتح؟", "عن أبي هريرة رضي الله عنه، قال: قال رسول الله صلى الله عليه وسلم: «منزلنا - إن شاء الله، إذا فتح الله - الخيف حيث تقاسموا على الكفر»", "4284"], ["باب: أين ركز النبي صلى الله عليه وسلم الراية يوم الفتح؟", "عن أبي هريرة رضي الله عنه، قال: قال رسول الله صلى الله عليه وسلم حين أراد حنينا: «منزلنا غدا إن شاء الله، بخيف بني كنانة، حيث تقاسموا على الكفر»", "4285"], ["باب: أين ركز النبي صلى الله عليه وسلم الراية يوم الفتح؟", "عن أنس بن مالك رضي الله عنه، أن النبي صلى الله عليه وسلم \" دخل مكة يوم الفتح وعلى رأسه المغفر، فلما نزعه جاء رجل فقال: ابن خطل متعلق بأستار الكعبة، فقال: «اقتله»، قال مالك: «ولم يكن النبي صلى الله عليه وسلم فيما نرى والله أعلم يومئذ محرما»", "4286"], ["باب: أين ركز النبي صلى الله عليه وسلم الراية يوم الفتح؟", "عن عبد الله رضي الله عنه، قال: دخل النبي صلى الله عليه وسلم مكة يوم الفتح، وحول البيت ستون وثلاث مائة نصب فجعل يطعنها بعود في يده، ويقول: «جاء الحق وزهق الباطل، جاء الحق وما يبدئ الباطل وما يعيد»", "4287"], ["باب: أين ركز النبي صلى الله عليه وسلم الراية يوم الفتح؟", "عن ابن عباس رضي الله عنهما: أن رسول الله صلى الله عليه وسلم لما قدم مكة، أبى أن يدخل البيت وفيه الآلهة، فأمر بها فأخرجت، فأخرج صورة إبراهيم وإسماعيل في أيديهما من الأزلام، فقال النبي صلى الله عليه وسلم: \" قاتلهم الله، لقد علموا: ما استقسما بها قط \"، ثم دخل البيت، فكبر في نواحي البيت، وخرج ولم يصل…", "4288"], ["باب دخول النبي صلى الله عليه وسلم من أعلى مكة", "عن عبد الله بن عمر رضي الله عنهما: «أن رسول الله صلى الله عليه وسلم أقبل يوم الفتح من أعلى مكة على راحلته، مردفا أسامة بن زيد، ومعه بلال، ومعه عثمان بن طلحة من الحجبة، حتى أناخ في المسجد، فأمره أن يأتي بمفتاح البيت، فدخل رسول الله صلى الله عليه وسلم ومعه أسامة بن زيد، وبلال، وعثمان بن طلحة، فمكث…", "4289"], ["باب دخول النبي صلى الله عليه وسلم من أعلى مكة", "حدثنا الهيثم بن خارجة، حدثنا حفص بن ميسرة، عن هشام بن عروة، عن أبيه، أن عائشة رضي الله عنها، أخبرته: «أن النبي صلى الله عليه وسلم دخل عام الفتح من كداء التي بأعلى مكة» تابعه أبو أسامة، ووهيب، في كداء", "4290"], ["باب دخول النبي صلى الله عليه وسلم من أعلى مكة", "حدثنا عبيد بن إسماعيل، حدثنا أبو أسامة، عن هشام، عن أبيه، «دخل النبي صلى الله عليه وسلم عام الفتح من أعلى مكة من كداء»", "4291"], ["باب منزل النبي صلى الله عليه وسلم يوم الفتح", "حدثنا أبو الوليد، حدثنا شعبة، عن عمرو، عن ابن أبي ليلى، ما أخبرنا أحد، أنه رأى النبي صلى الله عليه وسلم يصلي الضحى غير أم هانئ، فإنها ذكرت: «أنه يوم فتح مكة اغتسل في بيتها، ثم صلى ثماني ركعات»، قالت: «لم أره صلى صلاة أخف منها غير أنه يتم الركوع والسجود»", "4292"], ["باب منزل النبي صلى الله عليه وسلم يوم الفتح", "عن عائشة رضي الله عنها، قالت: كان النبي صلى الله عليه وسلم يقول في ركوعه وسجوده: «سبحانك اللهم ربنا وبحمدك، اللهم اغفر لي»", "4293"], ["باب منزل النبي صلى الله عليه وسلم يوم الفتح", "عن ابن عباس رضي الله عنهما، قال: كان عمر يدخلني مع أشياخ بدر، فقال بعضهم: لم تدخل هذا الفتى معنا ولنا أبناء مثله؟ فقال: «إنه ممن قد علمتم» قال: فدعاهم ذات يوم ودعاني معهم قال: وما رؤيته دعاني يومئذ إلا ليريهم مني، فقال: ما تقولون إذا جاء نصر الله والفتح، ورأيت الناس يدخلون حتى ختم السورة، فقال…", "4294"], ["باب منزل النبي صلى الله عليه وسلم يوم الفتح", "حدثنا سعيد بن شرحبيل، حدثنا الليث، عن المقبري، عن أبي شريح العدوي، أنه قال: لعمرو بن سعيد وهو يبعث البعوث إلى مكة ائذن لي أيها الأمير، أحدثك قولا قام به رسول الله صلى الله عليه وسلم الغد يوم الفتح، سمعته أذناي ووعاه قلبي، وأبصرته عيناي حين تكلم به، حمد الله وأثنى عليه ثم قال: \" إن مكة حرمها الله،…", "4295"], ["باب منزل النبي صلى الله عليه وسلم يوم الفتح", "عن جابر بن عبد الله رضي الله عنهما، أنه سمع رسول الله صلى الله عليه وسلم يقول عام الفتح: وهو بمكة «إن الله ورسوله حرم بيع الخمر»", "4296"], ["باب مقام النبي صلى الله عليه وسلم بمكة زمن الفتح", "حدثنا أبو نعيم، حدثنا سفيان * حدثنا قبيصة، حدثنا سفيان، عن يحيى بن أبي إسحاق، عن أنس رضي الله عنه، قال: «أقمنا مع النبي صلى الله عليه وسلم عشرا نقصر الصلاة»", "4297"], ["باب مقام النبي صلى الله عليه وسلم بمكة زمن الفتح", "عن ابن عباس رضي الله عنهما، قال: «أقام النبي صلى الله عليه وسلم بمكة تسعة عشر يوما يصلي ركعتين»", "4298"], ["باب مقام النبي صلى الله عليه وسلم بمكة زمن الفتح", "حدثنا أحمد بن يونس، حدثنا أبو شهاب، عن عاصم، عن عكرمة، عن ابن عباس، قال: «أقمنا مع النبي صلى الله عليه وسلم في سفر تسع عشرة نقصر الصلاة» وقال ابن عباس: «ونحن نقصر ما بيننا وبين تسع عشرة، فإذا زدنا أتممنا»", "4299"], ["باب:", "وقال الليث حدثني يونس، عن ابن شهاب، أخبرني عبد الله بن ثعلبة بن صعير، وكان النبي صلى الله عليه وسلم قد مسح وجهه عام الفتح", "4300"], ["باب:", "حدثني إبراهيم بن موسى، أخبرنا هشام، عن معمر، عن الزهري، عن سنين أبي جميلة، قال: أخبرنا ونحن مع ابن المسيب، قال: «وزعم أبو جميلة أنه أدرك النبي صلى الله عليه وسلم وخرج معه عام الفتح»", "4301"], ["باب:", "حدثنا سليمان بن حرب، حدثنا حماد بن زيد، عن أيوب، عن أبي قلابة، عن عمرو بن سلمة، قال: قال لي أبو قلابة: ألا تلقاه فتسأله؟ قال فلقيته فسألته فقال: كنا بماء ممر الناس، وكان يمر بنا الركبان فنسألهم: ما للناس، ما للناس؟ ما هذا الرجل؟ فيقولون: يزعم أن الله أرسله، أوحى إليه، أو: أوحى الله بكذا، فكنت أحفظ…", "4302"], ["باب:", "عن عائشة رضي الله عنها، عن النبي صلى الله عليه وسلم وقال الليث: حدثني يونس، عن ابن شهاب، أخبرني عروة بن الزبير، أن عائشة قالت: كان عتبة بن أبي وقاص عهد إلى أخيه سعد: أن يقبض ابن وليدة زمعة، وقال عتبة: إنه ابني، فلما قدم رسول الله صلى الله عليه وسلم مكة في الفتح، أخذ سعد بن أبي وقاص ابن وليدة زمعة،…", "4303"], ["باب:", "حدثنا محمد بن مقاتل، أخبرنا عبد الله، أخبرنا يونس، عن الزهري، قال: أخبرني عروة بن الزبير، أن امرأة سرقت في عهد رسول الله صلى الله عليه وسلم في غزوة الفتح، ففزع قومها إلى أسامة بن زيد يستشفعونه، قال عروة: فلما كلمه أسامة فيها، تلون وجه رسول الله صلى الله عليه وسلم، فقال: «أتكلمني في حد من حدود…", "4304"], ["باب:", "حدثنا عمرو بن خالد، حدثنا زهير، حدثنا عاصم، عن أبي عثمان، قال: حدثني مجاشع، قال: أتيت النبي صلى الله عليه وسلم بأخي بعد الفتح، قلت: يا رسول الله، جئتك بأخي لتبايعه على الهجرة. قال: «ذهب أهل الهجرة بما فيها». فقلت: \" على أي شيء تبايعه؟ قال: «أبايعه على الإسلام، والإيمان، والجهاد» فلقيت أبا معبد بعد،…", "4305 و4306"], ["باب:", "حدثنا محمد بن أبي بكر، حدثنا الفضيل بن سليمان، حدثنا عاصم، عن أبي عثمان النهدي، عن مجاشع بن مسعود، انطلقت بأبي معبد إلى النبي صلى الله عليه وسلم ليبايعه على الهجرة قال: «مضت الهجرة لأهلها، أبايعه على الإسلام والجهاد» فلقيت أبا معبد فسألته فقال: «صدق مجاشع» وقال خالد، عن أبي عثمان، عن مجاشع، أنه جاء…", "4307 و4308"], ["باب:", "حدثني محمد بن بشار، حدثنا غندر، حدثنا شعبة، عن أبي بشر، عن مجاهد، قلت لابن عمر رضي الله عنهما: إني أريد أن أهاجر إلى الشأم، قال: «لا هجرة، ولكن جهاد، فانطلق فاعرض نفسك، فإن وجدت شيئا وإلا رجعت»", "4309"], ["باب:", "وقال النضر: أخبرنا شعبة، أخبرنا أبو بشر، سمعت مجاهدا، قلت لابن عمر: فقال: «لا هجرة اليوم أو بعد رسول الله صلى الله عليه وسلم» مثله", "4310"], ["باب:", "حدثني إسحاق بن يزيد، حدثنا يحيى بن حمزة، قال: حدثني أبو عمرو الأوزاعي، عن عبدة بن أبي لبابة، عن مجاهد بن جبر المكي، أن عبد الله بن عمر رضي الله عنهما، كان يقول: «لا هجرة بعد الفتح»", "4311"], ["باب:", "حدثنا إسحاق بن يزيد، حدثنا يحيى بن حمزة، قال: حدثني الأوزاعي، عن عطاء بن أبي رباح، قال: زرت عائشة مع عبيد بن عمير، فسألها عن الهجرة، فقالت: «لا هجرة اليوم، كان المؤمن يفر أحدهم بدينه إلى الله وإلى رسوله صلى الله عليه وسلم، مخافة أن يفتن عليه، فأما اليوم فقد أظهر الله الإسلام، فالمؤمن يعبد ربه حيث…", "4312"], ["باب:", "حدثنا إسحاق، حدثنا أبو عاصم، عن ابن جريج، قال: أخبرني حسن بن مسلم، عن مجاهد، أن رسول الله صلى الله عليه وسلم قام يوم الفتح فقال: «إن الله حرم مكة يوم خلق السموات والأرض، فهي حرام بحرام الله إلى يوم القيامة، لم تحل لأحد قبلي ولا تحل لأحد بعدي، ولم تحلل لي إلا ساعة من الدهر، لا ينفر صيدها، ولا يعضد…", "4313"], ["باب قول الله تعالى: {ويوم حنين إذ أعجبتكم كثرتكم فلم تغن عنكم شيئا وضاقت عليكم الأرض بما رحبت ثم وليتم مدبرين. ثم أنزل الله سكينته}- إلى قوله - {غفور رحيم}", "حدثنا محمد بن عبد الله بن نمير، حدثنا يزيد بن هارون، أخبرنا إسماعيل، رأيت بيد ابن أبي أوفى ضربة قال: «ضربتها مع النبي صلى الله عليه وسلم يوم حنين» قلت: شهدت حنينا؟ قال: قبل ذلك", "4314"], ["باب قول الله تعالى: {ويوم حنين إذ أعجبتكم كثرتكم فلم تغن عنكم شيئا وضاقت عليكم الأرض بما رحبت ثم وليتم مدبرين. ثم أنزل الله سكينته}- إلى قوله - {غفور رحيم}", "حدثنا محمد بن كثير، حدثنا سفيان، عن أبي إسحاق، قال: سمعت البراء رضي الله عنه، وجاءه رجل، فقال: يا أبا عمارة أتوليت يوم حنين؟ فقال: أما أنا فأشهد على النبي صلى الله عليه وسلم أنه لم يول، ولكن عجل سرعان القوم، فرشقتهم هوازن، وأبو سفيان بن الحارث آخذ برأس بغلته البيضاء، يقول: «أنا النبي لا كذب، أنا…", "4315"], ["باب قول الله تعالى: {ويوم حنين إذ أعجبتكم كثرتكم فلم تغن عنكم شيئا وضاقت عليكم الأرض بما رحبت ثم وليتم مدبرين. ثم أنزل الله سكينته}- إلى قوله - {غفور رحيم}", "حدثنا أبو الوليد، حدثنا شعبة، عن أبي إسحاق، قيل للبراء: وأنا أسمع أوليتم مع النبي صلى الله عليه وسلم يوم حنين؟ فقال: أما النبي صلى الله عليه وسلم فلا كانوا رماة، فقال: «أنا النبي لا كذب، أنا ابن عبد المطلب»", "4316"], ["باب قول الله تعالى: {ويوم حنين إذ أعجبتكم كثرتكم فلم تغن عنكم شيئا وضاقت عليكم الأرض بما رحبت ثم وليتم مدبرين. ثم أنزل الله سكينته}- إلى قوله - {غفور رحيم}", "حدثني محمد بن بشار، حدثنا غندر، حدثنا شعبة، عن أبي إسحاق، سمع البراء، وسأله رجل من قيس أفررتم عن رسول الله صلى الله عليه وسلم يوم حنين؟ فقال: لكن رسول الله صلى الله عليه وسلم لم يفر، كانت هوازن رماة، وإنا لما حملنا عليهم انكشفوا، فأكببنا على الغنائم، فاستقبلنا بالسهام، ولقد رأيت رسول الله صلى الله…", "4317"], ["باب قول الله تعالى: {ويوم حنين إذ أعجبتكم كثرتكم فلم تغن عنكم شيئا وضاقت عليكم الأرض بما رحبت ثم وليتم مدبرين. ثم أنزل الله سكينته}- إلى قوله - {غفور رحيم}", "حدثنا سعيد بن عفير، قال: حدثني ليث، حدثني عقيل، عن ابن شهاب، وحدثني إسحاق ، حدثنا يعقوب بن إبراهيم، حدثنا ابن أخي ابن شهاب، قال: محمد بن شهاب، وزعم عروة بن الزبير، أن مروان، والمسور بن مخرمة، أخبراه أن رسول الله صلى الله عليه وسلم قام حين جاءه وفد هوازن مسلمين، فسألوه أن يرد إليهم أموالهم وسبيهم،…", "4318 و4319"], ["باب قول الله تعالى: {ويوم حنين إذ أعجبتكم كثرتكم فلم تغن عنكم شيئا وضاقت عليكم الأرض بما رحبت ثم وليتم مدبرين. ثم أنزل الله سكينته}- إلى قوله - {غفور رحيم}", "حدثنا أبو النعمان، حدثنا حماد بن زيد، عن أيوب، عن نافع، أن عمر، قال: يا رسول الله. * حدثني محمد بن مقاتل، أخبرنا عبد الله، أخبرنا معمر، عن أيوب، عن نافع، عن ابن عمر رضي الله عنهما، قال: لما قفلنا من حنين، سأل عمر النبي صلى الله عليه وسلم عن نذر كان نذره في الجاهلية، اعتكاف: «فأمره النبي صلى الله…", "4320"], ["باب قول الله تعالى: {ويوم حنين إذ أعجبتكم كثرتكم فلم تغن عنكم شيئا وضاقت عليكم الأرض بما رحبت ثم وليتم مدبرين. ثم أنزل الله سكينته}- إلى قوله - {غفور رحيم}", "حدثنا عبد الله بن يوسف، أخبرنا مالك، عن يحيى بن سعيد، عن عمر بن كثير بن أفلح، عن أبي محمد، مولى أبي قتادة، عن أبي قتادة، قال: خرجنا مع النبي صلى الله عليه وسلم عام حنين، فلما التقينا كانت للمسلمين جولة، فرأيت رجلا من المشركين قد علا رجلا من المسلمين، فضربته من ورائه على حبل عاتقه بالسيف فقطعت…", "4321"], ["باب قول الله تعالى: {ويوم حنين إذ أعجبتكم كثرتكم فلم تغن عنكم شيئا وضاقت عليكم الأرض بما رحبت ثم وليتم مدبرين. ثم أنزل الله سكينته}- إلى قوله - {غفور رحيم}", "وقال الليث: حدثني يحيى بن سعيد، عن عمر بن كثير بن أفلح، عن أبي محمد، مولى أبي قتادة، أن أبا قتادة، قال: لما كان يوم حنين نظرت إلى رجل من المسلمين يقاتل رجلا من المشركين، وآخر من المشركين يختله من ورائه ليقتله، فأسرعت إلى الذي يختله، فرفع يده ليضربني وأضرب يده فقطعتها، ثم أخذني فضمني ضما شديدا، حتى…", "4322"], ["باب غزاة أوطاس", "عن أبي موسى رضي الله عنه، قال: لما فرغ النبي صلى الله عليه وسلم من حنين بعث أبا عامر على جيش إلى أوطاس، فلقي دريد بن الصمة، فقتل دريد وهزم الله أصحابه، قال أبو موسى: وبعثني مع أبي عامر، فرمي أبو عامر في ركبته، رماه جشمي بسهم فأثبته في ركبته، فانتهيت إليه فقلت: يا عم من رماك؟ فأشار إلى أبي موسى…", "4323"], ["باب غزوة الطائف", "حدثنا الحميدي، سمع سفيان، حدثنا هشام، عن أبيه، عن زينب بنة أبي سلمة، عن أمها أم سلمة رضي الله عنها، دخل علي النبي صلى الله عليه وسلم، وعندي مخنث، فسمعته يقول لعبد الله بن أمية: يا عبد الله، أرأيت إن فتح الله عليكم الطائف غدا، فعليك بابنة غيلان، فإنها تقبل بأربع، وتدبر بثمان، وقال النبي صلى الله…", "4324"], ["باب غزوة الطائف", "حدثنا علي بن عبد الله، حدثنا سفيان، عن عمرو، عن أبي العباس الشاعر الأعمى، عن عبد الله بن عمرو قال: لما حاصر رسول الله صلى الله عليه وسلم الطائف، فلم ينل منهم شيئا، قال: «إنا قافلون إن شاء الله». فثقل عليهم، وقالوا: نذهب ولا نفتحه، وقال مرة: «نقفل». فقال: «اغدوا على القتال». فغدوا فأصابهم جراح،…", "4325"], ["باب غزوة الطائف", "حدثنا محمد بن بشار، حدثنا غندر، حدثنا شعبة، عن عاصم، قال: سمعت أبا عثمان، قال: سمعت سعدا، وهو أول من رمى بسهم في سبيل الله، وأبا بكرة، وكان تسور حصن الطائف في أناس فجاء إلى النبي صلى الله عليه وسلم، فقالا: سمعنا النبي صلى الله عليه وسلم يقول: «من ادعى إلى غير أبيه، وهو يعلم فالجنة عليه حرام» وقال…", "4326 و4327"], ["باب غزوة الطائف", "عن أبي موسى رضي الله عنه، قال: كنت عند النبي صلى الله عليه وسلم وهو نازل بالجعرانة بين مكة والمدينة، ومعه بلال فأتى النبي صلى الله عليه وسلم أعرابي فقال: ألا تنجز لي ما وعدتني؟ فقال له: «أبشر» فقال: قد أكثرت علي من أبشر، فأقبل على أبي موسى وبلال كهيئة الغضبان، فقال: «رد البشرى، فاقبلا أنتما» قالا:…", "4328"], ["باب غزوة الطائف", "حدثنا يعقوب بن إبراهيم، حدثنا إسماعيل، حدثنا ابن جريج، قال: أخبرني عطاء، أن صفوان بن يعلى بن أمية، أخبر أن يعلى كان يقول: ليتني أرى رسول الله صلى الله عليه وسلم حين ينزل عليه، قال: فبينا النبي صلى الله عليه وسلم بالجعرانة وعليه ثوب قد أظل به، معه فيه ناس من أصحابه، إذ جاءه أعرابي عليه جبة متضمخ…", "4329"], ["باب غزوة الطائف", "حدثنا موسى بن إسماعيل، حدثنا وهيب، حدثنا عمرو بن يحيى، عن عباد بن تميم، عن عبد الله بن زيد بن عاصم، قال: لما أفاء الله على رسوله صلى الله عليه وسلم يوم حنين، قسم في الناس في المؤلفة قلوبهم، ولم يعط الأنصار شيئا، فكأنهم وجدوا إذ لم يصبهم ما أصاب الناس، فخطبهم فقال: «يا معشر الأنصار، ألم أجدكم ضلالا…", "4330"], ["باب غزوة الطائف", "عن أنس بن مالك رضي الله عنه، قال: قال ناس من الأنصار، حين أفاء الله على رسوله صلى الله عليه وسلم ما أفاء من أموال هوازن، فطفق النبي صلى الله عليه وسلم يعطي رجالا المائة من الإبل، فقالوا: يغفر الله لرسول الله صلى الله عليه وسلم يعطي قريشا ويتركنا، وسيوفنا تقطر من دمائهم، قال أنس: فحدث رسول الله صلى…", "4331"], ["باب غزوة الطائف", "حدثنا سليمان بن حرب، حدثنا شعبة، عن أبي التياح، عن أنس، قال: لما كان يوم فتح مكة قسم رسول الله صلى الله عليه وسلم غنائم بين قريش، فغضبت الأنصار، قال النبي صلى الله عليه وسلم: «أما ترضون أن يذهب الناس بالدنيا، وتذهبون برسول الله - صلى الله عليه وسلم -» قالوا: بلى، قال: «لو سلك الناس واديا أو شعبا،…", "4332"], ["باب غزوة الطائف", "عن أنس رضي الله عنه، قال: لما كان يوم حنين، التقى هوازن ومع النبي صلى الله عليه وسلم عشرة آلاف، والطلقاء، فأدبروا، قال: «يا معشر الأنصار». قالوا: لبيك يا رسول الله وسعديك لبيك نحن بين يديك، فنزل النبي صلى الله عليه وسلم فقال: «أنا عبد الله ورسوله». فانهزم المشركون، فأعطى الطلقاء والمهاجرين ولم يعط…", "4333"], ["باب غزوة الطائف", "عن أنس بن مالك رضي الله عنه، قال: جمع النبي صلى الله عليه وسلم ناسا من الأنصار فقال: «إن قريشا حديث عهد بجاهلية ومصيبة، وإني أردت أن أجبرهم وأتألفهم، أما ترضون أن يرجع الناس بالدنيا، وترجعون برسول الله صلى الله عليه وسلم إلى بيوتكم» قالوا: بلى، قال: «لو سلك الناس واديا، وسلكت الأنصار شعبا، لسلكت…", "4334"], ["باب غزوة الطائف", "حدثنا قبيصة، حدثنا سفيان، عن الأعمش، عن أبي وائل، عن عبد الله، قال: لما قسم النبي صلى الله عليه وسلم قسمة حنين، قال: رجل من الأنصار: ما أراد بها وجه الله، فأتيت النبي صلى الله عليه وسلم فأخبرته، فتغير وجهه ثم قال: «رحمة الله على موسى، لقد أوذي بأكثر من هذا فصبر»", "4335"], ["باب غزوة الطائف", "عن عبد الله رضي الله عنه، قال: لما كان يوم حنين آثر النبي صلى الله عليه وسلم ناسا، أعطى الأقرع مائة من الإبل، وأعطى عيينة مثل ذلك، وأعطى ناسا، فقال رجل: ما أريد بهذه القسمة وجه الله، فقلت: لأخبرن النبي صلى الله عليه وسلم، قال: «رحم الله موسى، قد أوذي بأكثر من هذا فصبر»", "4336"], ["باب غزوة الطائف", "عن أنس بن مالك رضي الله عنه، قال: لما كان يوم حنين، أقبلت هوازن وغطفان وغيرهم بنعمهم وذراريهم، ومع النبي صلى الله عليه وسلم عشرة آلاف، ومن الطلقاء، فأدبروا عنه حتى بقي وحده، فنادى يومئذ نداءين لم يخلط بينهما، التفت عن يمينه فقال: «يا معشر الأنصار». قالوا: لبيك يا رسول الله أبشر نحن معك، ثم التفت عن…", "4337"], ["باب السرية التي قبل نجد", "عن ابن عمر رضي الله عنهما، قال: «بعث النبي صلى الله عليه وسلم سرية قبل نجد فكنت فيها، فبلغت سهامنا اثني عشر بعيرا، ونفلنا بعيرا بعيرا، فرجعنا بثلاثة عشر بعيرا»", "4338"], ["باب بعث النبي صلى الله عليه وسلم خالد بن الوليد إلى بني جذيمة", "حدثني محمود، حدثنا عبد الرزاق، أخبرنا معمر، * وحدثني نعيم، أخبرنا عبد الله، أخبرنا معمر، عن الزهري، عن سالم، عن أبيه، قال: بعث النبي صلى الله عليه وسلم خالد بن الوليد إلى بني جذيمة، فدعاهم إلى الإسلام، فلم يحسنوا أن يقولوا: أسلمنا، فجعلوا يقولون: صبأنا صبأنا، فجعل خالد يقتل منهم ويأسر، ودفع إلى كل…", "4339"], ["سرية عبد الله بن حذافة السهمي، وعلقمة بن مجزز المدلجي ويقال: إنها سرية الأنصار", "عن علي رضي الله عنه، قال: بعث النبي صلى الله عليه وسلم سرية فاستعمل رجلا من الأنصار وأمرهم أن يطيعوه، فغضب، فقال: أليس أمركم النبي صلى الله عليه وسلم أن تطيعوني؟ قالوا: بلى، قال: فاجمعوا لي حطبا، فجمعوا، فقال: أوقدوا نارا، فأوقدوها، فقال: ادخلوها، فهموا وجعل بعضهم يمسك بعضا، ويقولون: فررنا إلى…", "4340"], ["بعث أبي موسى، ومعاذ إلى اليمن قبل حجة الوداع", "حدثنا موسى، حدثنا أبو عوانة، حدثنا عبد الملك، عن أبي بردة، قال: بعث رسول الله صلى الله عليه وسلم أبا موسى، ومعاذ بن جبل إلى اليمن، قال: وبعث كل واحد منهما على مخلاف، قال: واليمن مخلافان، ثم قال: «يسرا ولا تعسرا، وبشرا ولا تنفرا»، فانطلق كل واحد منهما إلى عمله، وكان كل واحد منهما إذا سار في أرضه كان…", "4341 و4342"], ["بعث أبي موسى، ومعاذ إلى اليمن قبل حجة الوداع", "عن أبي موسى الأشعري رضي الله عنه، أن النبي صلى الله عليه وسلم بعثه إلى اليمن، فسأله عن أشربة تصنع بها، فقال: «وما هي؟» قال: البتع والمزر، فقلت لأبي بردة: ما البتع؟ قال: نبيذ العسل، والمزر نبيذ الشعير، فقال: «كل مسكر حرام» رواه جرير، وعبد الواحد، عن الشيباني، عن أبي بردة", "4343"], ["بعث أبي موسى، ومعاذ إلى اليمن قبل حجة الوداع", "حدثنا مسلم، حدثنا شعبة، حدثنا سعيد بن أبي بردة، عن أبيه، قال: بعث النبي صلى الله عليه وسلم جده أبا موسى ومعاذا إلى اليمن، فقال: «يسرا ولا تعسرا، وبشرا ولا تنفرا وتطاوعا»، فقال أبو موسى: يا نبي الله إن أرضنا بها شراب من الشعير المزر، وشراب من العسل البتع، فقال: «كل مسكر حرام». فانطلقا، فقال معاذ…", "4344 و4345"], ["بعث أبي موسى، ومعاذ إلى اليمن قبل حجة الوداع", "عن أبو موسى الأشعري رضي الله عنه، قال: بعثني رسول الله صلى الله عليه وسلم إلى أرض قومي، فجئت ورسول الله صلى الله عليه وسلم منيخ بالأبطح، فقال: «أحججت يا عبد الله بن قيس» قلت: نعم يا رسول الله، قال: «كيف قلت؟» قال: قلت: لبيك إهلالا كإهلالك، قال: «فهل سقت معك هديا» قلت: لم أسق، قال: «فطف بالبيت، واسع…", "4346"], ["بعث أبي موسى، ومعاذ إلى اليمن قبل حجة الوداع", "عن ابن عباس رضي الله عنهما، قال: قال رسول الله صلى الله عليه وسلم لمعاذ بن جبل حين بعثه إلى اليمن: «إنك ستأتي قوما من أهل الكتاب، فإذا جئتهم فادعهم إلى أن يشهدوا أن لا إله إلا الله، وأن محمدا رسول الله ، فإن هم طاعوا لك بذلك، فأخبرهم أن الله قد فرض عليهم خمس صلوات في كل يوم وليلة، فإن هم طاعوا لك…", "4347"], ["بعث أبي موسى، ومعاذ إلى اليمن قبل حجة الوداع", "حدثنا سليمان بن حرب، حدثنا شعبة، عن حبيب بن أبي ثابت، عن سعيد بن جبير، عن عمرو بن ميمون، أن معاذا رضي الله عنه، لما قدم اليمن، صلى بهم الصبح، فقرأ: \" ﴿واتخذ الله إبراهيم خليلا﴾ فقال رجل من القوم: لقد قرت عين أم إبراهيم \" زاد معاذ، عن شعبة، عن حبيب، عن سعيد، عن عمرو أن النبي صلى الله عليه وسلم بعث…", "4348"], ["بعث علي بن أبي طالب عليه السلام، وخالد بن الوليد رضي الله عنه، إلى اليمن قبل حجة الوداع", "حدثني أحمد بن عثمان، حدثنا شريح بن مسلمة، حدثنا إبراهيم بن يوسف بن إسحاق بن أبي إسحاق، حدثني أبي، عن أبي إسحاق، سمعت البراء رضي الله عنه، بعثنا رسول الله صلى الله عليه وسلم مع خالد بن الوليد إلى اليمن، قال: ثم بعث عليا بعد ذلك مكانه فقال: «مر أصحاب خالد، من شاء منهم أن يعقب معك فليعقب، ومن شاء…", "4349"], ["بعث علي بن أبي طالب عليه السلام، وخالد بن الوليد رضي الله عنه، إلى اليمن قبل حجة الوداع", "حدثني محمد بن بشار، حدثنا روح بن عبادة، حدثنا علي بن سويد بن منجوف، عن عبد الله بن بريدة، عن أبيه رضي الله عنه، قال: بعث النبي صلى الله عليه وسلم عليا إلى خالد ليقبض الخمس، وكنت أبغض عليا وقد اغتسل، فقلت لخالد: ألا ترى إلى هذا، فلما قدمنا على النبي صلى الله عليه وسلم ذكرت ذلك له، فقال: «يا بريدة…", "4350"], ["بعث علي بن أبي طالب عليه السلام، وخالد بن الوليد رضي الله عنه، إلى اليمن قبل حجة الوداع", "حدثنا قتيبة، حدثنا عبد الواحد، عن عمارة بن القعقاع بن شبرمة، حدثنا عبد الرحمن بن أبي نعم، قال: سمعت أبا سعيد الخدري، يقول: بعث علي بن أبي طالب رضي الله عنه إلى رسول الله صلى الله عليه وسلم من اليمن بذهيبة في أديم مقروظ، لم تحصل من ترابها، قال: فقسمها بين أربعة نفر، بين عيينة بن بدر، وأقرع بن حابس،…", "4351"], ["بعث علي بن أبي طالب عليه السلام، وخالد بن الوليد رضي الله عنه، إلى اليمن قبل حجة الوداع", "حدثنا المكي بن إبراهيم، عن ابن جريج، قال: عطاء، قال جابر: «أمر النبي صلى الله عليه وسلم عليا أن يقيم على إحرامه»، زاد محمد بن بكر، عن ابن جريج، قال: عطاء، قال: جابر، فقدم علي بن أبي طالب رضي الله عنه، بسعايته، قال له النبي صلى الله عليه وسلم: «بم أهللت يا علي؟» قال: بما أهل به النبي صلى الله عليه…", "4352"], ["بعث علي بن أبي طالب عليه السلام، وخالد بن الوليد رضي الله عنه، إلى اليمن قبل حجة الوداع", "حدثنا مسدد، حدثنا بشر بن المفضل، عن حميد الطويل، حدثنا بكر، أنه ذكر لابن عمر، أن أنسا حدثهم أن النبي صلى الله عليه وسلم أهل بعمرة وحجة، فقال: أهل النبي صلى الله عليه وسلم بالحج وأهللنا به معه، فلما قدمنا مكة قال: «من لم يكن معه هدي فليجعلها عمرة»، وكان مع النبي صلى الله عليه وسلم هدي، فقدم علينا…", "4353 و4354"], ["غزوة ذي الخلصة", "حدثنا مسدد، حدثنا خالد، حدثنا بيان، عن قيس، عن جرير، قال: كان بيت في الجاهلية يقال له ذو الخلصة ، والكعبة اليمانية، والكعبة الشأمية، فقال لي النبي صلى الله عليه وسلم: «ألا تريحني من ذي الخلصة»، فنفرت في مائة وخمسين راكبا فكسرناه، وقتلنا من وجدنا عنده، فأتيت النبي صلى الله عليه وسلم فأخبرته فدعا لنا…", "4355"], ["غزوة ذي الخلصة", "حدثنا محمد بن المثنى، حدثنا يحيى، حدثنا إسماعيل، حدثنا قيس، قال: قال لي جرير رضي الله عنه: قال لي النبي صلى الله عليه وسلم: «ألا تريحني من ذي الخلصة»، وكان بيتا في خثعم، يسمى الكعبة اليمانية، فانطلقت في خمسين ومائة فارس من أحمس، وكانوا أصحاب خيل، وكنت لا أثبت على الخيل، فضرب في صدري حتى رأيت أثر…", "4356"], ["غزوة ذي الخلصة", "حدثنا يوسف بن موسى، أخبرنا أبو أسامة، عن إسماعيل بن أبي خالد، عن قيس، عن جرير، قال: قال لي رسول الله صلى الله عليه وسلم: «ألا تريحني من ذي الخلصة» فقلت: بلى، فانطلقت في خمسين ومائة فارس من أحمس، وكانوا أصحاب خيل، وكنت لا أثبت على الخيل، فذكرت ذلك للنبي صلى الله عليه وسلم، فضرب يده على صدري حتى رأيت…", "4357"], ["غزوة ذات السلاسل", "حدثنا إسحاق، أخبرنا خالد بن عبد الله، عن خالد الحذاء، عن أبي عثمان، أن رسول الله صلى الله عليه وسلم بعث عمرو بن العاص على جيش ذات السلاسل، قال: فأتيته فقلت: أي الناس أحب إليك؟ قال: «عائشة» قلت: من الرجال؟ قال: «أبوها» قلت: ثم من؟ قال: «عمر» فعد رجالا، فسكت مخافة أن يجعلني في آخرهم", "4358"], ["ذهاب جرير إلى اليمن", "حدثني عبد الله بن أبي شيبة العبسي، حدثنا ابن إدريس، عن إسماعيل بن أبي خالد، عن قيس، عن جرير، قال: كنت بالبحر، فلقيت رجلين من أهل اليمن، ذا كلاع، وذا عمرو، فجعلت أحدثهم عن رسول الله صلى الله عليه وسلم، فقال له: ذو عمرو: لئن كان الذي تذكر من أمر صاحبك، لقد مر على أجله منذ ثلاث، وأقبلا معي حتى إذا كنا…", "4359"], ["باب غزوة سيف البحر، وهم يتلقون عيرا لقريش، وأميرهم أبو عبيدة", "عن جابر بن عبد الله رضي الله عنهما، أنه قال: «بعث رسول الله صلى الله عليه وسلم بعثا قبل الساحل، وأمر عليهم أبا عبيدة بن الجراح» وهم ثلاث مائة، فخرجنا وكنا ببعض الطريق فني الزاد، فأمر أبو عبيدة بأزواد الجيش، فجمع فكان مزودي تمر، فكان يقوتنا كل يوم قليل قليل حتى فني فلم يكن يصيبنا إلا تمرة تمرة،…", "4360"], ["باب غزوة سيف البحر، وهم يتلقون عيرا لقريش، وأميرهم أبو عبيدة", "حدثنا علي بن عبد الله، حدثنا سفيان، قال: الذي حفظناه من عمرو بن دينار، قال: سمعت جابر بن عبد الله يقول: «بعثنا رسول الله صلى الله عليه وسلم ثلاث مائة راكب أميرنا أبو عبيدة بن الجراح نرصد عير قريش»، فأقمنا بالساحل نصف شهر، فأصابنا جوع شديد حتى أكلنا الخبط، فسمي ذلك الجيش جيش الخبط، فألقى لنا البحر…", "4361"], ["باب غزوة سيف البحر، وهم يتلقون عيرا لقريش، وأميرهم أبو عبيدة", "حدثنا مسدد، حدثنا يحيى، عن ابن جريج، قال: أخبرني عمرو، أنه سمع جابرا رضي الله عنه، يقول: غزونا جيش الخبط، وأمر أبو عبيدة فجعنا جوعا شديدا، فألقى البحر حوتا ميتا لم نر مثله، يقال له العنبر، فأكلنا منه نصف شهر، فأخذ أبو عبيدة عظما من عظامه، فمر الراكب تحته فأخبرني أبو الزبير، أنه سمع جابرا، يقول: قال…", "4362"], ["حج أبي بكر بالناس في سنة تسع", "حدثنا سليمان بن داود أبو الربيع، حدثنا فليح، عن الزهري، عن حميد بن عبد الرحمن، عن أبي هريرة، أن أبا بكر الصديق رضي الله عنه بعثه، في الحجة التي أمره النبي صلى الله عليه وسلم قبل حجة الوداع، يوم النحر في رهط يؤذن في الناس «لا يحج بعد العام مشرك، ولا يطوف بالبيت عريان»", "4363"], ["حج أبي بكر بالناس في سنة تسع", "عن البراء رضي الله عنه، قال: \" آخر سورة نزلت كاملة براءة، وآخر سورة نزلت خاتمة سورة النساء ﴿يستفتونك قل الله يفتيكم في الكلالة﴾", "4364"], ["وفد بني تميم", "عن عمران بن حصين رضي الله عنهما، قال: أتى نفر من بني تميم النبي صلى الله عليه وسلم، فقال: «اقبلوا البشرى يا بني تميم». قالوا: يا رسول الله قد بشرتنا فأعطنا، فرئي ذلك في وجهه، فجاء نفر من اليمن، فقال: «اقبلوا البشرى إذ لم يقبلها بنو تميم» قالوا: قد قبلنا يا رسول الله", "4365"], ["وفد بني تميم", "عن أبي هريرة رضي الله عنه، قال: لا أزال أحب بني تميم بعد ثلاث سمعته من رسول الله صلى الله عليه وسلم يقولها فيهم: «هم أشد أمتي على الدجال» وكانت فيهم سبية عند عائشة، فقال: «أعتقيها، فإنها من ولد إسماعيل»، وجاءت صدقاتهم، فقال: \" هذه صدقات قوم، أو: قومي \"", "4366"], ["وفد بني تميم", "حدثني إبراهيم بن موسى، حدثنا هشام بن يوسف، أن ابن جريج، أخبرهم عن ابن أبي مليكة، أن عبد الله بن الزبير، أخبرهم: «أنه قدم ركب من بني تميم على النبي صلى الله عليه وسلم»، فقال أبو بكر: أمر القعقاع بن معبد بن زرارة، قال عمر: بل أمر الأقرع بن حابس، قال أبو بكر: ما أردت إلا خلافي، قال عمر: ما أردت خلافك،…", "4367"], ["باب وفد عبد القيس", "حدثني إسحاق، أخبرنا أبو عامر العقدي، حدثنا قرة، عن أبي جمرة، قلت لابن عباس رضي الله عنهما: إن لي جرة ينتبذ لي نبيذ، فأشربه حلوا في جر، إن أكثرت منه، فجالست القوم فأطلت الجلوس، خشيت أن أفتضح، فقال: قدم وفد عبد القيس على رسول الله صلى الله عليه وسلم، فقال: «مرحبا بالقوم، غير خزايا ولا الندامى»،…", "4368"], ["باب وفد عبد القيس", "حدثنا سليمان بن حرب، حدثنا حماد بن زيد، عن أبي جمرة، قال: سمعت ابن عباس، يقول: قدم وفد عبد القيس على النبي صلى الله عليه وسلم، فقالوا: يا رسول الله، إنا هذا الحي من ربيعة، وقد حالت بيننا وبينك كفار مضر، فلسنا نخلص إليك إلا في شهر حرام، فمرنا بأشياء نأخذ بها، وندعو إليها من وراءنا، قال: «آمركم…", "4369"], ["باب وفد عبد القيس", "حدثنا يحيى بن سليمان، حدثني ابن وهب، أخبرني عمرو، وقال: بكر بن مضر، عن عمرو بن الحارث، عن بكير، أن كريبا، مولى ابن عباس، حدثه أن ابن عباس، وعبد الرحمن بن أزهر، والمسور بن مخرمة أرسلوا إلى عائشة رضي الله عنها، فقالوا: اقرأ عليها السلام منا جميعا، وسلها عن الركعتين بعد العصر، وإنا أخبرنا أنك تصليها،…", "4370"], ["باب وفد عبد القيس", "عن ابن عباس رضي الله عنهما، قال: \" أول جمعة جمعت، بعد جمعة جمعت في مسجد رسول الله صلى الله عليه وسلم، في مسجد عبد القيس بجواثى، يعني قرية من البحرين", "4371"], ["أثال", "حدثنا عبد الله بن يوسف، حدثنا الليث، قال: حدثني سعيد بن أبي سعيد، أنه سمع أبا هريرة رضي الله عنه، قال: بعث النبي صلى الله عليه وسلم خيلا قبل نجد، فجاءت برجل من بني حنيفة يقال له ثمامة بن أثال، فربطوه بسارية من سواري المسجد، فخرج إليه النبي صلى الله عليه وسلم، فقال: «ما عندك يا ثمامة؟» فقال: عندي…", "4372"], ["أثال", "عن ابن عباس رضي الله عنهما، قال: قدم مسيلمة الكذاب على عهد رسول الله صلى الله عليه وسلم، فجعل يقول: إن جعل لي محمد من بعده تبعته، وقدمها في بشر كثير من قومه، فأقبل إليه رسول الله صلى الله عليه وسلم ومعه ثابت بن قيس بن شماس، وفي يد رسول الله صلى الله عليه وسلم قطعة جريد، حتى وقف على مسيلمة في…", "4373"], ["أثال", "قال ابن عباس: فسألت عن قول رسول الله صلى الله عليه وسلم: «إنك أرى الذي أريت فيه ما رأيت، فأخبرني أبو هريرة: أن رسول الله صلى الله عليه وسلم قال: \" بينا أنا نائم، رأيت في يدي سوارين من ذهب، فأهمني شأنهما، فأوحي إلي في المنام: أن انفخهما، فنفختهما فطارا، فأولتهما كذابين يخرجان بعدي \" أحدهما العنسي،…", "4374"], ["أثال", "حدثنا إسحاق بن نصر، حدثنا عبد الرزاق، عن معمر، عن همام، أنه سمع أبا هريرة رضي الله عنه، يقول: قال رسول الله صلى الله عليه وسلم: «بينا أنا نائم أتيت بخزائن الأرض، فوضع في كفي سواران من ذهب، فكبرا علي، فأوحى إلي أن انفخهما، فنفختهما فذهبا، فأولتهما الكذابين اللذين أنا بينهما، صاحب صنعاء، وصاحب…", "4375"], ["أثال", "حدثنا الصلت بن محمد، قال: سمعت مهدي بن ميمون، قال: سمعت أبا رجاء العطاردي، يقول: \" كنا نعبد الحجر، فإذا وجدنا حجرا هو أخير منه ألقيناه، وأخذنا الآخر، فإذا لم نجد حجرا جمعنا جثوة من تراب، ثم جئنا بالشاة فحلبناه عليه، ثم طفنا به، فإذا دخل شهر رجب قلنا: منصل الأسنة، فلا ندع رمحا فيه حديدة، ولا سهما…", "4376"], ["أثال", "وسمعت أبا رجاء يقول: «كنت يوم بعث النبي صلى الله عليه وسلم غلاما أرعى الإبل على أهلي، فلما سمعنا بخروجه فررنا إلى النار، إلى مسيلمة الكذاب»", "4377"], ["قصة الأسود العنسي", "حدثنا سعيد بن محمد الجرمي، حدثنا يعقوب بن إبراهيم، حدثنا أبي، عن صالح، عن ابن عبيدة بن نشيط، وكان في موضع آخر اسمه عبد الله، أن عبيد الله بن عبد الله بن عتبة، قال: بلغنا أن مسيلمة الكذاب قدم المدينة فنزل في دار بنت الحارث، وكان تحته بنت الحارث بن كريز، وهي أم عبد الله بن عامر، فأتاه رسول الله صلى…", "4378"], ["قصة الأسود العنسي", "قال: عبيد الله بن عبد الله: سألت عبد الله بن عباس عن رؤيا رسول الله صلى الله عليه وسلم التي ذكر، فقال ابن عباس: ذكر لي أن رسول الله صلى الله عليه وسلم، قال: «بينا أنا نائم أريت أنه وضع في يدي سواران من ذهب ففظعتهما وكرهتهما، فأذن لي فنفختهما فطارا، فأولتهما كذابين يخرجان» فقال عبيد الله: أحدهما…", "4379"], ["باب قصة أهل نجران", "حدثني عباس بن الحسين، حدثنا يحيى بن آدم، عن إسرائيل، عن أبي إسحاق، عن صلة بن زفر، عن حذيفة، قال: جاء العاقب والسيد، صاحبا نجران، إلى رسول الله صلى الله عليه وسلم يريدان أن يلاعناه، قال: فقال أحدهما لصاحبه: لا تفعل، فوالله لئن كان نبيا فلاعنا لا نفلح نحن، ولا عقبنا من بعدنا، قالا: إنا نعطيك ما…", "4380"], ["باب قصة أهل نجران", "عن حذيفة رضي الله عنه، قال: جاء أهل نجران إلى النبي صلى الله عليه وسلم فقالوا: ابعث لنا رجلا أمينا فقال: «لأبعثن إليكم رجلا أمينا حق أمين، فاستشرف له الناس فبعث أبا عبيدة بن الجراح»", "4381"], ["باب قصة أهل نجران", "حدثنا أبو الوليد، حدثنا شعبة، عن خالد، عن أبي قلابة، عن أنس، عن النبي صلى الله عليه وسلم، قال: «لكل أمة أمين، وأمين هذه الأمة أبو عبيدة بن الجراح»", "4382"], ["قصة عمان والبحرين", "حدثنا قتيبة بن سعيد، حدثنا سفيان، سمع ابن المنكدر، جابر بن عبد الله رضي الله عنهما، يقول: قال لي رسول الله صلى الله عليه وسلم: «لو قد جاء مال البحرين لقد أعطيتك هكذا، وهكذا». ثلاثا، فلم يقدم مال البحرين حتى قبض رسول الله صلى الله عليه وسلم، فلما قدم على أبي بكر أمر مناديا فنادى: من كان له عند النبي…", "4383"], ["باب قدوم الأشعريين", "عن أبي موسى رضي الله عنه، قال: «قدمت أنا وأخي من اليمن، فمكثنا حينا، ما نرى ابن مسعود وأمه، إلا من أهل البيت، من كثرة دخولهم ولزومهم له»", "4384"], ["باب قدوم الأشعريين", "حدثنا أبو نعيم، حدثنا عبد السلام، عن أيوب، عن أبي قلابة، عن زهدم، قال: لما قدم أبو موسى أكرم هذا الحي من جرم، وإنا لجلوس عنده، وهو يتغدى دجاجا، وفي القوم رجل جالس، فدعاه إلى الغداء، فقال: إني رأيته يأكل شيئا فقذرته، فقال: هلم، فإني رأيت النبي صلى الله عليه وسلم يأكله، فقال: إني حلفت لا آكله، فقال:…", "4385"], ["باب قدوم الأشعريين", "حدثني عمرو بن علي، حدثنا أبو عاصم، حدثنا سفيان، حدثنا أبو صخرة جامع بن شداد، حدثنا صفوان بن محرز المازني، حدثنا عمران بن حصين، قال: جاءت بنو تميم إلى رسول الله صلى الله عليه وسلم، فقال: «أبشروا يا بني تميم» قالوا: أما إذ بشرتنا فأعطنا، فتغير وجه رسول الله صلى الله عليه وسلم فجاء ناس من أهل اليمن…", "4386"], ["باب قدوم الأشعريين", "حدثني عبد الله بن محمد الجعفي، حدثنا وهب بن جرير، حدثنا شعبة، عن إسماعيل بن أبي خالد، عن قيس بن أبي حازم، عن أبي مسعود، أن النبي صلى الله عليه وسلم، قال: «الإيمان ها هنا وأشار بيده إلى اليمن، والجفاء وغلظ القلوب في الفدادين عند أصول أذناب الإبل، من حيث يطلع قرنا الشيطان ربيعة، ومضر»", "4387"], ["باب قدوم الأشعريين", "عن أبي هريرة رضي الله عنه، عن النبي صلى الله عليه وسلم: قال «أتاكم أهل اليمن، هم أرق أفئدة وألين قلوبا، الإيمان يمان والحكمة يمانية، والفخر والخيلاء في أصحاب الإبل، والسكينة والوقار في أهل الغنم»، وقال: غندر، عن شعبة، عن سليمان، سمعت ذكوان، عن أبي هريرة ، عن النبي صلى الله عليه وسلم", "4388"], ["باب قدوم الأشعريين", "حدثنا إسماعيل، قال: حدثني أخي، عن سليمان، عن ثور بن زيد، عن أبي الغيث، عن أبي هريرة، أن النبي صلى الله عليه وسلم، قال: «الإيمان يمان، والفتنة ها هنا، ها هنا يطلع قرن الشيطان»", "4389"], ["باب قدوم الأشعريين", "عن أبي هريرة رضي الله عنه، عن النبي صلى الله عليه وسلم، قال: «أتاكم أهل اليمن، أضعف قلوبا، وأرق أفئدة، الفقه يمان والحكمة يمانية»", "4390"], ["باب قدوم الأشعريين", "حدثنا عبدان، عن أبي حمزة، عن الأعمش، عن إبراهيم، عن علقمة، قال: \" كنا جلوسا مع ابن مسعود، فجاء خباب، فقال: يا أبا عبد الرحمن، أيستطيع هؤلاء الشباب أن يقرءوا كما تقرأ؟ قال: أما إنك لو شئت أمرت بعضهم يقرأ عليك؟ قال: أجل، قال: اقرأ يا علقمة، فقال زيد بن حدير، أخو زياد بن حدير: أتأمر علقمة أن يقرأ وليس…", "4391"], ["قصة دوس، والطفيل بن عمرو الدوسي", "عن أبي هريرة رضي الله عنه، قال: جاء الطفيل بن عمرو إلى النبي صلى الله عليه وسلم فقال: إن دوسا قد هلكت عصت وأبت فادع الله عليهم، فقال: «اللهم اهد دوسا وأت بهم»", "4392"], ["قصة دوس، والطفيل بن عمرو الدوسي", "حدثني محمد بن العلاء، حدثنا أبو أسامة، حدثنا إسماعيل، عن قيس، عن أبي هريرة، قال: لما قدمت على النبي صلى الله عليه وسلم قلت في الطريق: يا ليلة من طولها وعنائها ... على أنها من دارة الكفر نجت وأبق غلام لي في الطريق، فلما قدمت على النبي صلى الله عليه وسلم فبايعته، فبينا أنا عنده إذ طلع الغلام، فقال لي…", "4393"], ["باب قصة وفد طيئ وحديث عدي بن حاتم", "حدثنا موسى بن إسماعيل، حدثنا أبو عوانة، حدثنا عبد الملك، عن عمرو بن حريث، عن عدي بن حاتم، قال: أتينا عمر في وفد، فجعل يدعو رجلا رجلا ويسميهم، فقلت: أما تعرفني يا أمير المؤمنين؟ قال: بلى «أسلمت إذ كفروا، وأقبلت إذ أدبروا، ووفيت إذ غدروا، وعرفت إذ أنكروا». فقال عدي: فلا أبالي إذا", "4394"], ["باب حجة الوداع", "عن عائشة رضي الله عنها، قالت: خرجنا مع رسول الله صلى الله عليه وسلم في حجة الوداع، فأهللنا بعمرة، ثم قال رسول الله صلى الله عليه وسلم: «من كان معه هدي فليهلل بالحج مع العمرة، ثم لا يحل حتى يحل منهما جميعا»، فقدمت معه مكة وأنا حائض، ولم أطف بالبيت، ولا بين الصفا والمروة، فشكوت إلى رسول الله صلى الله…", "4395"], ["باب حجة الوداع", "حدثني عمرو بن علي، حدثنا يحيى بن سعيد، حدثنا ابن جريج، قال: حدثني عطاء، عن ابن عباس: إذا طاف بالبيت فقد حل، فقلت: من أين؟ قال: هذا ابن عباس قال: من قول الله تعالى: ﴿ثم محلها إلى البيت العتيق﴾ ومن «أمر النبي صلى الله عليه وسلم أصحابه أن يحلوا في حجة الوداع»، قلت: إنما كان ذلك بعد المعرف قال: كان ابن…", "4396"], ["باب حجة الوداع", "عن أبي موسى الأشعري رضي الله عنه، قال: قدمت على النبي صلى الله عليه وسلم بالبطحاء، فقال: «أحججت» قلت: نعم، قال: «كيف أهللت» قلت: لبيك بإهلال كإهلال رسول الله صلى الله عليه وسلم، قال: «طف بالبيت، وبالصفا، والمروة، ثم حل» فطفت بالبيت وبالصفا والمروة، وأتيت امرأة من قيس، ففلت رأسي", "4397"], ["باب حجة الوداع", "حدثني إبراهيم بن المنذر، أخبرنا أنس بن عياض، حدثنا موسى بن عقبة، عن نافع، أن ابن عمر، أخبره أن حفصة رضي الله عنها زوج النبي صلى الله عليه وسلم، أخبرته: أن النبي صلى الله عليه وسلم أمر أزواجه أن يحللن عام حجة الوداع، فقالت حفصة: فما يمنعك؟ فقال: «لبدت رأسي، وقلدت هديي، فلست أحل حتى أنحر هديي»", "4398"], ["باب حجة الوداع", "عن ابن عباس رضي الله عنهما، أن امرأة من خثعم استفتت رسول الله صلى الله عليه وسلم في حجة الوداع، والفضل بن عباس رديف رسول الله صلى الله عليه وسلم، فقالت: يا رسول الله، إن فريضة الله على عباده أدركت أبي شيخا كبيرا، لا يستطيع أن يستوي على الراحلة، فهل يقضي أن أحج عنه؟ قال: «نعم»", "4399"], ["باب حجة الوداع", "عن ابن عمر رضي الله عنهما، قال: أقبل النبي صلى الله عليه وسلم عام الفتح، وهو مردف أسامة على القصواء، ومعه بلال، وعثمان بن طلحة، حتى أناخ عند البيت، ثم قال لعثمان: «ائتنا بالمفتاح». فجاءه بالمفتاح ففتح له الباب، فدخل النبي صلى الله عليه وسلم وأسامة، وبلال، وعثمان، ثم أغلقوا عليهم الباب، فمكث نهارا…", "4400"], ["باب حجة الوداع", "حدثنا أبو اليمان، أخبرنا شعيب، عن الزهري، حدثني عروة بن الزبير، وأبو سلمة بن عبد الرحمن، أن عائشة زوج النبي صلى الله عليه وسلم، أخبرتهما أن صفية بنت حيي زوج النبي صلى الله عليه وسلم، حاضت في حجة الوداع، فقال النبي صلى الله عليه وسلم: «أحابستنا هي» فقلت: إنها قد أفاضت يا رسول الله وطافت بالبيت، فقال…", "4401"], ["باب حجة الوداع", "عن ابن عمر رضي الله عنهما، قال: كنا نتحدث بحجة الوداع، والنبي صلى الله عليه وسلم بين أظهرنا، ولا ندري ما حجة الوداع، فحمد الله وأثنى عليه، ثم ذكر المسيح الدجال فأطنب في ذكره، وقال: \" ما بعث الله من نبي إلا أنذر أمته، أنذره نوح والنبيون من بعده، وإنه يخرج فيكم، فما خفي عليكم من شأنه فليس يخفى عليكم:…", "4402"], ["باب حجة الوداع", "ألا إن الله حرم عليكم دماءكم وأموالكم، كحرمة يومكم هذا، في بلدكم هذا، في شهركم هذا، ألا هل بلغت \" قالوا: نعم، قال: «اللهم اشهد - ثلاثا - ويلكم، أو ويحكم، انظروا، لا ترجعوا بعدي كفارا، يضرب بعضكم رقاب بعض»", "4403"], ["باب حجة الوداع", "حدثنا عمرو بن خالد، حدثنا زهير، حدثنا أبو إسحاق، قال: حدثني زيد بن أرقم، أن النبي صلى الله عليه وسلم «غزا تسع عشرة غزوة، وأنه حج بعد ما هاجر حجة واحدة، لم يحج بعدها حجة الوداع»، قال أبو إسحاق: «وبمكة أخرى»", "4404"], ["باب حجة الوداع", "حدثنا حفص بن عمر، حدثنا شعبة، عن علي بن مدرك، عن أبي زرعة بن عمرو بن جرير، عن جرير، أن النبي صلى الله عليه وسلم، قال: في حجة الوداع لجرير: «استنصت الناس» فقال: «لا ترجعوا بعدي كفارا، يضرب بعضكم رقاب بعض»", "4405"], ["باب حجة الوداع", "حدثني محمد بن المثنى، حدثنا عبد الوهاب، حدثنا أيوب، عن محمد، عن ابن أبي بكرة، عن أبي بكرة، عن النبي صلى الله عليه وسلم، قال: \" الزمان قد استدار كهيئة يوم خلق السموات والأرض، السنة اثنا عشر شهرا منها أربعة حرم: ثلاثة متواليات: ذو القعدة، وذو الحجة، والمحرم، ورجب مضر، الذي بين جمادى وشعبان، أي شهر…", "4406"], ["باب حجة الوداع", "حدثنا محمد بن يوسف، حدثنا سفيان الثوري، عن قيس بن مسلم، عن طارق بن شهاب، أن أناسا، من اليهود قالوا: لو نزلت هذه الآية فينا لاتخذنا ذلك اليوم عيدا، فقال عمر: أية آية؟ فقالوا: ﴿اليوم أكملت لكم دينكم وأتممت عليكم نعمتي﴾. فقال عمر: «إني لأعلم أي مكان أنزلت أنزلت، ورسول الله صلى الله عليه وسلم واقف…", "4407"], ["باب حجة الوداع", "عن عائشة رضي الله عنها، قالت : خرجنا مع رسول الله صلى الله عليه وسلم، فمنا من أهل بعمرة، ومنا من أهل بحجة، ومنا من أهل بحج وعمرة، «وأهل رسول الله صلى الله عليه وسلم بالحج»، فأما من أهل بالحج أو جمع الحج والعمرة، فلم يحلوا حتى يوم النحر حدثنا عبد الله بن يوسف، أخبرنا مالك، وقال: مع رسول الله صلى…", "4408"], ["باب حجة الوداع", "حدثنا أحمد بن يونس، حدثنا إبراهيم هو ابن سعد، حدثنا ابن شهاب، عن عامر بن سعد، عن أبيه، قال: عادني النبي صلى الله عليه وسلم في حجة الوداع، من وجع أشفيت منه على الموت، فقلت: يا رسول الله، بلغ بي من الوجع ما ترى، وأنا ذو مال، ولا يرثني إلا ابنة لي واحدة، أفأتصدق بثلثي مالي؟ قال: «لا» قلت: أفأتصدق…", "4409"], ["باب حجة الوداع", "حدثني إبراهيم بن المنذر، حدثنا أبو ضمرة، حدثنا موسى بن عقبة، عن نافع، أن ابن عمر رضي الله عنهما، أخبرهم: «أن رسول الله صلى الله عليه وسلم حلق رأسه في حجة الوداع»", "4410"], ["باب حجة الوداع", "حدثنا عبيد الله بن سعيد، حدثنا محمد بن بكر، حدثنا ابن جريج، أخبرني موسى بن عقبة، عن نافع، أخبره ابن عمر، «أن النبي صلى الله عليه وسلم حلق في حجة الوداع، وأناس من أصحابه وقصر بعضهم»", "4411"], ["باب حجة الوداع", "حدثنا يحيى بن قزعة، حدثنا مالك، عن ابن شهاب، وقال الليث: حدثني يونس، عن ابن شهاب، حدثني عبيد الله بن عبد الله، أن عبد الله بن عباس رضي الله عنهما، أخبره «أنه أقبل يسير على حمار، ورسول الله صلى الله عليه وسلم قائم بمنى في حجة الوداع يصلي بالناس، فسار الحمار بين يدي بعض الصف، ثم نزل عنه فصف مع الناس»", "4412"], ["باب حجة الوداع", "حدثنا مسدد، حدثنا يحيى، عن هشام، قال: حدثني أبي قال: سئل أسامة وأنا شاهد عن سير النبي صلى الله عليه وسلم في حجته؟ فقال: «العنق فإذا وجد فجوة نص»", "4413"], ["باب حجة الوداع", "حدثنا عبد الله بن مسلمة، عن مالك، عن يحيى بن سعيد، عن عدي بن ثابت، عن عبد الله بن يزيد الخطمي، أن أبا أيوب، أخبره: أنه «صلى مع رسول الله صلى الله عليه وسلم في حجة الوداع المغرب والعشاء جميعا»", "4414"], ["باب غزوة تبوك وهي غزوة العسرة", "عن أبي موسى رضي الله عنه، قال: أرسلني أصحابي إلى رسول الله صلى الله عليه وسلم أسأله الحملان لهم، إذ هم معه في جيش العسرة، وهي غزوة تبوك فقلت يا نبي الله، إن أصحابي أرسلوني إليك لتحملهم، فقال «والله لا أحملكم على شيء ووافقته، وهو غضبان ولا أشعر» ورجعت حزينا من منع النبي صلى الله عليه وسلم، ومن مخافة…", "4415"], ["باب غزوة تبوك وهي غزوة العسرة", "حدثنا مسدد، حدثنا يحيى، عن شعبة، عن الحكم، عن مصعب بن سعد، عن أبيه، أن رسول الله صلى الله عليه وسلم خرج إلى تبوك، واستخلف عليا، فقال: أتخلفني في الصبيان والنساء؟ قال: «ألا ترضى أن تكون مني بمنزلة هارون، من موسى إلا أنه ليس نبي بعدي»، وقال أبو داود: حدثنا شعبة، عن الحكم، سمعت مصعبا", "4416"], ["باب غزوة تبوك وهي غزوة العسرة", "حدثنا عبيد الله بن سعيد، حدثنا محمد بن بكر، أخبرنا ابن جريج، قال: سمعت عطاء، يخبر قال: أخبرني صفوان بن يعلى بن أمية، عن أبيه، قال: غزوت مع النبي صلى الله عليه وسلم العسرة، قال: كان يعلى يقول: تلك الغزوة أوثق أعمالي عندي، قال عطاء: فقال صفوان: قال يعلى: فكان لي أجير، فقاتل إنسانا فعض أحدهما يد…", "4417"], ["حديث كعب بن مالك، وقول الله عز وجل: {وعلى الثلاثة الذين خلفوا}", "حدثنا يحيى بن بكير، حدثنا الليث، عن عقيل، عن ابن شهاب، عن عبد الرحمن بن عبد الله بن كعب بن مالك، أن عبد الله بن كعب بن مالك، وكان، قائد كعب من بنيه، حين عمي، قال: سمعت كعب بن مالك، يحدث حين تخلف عن قصة، تبوك، قال كعب: لم أتخلف عن رسول الله صلى الله عليه وسلم في غزوة غزاها إلا في غزوة تبوك، غير أني…", "4418"], ["نزول النبي صلى الله عليه وسلم الحجر", "عن ابن عمر رضي الله عنهما، قال: لما مر النبي صلى الله عليه وسلم بالحجر قال: «لا تدخلوا مساكن الذين ظلموا أنفسهم، أن يصيبكم ما أصابهم، إلا أن تكونوا باكين، ثم قنع رأسه وأسرع السير حتى أجاز الوادي»", "4419"], ["نزول النبي صلى الله عليه وسلم الحجر", "عن ابن عمر رضي الله عنهما، قال: قال رسول الله صلى الله عليه وسلم لأصحاب الحجر: «لا تدخلوا على هؤلاء المعذبين إلا أن تكونوا باكين، أن يصيبكم مثل ما أصابهم»", "4420"], ["نزول النبي صلى الله عليه وسلم الحجر", "حدثنا يحيى بن بكير، عن الليث، عن عبد العزيز بن أبي سلمة، عن سعد بن إبراهيم، عن نافع بن جبير، عن عروة بن المغيرة، عن أبيه المغيرة بن شعبة، قال: «ذهب النبي صلى الله عليه وسلم لبعض حاجته، فقمت أسكب عليه الماء، - لا أعلمه إلا قال في غزوة تبوك - فغسل وجهه، وذهب يغسل ذراعيه، فضاق عليه كم الجبة، فأخرجهما…", "4421"], ["نزول النبي صلى الله عليه وسلم الحجر", "حدثنا خالد بن مخلد، حدثنا سليمان، قال: حدثني عمرو بن يحيى، عن عباس بن سهل بن سعد، عن أبي حميد، قال: أقبلنا مع النبي صلى الله عليه وسلم من غزوة تبوك، حتى إذا أشرفنا على المدينة قال: هذه طابة، وهذا أحد، جبل يحبنا ونحبه \"", "4422"], ["نزول النبي صلى الله عليه وسلم الحجر", "عن أنس بن مالك رضي الله عنه، أن رسول الله صلى الله عليه وسلم رجع من غزوة تبوك فدنا من المدينة، فقال: «إن بالمدينة أقواما، ما سرتم مسيرا، ولا قطعتم واديا إلا كانوا معكم»، قالوا: يا رسول الله، وهم بالمدينة؟ قال: «وهم بالمدينة، حبسهم العذر»", "4423"], ["باب كتاب النبي صلى الله عليه وسلم إلى كسرى وقيصر", "حدثنا إسحاق، حدثنا يعقوب بن إبراهيم، حدثنا أبي، عن صالح، عن ابن شهاب، قال: أخبرني عبيد الله بن عبد الله، أن ابن عباس، أخبره \" أن رسول الله صلى الله عليه وسلم: بعث بكتابه إلى كسرى، مع عبد الله بن حذافة السهمي \" فأمره أن يدفعه إلى عظيم البحرين، فدفعه عظيم البحرين إلى كسرى، فلما قرأه مزقه، فحسبت أن…", "4424"], ["باب كتاب النبي صلى الله عليه وسلم إلى كسرى وقيصر", "حدثنا عثمان بن الهيثم، حدثنا عوف، عن الحسن، عن أبي بكرة، قال: لقد نفعني الله بكلمة سمعتها من رسول الله صلى الله عليه وسلم أيام الجمل، بعد ما كدت أن ألحق بأصحاب الجمل فأقاتل معهم، قال: لما بلغ رسول الله صلى الله عليه وسلم أن أهل فارس، قد ملكوا عليهم بنت كسرى، قال: «لن يفلح قوم ولوا أمرهم امرأة»", "4425"], ["باب كتاب النبي صلى الله عليه وسلم إلى كسرى وقيصر", "حدثنا علي بن عبد الله، حدثنا سفيان، قال: سمعت الزهري، عن السائب بن يزيد، يقول: أذكر أني «خرجت مع الغلمان إلى ثنية الوداع، نتلقى رسول الله صلى الله عليه وسلم»، وقال سفيان مرة : «مع الصبيان»", "4426"], ["باب كتاب النبي صلى الله عليه وسلم إلى كسرى وقيصر", "حدثنا عبد الله بن محمد، حدثنا سفيان، عن الزهري، عن السائب، أذكر أني «خرجت مع الصبيان نتلقى النبي صلى الله عليه وسلم، إلى ثنية الوداع مقدمه من غزوة تبوك»", "4427"], ["باب مرض النبي صلى الله عليه وسلم ووفاته", "وقال يونس عن الزهري، قال عروة: قالت عائشة رضي الله عنها: كان النبي صلى الله عليه وسلم يقول في مرضه الذي مات فيه: «يا عائشة ما أزال أجد ألم الطعام الذي أكلت بخيبر، فهذا أوان وجدت انقطاع أبهري من ذلك السم»", "4428"], ["باب مرض النبي صلى الله عليه وسلم ووفاته", "حدثنا يحيى بن بكير، حدثنا الليث، عن عقيل، عن ابن شهاب، عن عبيد الله بن عبد الله، عن عبد الله بن عباس رضي الله عنهما، عن أم الفضل بنت الحارث، قالت: سمعت النبي صلى الله عليه وسلم: «يقرأ في المغرب بالمرسلات عرفا، ثم ما صلى لنا بعدها حتى قبضه الله»", "4429"], ["باب مرض النبي صلى الله عليه وسلم ووفاته", "حدثنا محمد بن عرعرة، حدثنا شعبة، عن أبي بشر، عن سعيد بن جبير، عن ابن عباس، قال: كان عمر بن الخطاب رضي الله عنه، يدني ابن عباس، فقال له عبد الرحمن بن عوف: إن لنا أبناء مثله، فقال: إنه من حيث تعلم، فسأل عمر، ابن عباس عن هذه الآية: ﴿إذا جاء نصر الله والفتح﴾. فقال: «أجل رسول الله صلى الله عليه وسلم…", "4430"], ["باب مرض النبي صلى الله عليه وسلم ووفاته", "حدثنا قتيبة، حدثنا سفيان، عن سليمان الأحول، عن سعيد بن جبير، قال: قال ابن عباس: يوم الخميس، وما يوم الخميس؟ اشتد برسول الله صلى الله عليه وسلم وجعه، فقال: «ائتوني أكتب لكم كتابا لن تضلوا بعده أبدا»، فتنازعوا ولا ينبغي عند نبي تنازع، فقالوا: ما شأنه، أهجر استفهموه؟ فذهبوا يردون عليه، فقال: «دعوني،…", "4431"], ["باب مرض النبي صلى الله عليه وسلم ووفاته", "عن ابن عباس رضي الله عنهما، قال: لما حضر رسول الله صلى الله عليه وسلم وفي البيت رجال، فقال النبي صلى الله عليه وسلم: «هلموا أكتب لكم كتابا لا تضلوا بعده»، فقال بعضهم: إن رسول الله صلى الله عليه وسلم قد غلبه الوجع، وعندكم القرآن حسبنا، كتاب الله فاختلف أهل البيت واختصموا، فمنهم من يقول قربوا يكتب…", "4432"], ["باب مرض النبي صلى الله عليه وسلم ووفاته", "عن عائشة رضي الله عنها، قالت: دعا النبي صلى الله عليه وسلم فاطمة عليها السلام في شكواه الذي قبض فيه، فسارها بشيء فبكت، ثم دعاها فسارها بشيء فضحكت، فسألنا عن ذلك فقالت: «سارني النبي صلى الله عليه وسلم أنه يقبض في وجعه الذي توفي فيه فبكيت، ثم سارني فأخبرني أني أول أهله يتبعه فضحكت»", "4433 و4434"], ["باب مرض النبي صلى الله عليه وسلم ووفاته", "حدثني محمد بن بشار، حدثنا غندر، حدثنا شعبة، عن سعد، عن عروة، عن عائشة، قالت: كنت أسمع: \" أنه لا يموت نبي حتى يخير بين الدنيا والآخرة، فسمعت النبي صلى الله عليه وسلم يقول في مرضه الذي مات فيه، وأخذته بحة، يقول: ﴿مع الذين أنعم الله عليهم﴾ الآية فظننت أنه خير \"", "4435"], ["باب مرض النبي صلى الله عليه وسلم ووفاته", "حدثنا مسلم، حدثنا شعبة، عن سعد، عن عروة، عن عائشة، قالت: لما مرض النبي صلى الله عليه وسلم المرض الذي مات فيه جعل يقول: «في الرفيق الأعلى»", "4436"], ["باب مرض النبي صلى الله عليه وسلم ووفاته", "حدثنا أبو اليمان، أخبرنا شعيب، عن الزهري، قال: عروة بن الزبير، إن عائشة، قالت: كان رسول الله صلى الله عليه وسلم، وهو صحيح يقول: \" إنه لم يقبض نبي قط حتى يرى مقعده من الجنة، ثم يحيا أو يخير، فلما اشتكى وحضره القبض ورأسه على فخذ عائشة غشي عليه، فلما أفاق شخص بصره نحو سقف البيت، ثم قال: «اللهم في…", "4437"], ["باب مرض النبي صلى الله عليه وسلم ووفاته", "حدثنا محمد، حدثنا عفان، عن صخر بن جويرية، عن عبد الرحمن بن القاسم، عن أبيه، عن عائشة، دخل عبد الرحمن بن أبي بكر على النبي صلى الله عليه وسلم وأنا مسندته إلى صدري، ومع عبد الرحمن سواك رطب يستن به، فأبده رسول الله صلى الله عليه وسلم بصره، فأخذت السواك فقصمته، ونفضته وطيبته، ثم دفعته إلى النبي صلى…", "4438"], ["باب مرض النبي صلى الله عليه وسلم ووفاته", "حدثني حبان، أخبرنا عبد الله، أخبرنا يونس، عن ابن شهاب، قال: أخبرني عروة، أن عائشة، رضي الله عنها، أخبرته: «أن رسول الله صلى الله عليه وسلم كان إذا اشتكى نفث على نفسه بالمعوذات، ومسح عنه بيده، فلما اشتكى وجعه الذي توفي فيه، طفقت أنفث على نفسه بالمعوذات التي كان ينفث، وأمسح بيد النبي صلى الله عليه…", "4439"], ["باب مرض النبي صلى الله عليه وسلم ووفاته", "حدثنا معلى بن أسد، حدثنا عبد العزيز بن مختار، حدثنا هشام بن عروة، عن عباد بن عبد الله بن الزبير، أن عائشة، أخبرته أنها سمعت النبي صلى الله عليه وسلم وأصغت إليه قبل أن يموت، وهو مسند إلي ظهره يقول: «اللهم اغفر لي وارحمني، وألحقني بالرفيق»", "4440"], ["باب مرض النبي صلى الله عليه وسلم ووفاته", "عن عائشة رضي الله عنها، قالت: قال النبي صلى الله عليه وسلم في مرضه الذي لم يقم منه: «لعن الله اليهود اتخذوا قبور أنبيائهم مساجد»، قالت عائشة: «لولا ذلك لأبرز قبره خشي أن يتخذ مسجدا»", "4441"], ["باب مرض النبي صلى الله عليه وسلم ووفاته", "حدثنا سعيد بن عفير، قال: حدثني الليث، قال: حدثني عقيل، عن ابن شهاب، قال: أخبرني عبيد الله بن عبد الله بن عتبة بن مسعود، أن عائشة زوج النبي صلى الله عليه وسلم، قالت: لما ثقل رسول الله صلى الله عليه وسلم واشتد به وجعه، استأذن أزواجه أن يمرض في بيتي، فأذن له، فخرج وهو بين الرجلين تخط رجلاه في الأرض،…", "4442"], ["باب مرض النبي صلى الله عليه وسلم ووفاته", "وأخبرني عبيد الله بن عبد الله بن عتبة، أن عائشة، وعبد الله بن عباس رضي الله عنهم، قالا: لما نزل برسول الله صلى الله عليه وسلم، طفق يطرح خميصة له على وجهه، فإذا اغتم كشفها عن وجهه، وهو كذلك يقول: «لعنة الله على اليهود، والنصارى اتخذوا قبور أنبيائهم مساجد» يحذر ما صنعوا \"", "4443 و4444"], ["باب مرض النبي صلى الله عليه وسلم ووفاته", "أخبرني عبيد الله، أن عائشة، قالت: \" لقد راجعت رسول الله صلى الله عليه وسلم في ذلك، وما حملني على كثرة مراجعته إلا أنه لم يقع في قلبي: أن يحب الناس بعده رجلا، قام مقامه أبدا، ولا كنت أرى أنه لن يقوم أحد مقامه إلا تشاءم الناس به، فأردت أن يعدل ذلك رسول الله صلى الله عليه وسلم عن أبي بكر \" رواه ابن…", "4445"], ["باب مرض النبي صلى الله عليه وسلم ووفاته", "حدثنا عبد الله بن يوسف، حدثنا الليث، قال: حدثني ابن الهاد، عن عبد الرحمن بن القاسم، عن أبيه، عن عائشة، قالت: «مات النبي صلى الله عليه وسلم وإنه لبين حاقنتي وذاقنتي، فلا أكره شدة الموت لأحد أبدا، بعد النبي صلى الله عليه وسلم»", "4446"], ["باب مرض النبي صلى الله عليه وسلم ووفاته", "حدثني إسحاق، أخبرنا بشر بن شعيب بن أبي حمزة، قال: حدثني أبي، عن الزهري، قال: أخبرني عبد الله بن كعب بن مالك الأنصاري، وكان كعب بن مالك أحد الثلاثة الذين تيب عليهم أن عبد الله بن عباس، أخبره أن علي بن أبي طالب رضي الله عنه، خرج من عند رسول الله صلى الله عليه وسلم في وجعه الذي توفي فيه، فقال الناس:…", "4447"], ["باب مرض النبي صلى الله عليه وسلم ووفاته", "عن أنس بن مالك رضي الله عنه، أن المسلمين بينا هم في صلاة الفجر من يوم الاثنين، وأبو بكر يصلي لهم، لم يفجأهم إلا رسول الله صلى الله عليه وسلم قد «كشف ستر حجرة عائشة، فنظر إليهم وهم في صفوف الصلاة، ثم تبسم يضحك»، فنكص أبو بكر على عقبيه ليصل الصف، وظن أن رسول الله صلى الله عليه وسلم يريد أن يخرج إلى…", "4448"], ["باب مرض النبي صلى الله عليه وسلم ووفاته", "حدثني محمد بن عبيد، حدثنا عيسى بن يونس، عن عمر بن سعيد، قال: أخبرني ابن أبي مليكة، أن أبا عمرو ذكوان، مولى عائشة، أخبره أن عائشة كانت تقول: إن من نعم الله علي: أن رسول الله صلى الله عليه وسلم توفي في بيتي، وفي يومي، وبين سحري ونحري، وأن الله جمع بين ريقي وريقه عند موته: دخل علي عبد الرحمن، وبيده…", "4449"], ["باب مرض النبي صلى الله عليه وسلم ووفاته", "عن عائشة رضي الله عنها، أن رسول الله صلى الله عليه وسلم كان يسأل في مرضه الذي مات فيه، يقول: «أين أنا غدا، أين أنا غدا» يريد يوم عائشة، فأذن له أزواجه يكون حيث شاء، فكان في بيت عائشة حتى مات عندها، قالت عائشة: فمات في اليوم الذي كان يدور علي فيه، في بيتي، فقبضه الله وإن رأسه لبين نحري وسحري، وخالط…", "4450"], ["باب مرض النبي صلى الله عليه وسلم ووفاته", "عن عائشة رضي الله عنها، قالت: توفي النبي صلى الله عليه وسلم في بيتي، وفي يومي، وبين سحري ونحري، وكانت إحدانا تعوذه بدعاء إذا مرض، فذهبت أعوذه، فرفع رأسه إلى السماء، وقال: «في الرفيق الأعلى، في الرفيق الأعلى»، ومر عبد الرحمن بن أبي بكر وفي يده جريدة رطبة، فنظر إليه النبي صلى الله عليه وسلم، فظننت أن…", "4451"], ["باب مرض النبي صلى الله عليه وسلم ووفاته", "حدثنا يحيى بن بكير، حدثنا الليث، عن عقيل، عن ابن شهاب، قال: أخبرني أبو سلمة، أن عائشة ، أخبرته: أن أبا بكر رضي الله عنه أقبل على فرس من مسكنه بالسنح، حتى نزل فدخل المسجد، فلم يكلم الناس حتى دخل على عائشة، فتيمم رسول الله صلى الله عليه وسلم وهو مغشى بثوب حبرة، فكشف عن وجهه ثم أكب عليه فقبله وبكى، ثم…", "4452 و4453"], ["باب مرض النبي صلى الله عليه وسلم ووفاته", "قال الزهري: وحدثني أبو سلمة، عن عبد الله بن عباس، أن أبا بكر خرج وعمر يكلم الناس فقال: اجلس يا عمر، فأبى عمر أن يجلس، فأقبل الناس إليه، وتركوا عمر، فقال أبو بكر: \" أما بعد من كان منكم يعبد محمدا صلى الله عليه وسلم، فإن محمدا قد مات، ومن كان منكم يعبد الله فإن الله حي لا يموت، قال الله: ﴿وما محمد…", "4454"], ["باب مرض النبي صلى الله عليه وسلم ووفاته", "حدثني عبد الله بن أبي شيبة، حدثنا يحيى بن سعيد، عن سفيان، عن موسى بن أبي عائشة، عن عبيد الله بن عبد الله بن عتبة، عن عائشة، وابن عباس أن أبا بكر رضي الله عنه «قبل النبي صلى الله عليه وسلم بعد موته»", "4455 و4456 و4457"], ["باب مرض النبي صلى الله عليه وسلم ووفاته", "حدثنا علي، حدثنا يحيى، وزاد قالت عائشة: لددناه في مرضه فجعل يشير إلينا: «أن لا تلدوني» فقلنا كراهية المريض للدواء، فلما أفاق قال: «ألم أنهكم أن تلدوني»، قلنا كراهية المريض للدواء، فقال: «لا يبقى أحد في البيت إلا لد وأنا أنظر إلا العباس فإنه لم يشهدكم» رواه ابن أبي الزناد، عن هشام، عن أبيه، عن…", "4458"], ["باب مرض النبي صلى الله عليه وسلم ووفاته", "حدثنا عبد الله بن محمد، أخبرنا أزهر، أخبرنا ابن عون، عن إبراهيم، عن الأسود، قال: ذكر عند عائشة أن النبي صلى الله عليه وسلم أوصى إلى علي، فقالت: من قاله؟ «لقد رأيت النبي صلى الله عليه وسلم وإني لمسندته إلى صدري فدعا بالطست، فانخنث فمات فما شعرت فكيف أوصى إلى علي؟»", "4459"], ["باب مرض النبي صلى الله عليه وسلم ووفاته", "حدثنا أبو نعيم، حدثنا مالك بن مغول، عن طلحة، قال: سألت عبد الله بن أبي أوفى رضي الله عنهما أوصى النبي صلى الله عليه وسلم؟ فقال: لا، فقلت: كيف كتب على الناس الوصية، أو أمروا بها؟ قال: «أوصى بكتاب الله»", "4460"], ["باب مرض النبي صلى الله عليه وسلم ووفاته", "حدثنا قتيبة، حدثنا أبو الأحوص، عن أبي إسحاق، عن عمرو بن الحارث، قال: «ما ترك رسول الله صلى الله عليه وسلم دينارا، ولا درهما، ولا عبدا، ولا أمة، إلا بغلته البيضاء التي كان يركبها، وسلاحه، وأرضا جعلها لابن السبيل صدقة»", "4461"], ["باب مرض النبي صلى الله عليه وسلم ووفاته", "حدثنا سليمان بن حرب، حدثنا حماد، عن ثابت، عن أنس، قال: لما ثقل النبي صلى الله عليه وسلم جعل يتغشاه، فقالت فاطمة عليها السلام: وا كرب أباه، فقال لها: «ليس على أبيك كرب بعد اليوم»، فلما مات قالت: يا أبتاه، أجاب ربا دعاه، يا أبتاه، من جنة الفردوس، مأواه يا أبتاه إلى جبريل ننعاه، فلما دفن، قالت فاطمة…", "4462"], ["باب آخر ما تكلم النبي صلى الله عليه وسلم", "حدثنا بشر بن محمد، حدثنا عبد الله، قال يونس: قال الزهري: أخبرني سعيد بن المسيب، في رجال من أهل العلم: أن عائشة قالت: كان النبي صلى الله عليه وسلم يقول وهو صحيح: «إنه لم يقبض نبي حتى يرى مقعده من الجنة، ثم يخير» فلما نزل به، ورأسه على فخذي غشي عليه، ثم أفاق فأشخص بصره إلى سقف البيت، ثم قال: «اللهم…", "4463"], ["باب وفاة النبي صلى الله عليه وسلم", "حدثنا أبو نعيم، حدثنا شيبان، عن يحيى، عن أبي سلمة، عن عائشة، وابن عباس رضي الله عنهم: «أن النبي صلى الله عليه وسلم لبث بمكة عشر سنين، ينزل عليه القرآن وبالمدينة عشرا»", "4464 و4465"], ["باب وفاة النبي صلى الله عليه وسلم", "عن عائشة رضي الله عنها: «أن رسول الله صلى الله عليه وسلم توفي وهو ابن ثلاث وستين» قال ابن شهاب: وأخبرني سعيد بن المسيب مثله", "4466"], ["باب وفاة النبي صلى الله عليه وسلم", "عن عائشة رضي الله عنها، قالت: «توفي النبي صلى الله عليه وسلم ودرعه مرهونة عند يهودي بثلاثين»", "4467"], ["باب بعث النبي صلى الله عليه وسلم أسامة بن زيد رضي الله عنهما، في مرضه الذي توفي فيه", "حدثنا أبو عاصم الضحاك بن مخلد، عن الفضيل بن سليمان، حدثنا موسى بن عقبة، عن سالم، عن أبيه، استعمل النبي صلى الله عليه وسلم أسامة، فقالوا فيه: فقال النبي صلى الله عليه وسلم: «قد بلغني أنكم قلتم في أسامة وإنه أحب الناس إلي»", "4468"], ["باب بعث النبي صلى الله عليه وسلم أسامة بن زيد رضي الله عنهما، في مرضه الذي توفي فيه", "عن عبد الله بن عمر رضي الله عنهما، أن رسول الله صلى الله عليه وسلم بعث بعثا، وأمر عليهم أسامة بن زيد، فطعن الناس في إمارته، فقام رسول الله صلى الله عليه وسلم فقال: «إن تطعنوا في إمارته فقد كنتم تطعنون في إمارة أبيه من قبل، وايم الله إن كان لخليقا للإمارة، وإن كان لمن أحب الناس إلي، وإن هذا لمن أحب…", "4469"], ["باب بعث النبي صلى الله عليه وسلم أسامة بن زيد رضي الله عنهما، في مرضه الذي توفي فيه", "حدثنا أصبغ، قال: أخبرني ابن وهب، قال: أخبرني عمرو، عن ابن أبي حبيب، عن أبي الخير، عن الصنابحي، أنه قال له: متى هاجرت؟ قال: خرجنا من اليمن مهاجرين، فقدمنا الجحفة، فأقبل راكب، فقلت له: الخبر؟ فقال: «دفنا النبي صلى الله عليه وسلم منذ خمس»، قلت: هل سمعت في ليلة القدر شيئا؟ قال: نعم، أخبرني بلال مؤذن…", "4470"], ["باب: كم غزا النبي صلى الله عليه وسلم؟", "حدثنا عبد الله بن رجاء، حدثنا إسرائيل، عن أبي إسحاق، قال: سألت زيد بن أرقم رضي الله عنه: كم غزوت مع رسول الله صلى الله عليه وسلم؟ قال: سبع عشرة، قلت: \" كم غزا النبي صلى الله عليه وسلم؟ قال: تسع عشرة \"", "4471"], ["باب: كم غزا النبي صلى الله عليه وسلم؟", "عن البراء رضي الله عنه، قال: «غزوت مع النبي صلى الله عليه وسلم خمس عشرة»", "4472"], ["باب: كم غزا النبي صلى الله عليه وسلم؟", "حدثني أحمد بن الحسن، حدثنا أحمد بن محمد بن حنبل بن هلال، حدثنا معتمر بن سليمان، عن كهمس، عن ابن بريدة، عن أبيه، قال: «غزا مع رسول الله صلى الله عليه وسلم ست عشرة غزوة»", "4473"]];
